CREATE OR REPLACE FUNCTION "inventory"."add_test_stock"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN inventory.insert_stock_movement(
        p_tenant_id => p_tenant_id,
        p_catalog_item_id => p_catalog_item_id,
        p_location_id => p_location_id,
        p_quantity_delta => p_qty,
        p_movement_type => 'received',
        p_source_ref_type => 'test_data',
        p_source_ref_id => NULL,
        p_unit_cost => 10.00,
        p_reason => 'Test data',
        p_notes => 'Generated by test helper',
        p_correlation_id => NULL,
        p_occurred_at => NOW(),
        p_created_by_user_id => NULL,
        p_last_event_id => 'test_stock_' || gen_random_uuid()::TEXT
    );
END;
$$;


ALTER FUNCTION "inventory"."add_test_stock"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."auto_inject_tenant_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  jwt_tenant_id uuid;
BEGIN
  jwt_tenant_id := (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid;

  IF jwt_tenant_id IS NULL THEN
    jwt_tenant_id := (auth.jwt() -> 'app_metadata' ->> 'tenantId')::uuid;
  END IF;

  IF jwt_tenant_id IS NULL THEN
    jwt_tenant_id := (auth.jwt() ->> 'tenant_id')::uuid;
  END IF;

  IF jwt_tenant_id IS NULL THEN
    IF NEW.tenant_id IS NULL THEN
      RAISE EXCEPTION 'tenant_id is required when using service role';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.tenant_id IS NOT NULL AND NEW.tenant_id != jwt_tenant_id THEN
    RAISE WARNING 'Attempted to insert with tenant_id=% but JWT has tenant_id=%. Using JWT value.',
      NEW.tenant_id, jwt_tenant_id;
  END IF;

  NEW.tenant_id := jwt_tenant_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."auto_inject_tenant_id"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."auto_inject_tenant_id"() IS 'SECURITY: Auto-injects tenant_id from JWT on INSERT (supports both app_metadata and root paths). Prevents cross-tenant data insertion.';



CREATE OR REPLACE FUNCTION "inventory"."check_variance_approval"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_item_category_id" "uuid", "p_variance_qty" numeric, "p_expected_qty" numeric) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_threshold RECORD;
    v_variance_pct NUMERIC;
BEGIN
    -- Calculate variance percentage
    IF p_expected_qty = 0 THEN
        v_variance_pct := NULL;
    ELSE
        v_variance_pct := ABS((p_variance_qty / p_expected_qty) * 100);
    END IF;
    
    -- Find most specific threshold (priority order)
    SELECT * INTO v_threshold
    FROM inventory.cycle_count_variance_thresholds
    WHERE tenant_id = p_tenant_id
    AND (catalog_item_id = p_catalog_item_id OR catalog_item_id IS NULL)
    AND (location_id = p_location_id OR location_id IS NULL)
    AND (item_category_id = p_item_category_id OR item_category_id IS NULL)
    ORDER BY priority ASC
    LIMIT 1;
    
    -- If no threshold found, require approval for any variance
    IF NOT FOUND THEN
        RETURN (p_variance_qty != 0);
    END IF;
    
    -- Check thresholds
    IF v_threshold.max_variance_qty IS NOT NULL AND ABS(p_variance_qty) > v_threshold.max_variance_qty THEN
        RETURN TRUE;
    END IF;
    
    IF v_threshold.max_variance_pct IS NOT NULL AND v_variance_pct IS NOT NULL 
       AND v_variance_pct > v_threshold.max_variance_pct THEN
        RETURN TRUE;
    END IF;
    
    RETURN FALSE;
END;
$$;


ALTER FUNCTION "inventory"."check_variance_approval"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_item_category_id" "uuid", "p_variance_qty" numeric, "p_expected_qty" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."check_variance_approval"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_item_category_id" "uuid", "p_variance_qty" numeric, "p_expected_qty" numeric) IS 'Determines if variance requires approval based on thresholds';



CREATE OR REPLACE FUNCTION "inventory"."create_cycle_count_snapshot"("p_cycle_count_id" "uuid", "p_tenant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_location_id UUID;
    v_scope_path TEXT;
    v_count_type TEXT;
    v_snapshot_time TIMESTAMPTZ;
    v_skus_inserted INTEGER := 0;
    v_assets_inserted INTEGER := 0;
    v_result JSONB;
BEGIN
    -- Get cycle count details
    SELECT location_id, scope_path, count_type, NOW()
    INTO v_location_id, v_scope_path, v_count_type, v_snapshot_time
    FROM inventory.cycle_counts
    WHERE id = p_cycle_count_id AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cycle count % not found for tenant %', p_cycle_count_id, p_tenant_id;
    END IF;
    
    -- Update cycle count with snapshot time
    UPDATE inventory.cycle_counts
    SET snapshot_at = v_snapshot_time,
        status = 'in_progress',
        started_at = COALESCE(started_at, v_snapshot_time)
    WHERE id = p_cycle_count_id AND tenant_id = p_tenant_id;
    
    -- Snapshot SKUs (fungible items)
    -- For now, snapshot all items at the location
    -- TODO: Filter by scope_path if needed, handle partial counts
    INSERT INTO inventory.cycle_count_snapshot_skus (
        tenant_id, cycle_count_id, catalog_item_id, location_id, 
        expected_qty, snapshot_at
    )
    SELECT 
        sb.tenant_id,
        p_cycle_count_id,
        sb.catalog_item_id,
        sb.location_id,
        sb.qty_on_hand,
        v_snapshot_time
    FROM inventory.stock_balances sb
    INNER JOIN inventory.catalog_items ci ON ci.id = sb.catalog_item_id AND ci.tenant_id = sb.tenant_id
    WHERE sb.tenant_id = p_tenant_id
        AND sb.location_id = v_location_id
        AND ci.tracking_mode IN ('stock', 'both')
        AND sb.qty_on_hand > 0
    ON CONFLICT (cycle_count_id, catalog_item_id, location_id) DO NOTHING;
    
    GET DIAGNOSTICS v_skus_inserted = ROW_COUNT;
    
    -- Snapshot Assets (serialized items)
    -- Capture all assets currently at the location
    INSERT INTO inventory.cycle_count_snapshot_assets (
        tenant_id, cycle_count_id, asset_id, expected_location_id, 
        expected_status, snapshot_at
    )
    SELECT 
        a.tenant_id,
        p_cycle_count_id,
        a.id,
        a.location_id,
        a.status,
        v_snapshot_time
    FROM inventory.assets a
    INNER JOIN inventory.catalog_items ci ON ci.id = a.catalog_item_id AND ci.tenant_id = a.tenant_id
    WHERE a.tenant_id = p_tenant_id
        AND a.location_id = v_location_id
        AND ci.tracking_mode IN ('serialized', 'both')
        AND a.status IN ('available', 'assigned')
    ON CONFLICT (cycle_count_id, asset_id) DO NOTHING;
    
    GET DIAGNOSTICS v_assets_inserted = ROW_COUNT;
    
    -- Build result
    v_result := jsonb_build_object(
        'cycle_count_id', p_cycle_count_id,
        'snapshot_at', v_snapshot_time,
        'skus_snapshotted', v_skus_inserted,
        'assets_snapshotted', v_assets_inserted
    );
    
    RAISE NOTICE 'Snapshot created: % SKUs, % assets', v_skus_inserted, v_assets_inserted;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "inventory"."create_cycle_count_snapshot"("p_cycle_count_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."create_cycle_count_snapshot"("p_cycle_count_id" "uuid", "p_tenant_id" "uuid") IS 'Creates snapshot of expected inventory state for a cycle count. Captures SKUs from stock_balances and assets from assets table at current moment.';



CREATE OR REPLACE FUNCTION "inventory"."create_test_item"("p_tenant_id" "uuid", "p_sku" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text", "p_item_type" "text" DEFAULT 'stock'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_item_id UUID;
    v_sku TEXT;
    v_name TEXT;
BEGIN
    v_sku := COALESCE(p_sku, 'TEST-' || substring(gen_random_uuid()::TEXT from 1 for 8));
    v_name := COALESCE(p_name, 'Test Item ' || v_sku);
    
    INSERT INTO inventory.catalog_items (
        tenant_id,
        sku,
        name,
        item_type,
        last_event_id
    )
    VALUES (
        p_tenant_id,
        v_sku,
        v_name,
        p_item_type,
        'test_item_' || gen_random_uuid()::TEXT
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_item_id;
    
    IF v_item_id IS NULL THEN
        SELECT id INTO v_item_id
        FROM inventory.catalog_items
        WHERE tenant_id = p_tenant_id
        AND sku = v_sku
        LIMIT 1;
    END IF;
    
    RETURN v_item_id;
END;
$$;


ALTER FUNCTION "inventory"."create_test_item"("p_tenant_id" "uuid", "p_sku" "text", "p_name" "text", "p_item_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."create_test_location"("p_tenant_id" "uuid", "p_location_name" "text" DEFAULT 'Test Warehouse'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_location_id UUID;
BEGIN
    INSERT INTO inventory.locations (
        tenant_id, 
        name, 
        location_type, 
        last_event_id
    )
    VALUES (
        p_tenant_id,
        p_location_name,
        'warehouse',
        'test_location_' || gen_random_uuid()::TEXT
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_location_id;
    
    IF v_location_id IS NULL THEN
        SELECT id INTO v_location_id
        FROM inventory.locations
        WHERE tenant_id = p_tenant_id
        AND name = p_location_name
        LIMIT 1;
    END IF;
    
    RETURN v_location_id;
END;
$$;


ALTER FUNCTION "inventory"."create_test_location"("p_tenant_id" "uuid", "p_location_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."create_test_tenant"("p_tenant_name" "text" DEFAULT 'Test Tenant'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
BEGIN
    INSERT INTO public.tenants (name, last_event_id)
    VALUES (p_tenant_name, 'test_tenant_' || gen_random_uuid()::TEXT)
    ON CONFLICT (last_event_id) DO NOTHING
    RETURNING id INTO v_tenant_id;
    
    IF v_tenant_id IS NULL THEN
        SELECT id INTO v_tenant_id
        FROM public.tenants
        WHERE name = p_tenant_name
        LIMIT 1;
    END IF;
    
    RETURN v_tenant_id;
END;
$$;


ALTER FUNCTION "inventory"."create_test_tenant"("p_tenant_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."detect_movements_since_snapshot"("p_cycle_count_id" "uuid", "p_tenant_id" "uuid") RETURNS TABLE("movement_id" "uuid", "catalog_item_id" "uuid", "location_id" "uuid", "quantity_delta" numeric, "movement_type" "text", "occurred_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_snapshot_at TIMESTAMPTZ;
    v_location_id UUID;
BEGIN
    -- Get snapshot time and location
    SELECT snapshot_at, location_id
    INTO v_snapshot_at, v_location_id
    FROM inventory.cycle_counts
    WHERE id = p_cycle_count_id AND tenant_id = p_tenant_id;
    
    IF v_snapshot_at IS NULL THEN
        RAISE EXCEPTION 'Cycle count % has no snapshot', p_cycle_count_id;
    END IF;
    
    -- Return movements in scope after snapshot
    RETURN QUERY
    SELECT 
        sm.id,
        sm.catalog_item_id,
        sm.location_id,
        sm.quantity_delta,
        sm.movement_type,
        sm.occurred_at
    FROM inventory.stock_movements sm
    WHERE sm.tenant_id = p_tenant_id
        AND sm.location_id = v_location_id
        AND sm.occurred_at > v_snapshot_at
        AND sm.posting_status = 'posted'
    ORDER BY sm.occurred_at DESC;
END;
$$;


ALTER FUNCTION "inventory"."detect_movements_since_snapshot"("p_cycle_count_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."detect_movements_since_snapshot"("p_cycle_count_id" "uuid", "p_tenant_id" "uuid") IS 'Returns list of stock movements that occurred in cycle count scope after snapshot was captured. Used to detect conflicts.';



CREATE OR REPLACE FUNCTION "inventory"."emit_abc_classification_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Emit event when classification changes
  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.classification != NEW.classification) THEN
    INSERT INTO inventory.events_outbox (
      event_id,
      tenant_id,
      event_type,
      aggregate_type,
      aggregate_id,
      payload,
      status
    ) VALUES (
      gen_random_uuid(),
      NEW.tenant_id,
      CASE TG_OP
        WHEN 'INSERT' THEN 'abc_classification_created'
        WHEN 'UPDATE' THEN 'abc_classification_changed'
      END,
      'catalog_item',
      NEW.catalog_item_id,
      jsonb_build_object(
        'catalog_item_id', NEW.catalog_item_id,
        'classification', NEW.classification,
        'old_classification', CASE WHEN TG_OP = 'UPDATE' THEN OLD.classification ELSE NULL END,
        'annual_usage_value', NEW.annual_usage_value,
        'cumulative_value_pct', NEW.cumulative_value_pct,
        'classification_method', NEW.classification_method,
        'analysis_period', jsonb_build_object(
          'start', NEW.analysis_start_date,
          'end', NEW.analysis_end_date
        )
      ),
      'pending'
    );
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_abc_classification_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."emit_abc_classification_event"() IS 'Emits ABC classification events to events_outbox when items are classified or reclassified';



CREATE OR REPLACE FUNCTION "inventory"."emit_asset_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_name TEXT;
    v_payload JSONB;
    v_changes JSONB;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_event_name := 'asset.created';
        v_payload := jsonb_build_object(
            'asset_id', NEW.id,
            'asset_tag', NEW.asset_tag,
            'catalog_item_id', NEW.catalog_item_id,
            'status', NEW.status,
            'home_location_id', NEW.home_location_id,
            'tenant_id', NEW.tenant_id,
            'created_at', NEW.created_at
        );
    ELSIF TG_OP = 'UPDATE' THEN
        IF NEW.status = 'retired' AND OLD.status != 'retired' THEN
            v_event_name := 'asset.retired';
            v_payload := jsonb_build_object(
                'asset_id', NEW.id,
                'asset_tag', NEW.asset_tag,
                'tenant_id', NEW.tenant_id,
                'retired_at', NEW.updated_at
            );
        ELSE
            v_event_name := 'asset.updated';
            v_changes := jsonb_build_object();
            
            IF OLD.status != NEW.status THEN
                v_changes := v_changes || jsonb_build_object('status', jsonb_build_object('old', OLD.status, 'new', NEW.status));
            END IF;
            IF OLD.home_location_id IS DISTINCT FROM NEW.home_location_id THEN
                v_changes := v_changes || jsonb_build_object('home_location_id', jsonb_build_object('old', OLD.home_location_id, 'new', NEW.home_location_id));
            END IF;
            
            v_payload := jsonb_build_object(
                'asset_id', NEW.id,
                'tenant_id', NEW.tenant_id,
                'changes', v_changes,
                'updated_at', NEW.updated_at
            );
        END IF;
    END IF;
    
    PERFORM public.emit_event(
        p_type := v_event_name,
        p_payload := v_payload,
        p_tenant_id := NEW.tenant_id
    );
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_asset_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."emit_catalog_item_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_name TEXT;
    v_payload JSONB;
    v_changes JSONB;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_event_name := 'inventory.item.created';
        v_payload := jsonb_build_object(
            'item_id', NEW.id,
            'sku', NEW.sku,
            'name', NEW.name,
            'category_id', NEW.category_id,
            'tracking_mode', NEW.tracking_mode,
            'unit_of_measure', NEW.unit_of_measure,
            'tenant_id', NEW.tenant_id,
            'created_at', NEW.created_at
        );
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.active = TRUE AND NEW.active = FALSE THEN
            v_event_name := 'catalog_item.deactivated';
            v_payload := jsonb_build_object(
                'item_id', NEW.id,
                'tenant_id', NEW.tenant_id,
                'deactivated_at', NEW.updated_at
            );
        ELSIF OLD.active = FALSE AND NEW.active = TRUE THEN
            v_event_name := 'catalog_item.reactivated';
            v_payload := jsonb_build_object(
                'item_id', NEW.id,
                'tenant_id', NEW.tenant_id,
                'reactivated_at', NEW.updated_at
            );
        ELSE
            v_event_name := 'catalog_item.updated';
            v_changes := jsonb_build_object();

            IF OLD.name != NEW.name THEN
                v_changes := v_changes || jsonb_build_object('name', jsonb_build_object('old', OLD.name, 'new', NEW.name));
            END IF;
            IF OLD.sku != NEW.sku THEN
                v_changes := v_changes || jsonb_build_object('sku', jsonb_build_object('old', OLD.sku, 'new', NEW.sku));
            END IF;
            IF OLD.unit_of_measure IS DISTINCT FROM NEW.unit_of_measure THEN
                v_changes := v_changes || jsonb_build_object('unit_of_measure', jsonb_build_object('old', OLD.unit_of_measure, 'new', NEW.unit_of_measure));
            END IF;
            IF OLD.category_id IS DISTINCT FROM NEW.category_id THEN
                v_changes := v_changes || jsonb_build_object('category_id', jsonb_build_object('old', OLD.category_id, 'new', NEW.category_id));
            END IF;

            v_payload := jsonb_build_object(
                'item_id', NEW.id,
                'tenant_id', NEW.tenant_id,
                'changes', v_changes,
                'updated_at', NEW.updated_at
            );
        END IF;
    END IF;

    PERFORM public.emit_event(
        p_type := v_event_name,
        p_payload := v_payload,
        p_tenant_id := NEW.tenant_id
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_catalog_item_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."emit_catalog_item_event"() IS 'Emits events when catalog items are created or updated - uses unit_of_measure column';



CREATE OR REPLACE FUNCTION "inventory"."emit_category_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_name TEXT;
    v_payload JSONB;
    v_changes JSONB;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_event_name := 'category.created';
        v_payload := jsonb_build_object(
            'category_id', NEW.id,
            'name', NEW.name,
            'tenant_id', NEW.tenant_id,
            'created_at', NEW.created_at
        );
    ELSIF TG_OP = 'UPDATE' THEN
        v_event_name := 'category.updated';
        v_changes := jsonb_build_object();
        
        IF OLD.name != NEW.name THEN
            v_changes := v_changes || jsonb_build_object('name', jsonb_build_object('old', OLD.name, 'new', NEW.name));
        END IF;
        
        v_payload := jsonb_build_object(
            'category_id', NEW.id,
            'tenant_id', NEW.tenant_id,
            'changes', v_changes,
            'updated_at', NEW.updated_at
        );
    END IF;
    
    PERFORM public.emit_event(
        v_event_name,
        v_payload,
        NEW.tenant_id
    );
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_category_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."emit_cycle_count_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Emit event when cycle count is created
    IF TG_OP = 'INSERT' THEN
        PERFORM inventory.publish_event(
            p_tenant_id := NEW.tenant_id,
            p_scope := 'tenant',
            p_event_type := 'inventory.cycle_count.created',
            p_aggregate_type := 'cycle_count',
            p_aggregate_id := NEW.id,
            p_payload := to_jsonb(NEW),
            p_metadata := jsonb_build_object(
                'location_id', NEW.location_id,
                'count_date', NEW.count_date
            )
        );
    END IF;
    
    -- Note: Cycle counts table structure needs verification
    -- If status column exists, add status change event here
    
    RETURN NEW;
END;
$$;


