CREATE OR REPLACE FUNCTION "inventory"."emit_location_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_name TEXT;
    v_payload JSONB;
    v_changes JSONB;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_event_name := 'location.created';
        v_payload := jsonb_build_object(
            'location_id', NEW.id,
            'location_type_id', NEW.location_type_id,
            'name', NEW.name,
            'parent_location_id', NEW.parent_location_id,
            'address', NEW.address,
            'external_ref', NEW.external_ref,
            'tenant_id', NEW.tenant_id,
            'created_at', NEW.created_at,
            'created_by', NEW.created_by
        );
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.active = TRUE AND NEW.active = FALSE THEN
            v_event_name := 'location.deactivated';
            v_payload := jsonb_build_object(
                'location_id', NEW.id,
                'tenant_id', NEW.tenant_id,
                'deactivated_at', NEW.updated_at,
                'deactivated_by', NEW.updated_by
            );
        ELSE
            v_event_name := 'location.updated';
            v_changes := jsonb_build_object();
            
            IF OLD.name != NEW.name THEN
                v_changes := v_changes || jsonb_build_object('name', jsonb_build_object('old', OLD.name, 'new', NEW.name));
            END IF;
            
            IF OLD.location_type_id != NEW.location_type_id THEN
                v_changes := v_changes || jsonb_build_object('location_type_id', jsonb_build_object('old', OLD.location_type_id, 'new', NEW.location_type_id));
            END IF;
            
            IF (OLD.parent_location_id IS DISTINCT FROM NEW.parent_location_id) THEN
                v_changes := v_changes || jsonb_build_object('parent_location_id', jsonb_build_object('old', OLD.parent_location_id, 'new', NEW.parent_location_id));
            END IF;
            
            IF (OLD.address IS DISTINCT FROM NEW.address) THEN
                v_changes := v_changes || jsonb_build_object('address', jsonb_build_object('old', OLD.address, 'new', NEW.address));
            END IF;
            
            v_payload := jsonb_build_object(
                'location_id', NEW.id,
                'tenant_id', NEW.tenant_id,
                'changes', v_changes,
                'updated_at', NEW.updated_at,
                'updated_by', NEW.updated_by
            );
        END IF;
    END IF;
    
    PERFORM public.emit_event(
        p_type := v_event_name,
        p_payload := v_payload,
        p_tenant_id := NEW.tenant_id
    );
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_location_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."emit_location_event"() IS 'Emits events when locations are created, updated, or deactivated. Updated to use location_type_id instead of deprecated location_type column.';



CREATE OR REPLACE FUNCTION "inventory"."emit_reorder_alert_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Only emit events for new alerts or status changes
  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.status != NEW.status) THEN
    INSERT INTO inventory.events_outbox (
      event_id,
      tenant_id,
      event_type,
      aggregate_type,
      aggregate_id,
      payload,
      status
    ) VALUES (
      gen_random_uuid(),
      NEW.tenant_id,
      CASE TG_OP
        WHEN 'INSERT' THEN 'reorder_alert_created'
        WHEN 'UPDATE' THEN 'reorder_alert_status_changed'
      END,
      'reorder_alert',
      NEW.id,
      jsonb_build_object(
        'alert_id', NEW.id,
        'catalog_item_id', NEW.catalog_item_id,
        'location_id', NEW.location_id,
        'alert_type', NEW.alert_type,
        'priority', NEW.priority,
        'status', NEW.status,
        'current_qty', NEW.current_qty,
        'reorder_point', NEW.reorder_point,
        'suggested_order_qty', NEW.suggested_order_qty,
        'old_status', CASE WHEN TG_OP = 'UPDATE' THEN OLD.status ELSE NULL END
      ),
      'pending'
    );
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_reorder_alert_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."emit_reorder_alert_event"() IS 'Emits reorder alert events to events_outbox when alerts are created or status changes';



CREATE OR REPLACE FUNCTION "inventory"."emit_stock_movement_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_event_name text;
  v_payload jsonb;
  v_actor_user_id uuid;
BEGIN
  IF NEW.created_by_user_id IS NOT NULL THEN
    SELECT id INTO v_actor_user_id
    FROM auth.users
    WHERE id = NEW.created_by_user_id;
  END IF;

  CASE NEW.movement_type
    WHEN 'received' THEN
      v_event_name := 'stock.replenished';
      v_payload := jsonb_build_object(
        'movement_id', NEW.id,
        'item_id', NEW.catalog_item_id,
        'location_id', NEW.location_id,
        'quantity_delta', NEW.quantity_delta,
        'source_ref_type', NEW.source_ref_type,
        'source_ref_id', NEW.source_ref_id,
        'tenant_id', NEW.tenant_id,
        'occurred_at', NEW.occurred_at
      );
    WHEN 'issued' THEN
      v_event_name := 'stock.issued';
      v_payload := jsonb_build_object(
        'movement_id', NEW.id,
        'item_id', NEW.catalog_item_id,
        'location_id', NEW.location_id,
        'quantity_delta', NEW.quantity_delta,
        'tenant_id', NEW.tenant_id,
        'occurred_at', NEW.occurred_at
      );
    WHEN 'returned' THEN
      v_event_name := 'stock.returned';
      v_payload := jsonb_build_object(
        'movement_id', NEW.id,
        'item_id', NEW.catalog_item_id,
        'location_id', NEW.location_id,
        'quantity_delta', NEW.quantity_delta,
        'tenant_id', NEW.tenant_id,
        'occurred_at', NEW.occurred_at
      );
    WHEN 'transferred_in', 'transferred_out' THEN
      v_event_name := 'stock.transferred';
      v_payload := jsonb_build_object(
        'movement_id', NEW.id,
        'item_id', NEW.catalog_item_id,
        'location_id', NEW.location_id,
        'quantity_delta', NEW.quantity_delta,
        'correlation_id', NEW.correlation_id,
        'tenant_id', NEW.tenant_id,
        'occurred_at', NEW.occurred_at
      );
    ELSE
      v_event_name := 'stock.adjusted';
      v_payload := jsonb_build_object(
        'movement_id', NEW.id,
        'item_id', NEW.catalog_item_id,
        'location_id', NEW.location_id,
        'quantity_delta', NEW.quantity_delta,
        'movement_type', NEW.movement_type,
        'tenant_id', NEW.tenant_id,
        'occurred_at', NEW.occurred_at
      );
  END CASE;

  PERFORM public.emit_event(
    p_type => v_event_name,
    p_payload => v_payload,
    p_tenant_id => NEW.tenant_id,
    p_actor_id => v_actor_user_id,
    p_trace_id => NULL,
    p_correlation_id => NEW.correlation_id,
    p_aggregate_id => NEW.id
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_stock_movement_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."emit_stock_movement_event"() IS 'Emits events for stock movements (FIXED: uses catalog_item_id)';



CREATE OR REPLACE FUNCTION "inventory"."emit_stock_threshold_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_par_level record;
  v_payload jsonb;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.qty_on_hand < OLD.qty_on_hand THEN
    SELECT * INTO v_par_level
    FROM inventory.item_location_par_levels
    WHERE catalog_item_id = NEW.catalog_item_id
      AND location_id = NEW.location_id
      AND tenant_id = NEW.tenant_id;

    IF FOUND THEN
      IF OLD.qty_on_hand >= v_par_level.reorder_point AND NEW.qty_on_hand < v_par_level.reorder_point THEN
        v_payload := jsonb_build_object(
          'item_id', NEW.catalog_item_id,
          'location_id', NEW.location_id,
          'current_qty', NEW.qty_on_hand,
          'reorder_point', v_par_level.reorder_point,
          'reorder_qty', v_par_level.reorder_qty,
          'tenant_id', NEW.tenant_id,
          'detected_at', NOW()
        );

        PERFORM public.emit_event(
          p_type => 'stock.low_threshold_reached',
          p_payload => v_payload,
          p_tenant_id => NEW.tenant_id,
          p_actor_id => NULL,
          p_trace_id => NULL,
          p_correlation_id => NULL,
          p_aggregate_id => NEW.id
        );
      END IF;

      IF OLD.qty_on_hand > 0 AND NEW.qty_on_hand <= 0 THEN
        v_payload := jsonb_build_object(
          'item_id', NEW.catalog_item_id,
          'location_id', NEW.location_id,
          'previous_qty', OLD.qty_on_hand,
          'tenant_id', NEW.tenant_id,
          'occurred_at', NOW()
        );

        PERFORM public.emit_event(
          p_type => 'stock.out_of_stock',
          p_payload => v_payload,
          p_tenant_id => NEW.tenant_id,
          p_actor_id => NULL,
          p_trace_id => NULL,
          p_correlation_id => NULL,
          p_aggregate_id => NEW.id
        );
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_stock_threshold_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."expire_old_reservations"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE inventory.reservations
    SET 
        status = 'expired',
        updated_at = NOW()
    WHERE status = 'active'
    AND expiration_date IS NOT NULL
    AND expiration_date < CURRENT_DATE
    AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id);
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    
    RETURN v_count;
END;
$$;


