CREATE OR REPLACE FUNCTION "inventory"."generate_reorder_alerts"() RETURNS TABLE("alerts_created" integer, "alerts_updated" integer, "alerts_auto_dismissed" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_alerts_created INTEGER := 0;
  v_alerts_updated INTEGER := 0;
  v_alerts_dismissed INTEGER := 0;
  v_item RECORD;
  v_existing_alert_id UUID;
BEGIN
  -- Loop through items needing reorder
  FOR v_item IN 
    SELECT * FROM inventory.v_items_needing_reorder
  LOOP
    -- Check if alert already exists for this item/location
    SELECT id INTO v_existing_alert_id
    FROM inventory.reorder_alerts
    WHERE tenant_id = v_item.tenant_id
      AND catalog_item_id = v_item.catalog_item_id
      AND location_id = v_item.location_id
      AND status IN ('open', 'acknowledged')
    LIMIT 1;

    IF v_existing_alert_id IS NOT NULL THEN
      -- Update existing alert with current quantities
      UPDATE inventory.reorder_alerts
      SET
        alert_type = v_item.alert_type,
        current_qty = v_item.qty_available,
        priority = v_item.alert_priority,
        suggested_order_qty = v_item.suggested_order_qty,
        updated_at = now()
      WHERE id = v_existing_alert_id;
      
      v_alerts_updated := v_alerts_updated + 1;
    ELSE
      -- Create new alert
      INSERT INTO inventory.reorder_alerts (
        tenant_id,
        catalog_item_id,
        location_id,
        alert_type,
        current_qty,
        reorder_point,
        min_stock_level,
        target_level,
        suggested_order_qty,
        priority,
        status
      ) VALUES (
        v_item.tenant_id,
        v_item.catalog_item_id,
        v_item.location_id,
        v_item.alert_type,
        v_item.qty_available,
        v_item.reorder_point,
        v_item.min_stock_level,
        v_item.target_level,
        v_item.suggested_order_qty,
        v_item.alert_priority,
        'open'
      );
      
      v_alerts_created := v_alerts_created + 1;
    END IF;
  END LOOP;

  -- Auto-dismiss alerts for items that are now above reorder point
  WITH dismissed AS (
    UPDATE inventory.reorder_alerts ra
    SET 
      status = 'dismissed',
      dismissed_reason = 'Stock level restored above reorder point',
      dismissed_at = now(),
      updated_at = now()
    WHERE ra.status IN ('open', 'acknowledged')
      AND NOT EXISTS (
        SELECT 1 
        FROM inventory.v_items_needing_reorder inr
        WHERE inr.tenant_id = ra.tenant_id
          AND inr.catalog_item_id = ra.catalog_item_id
          AND inr.location_id = ra.location_id
      )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_alerts_dismissed FROM dismissed;

  RETURN QUERY SELECT v_alerts_created, v_alerts_updated, v_alerts_dismissed;
END;
$$;


ALTER FUNCTION "inventory"."generate_reorder_alerts"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."generate_reorder_alerts"() IS 'Scans stock levels and generates/updates reorder alerts. Auto-dismisses resolved alerts. Run via cron every hour.';



CREATE OR REPLACE FUNCTION "inventory"."get_failed_events"("p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "tenant_id" "uuid", "event_type" "text", "aggregate_type" "text", "aggregate_id" "uuid", "retry_count" integer, "last_error" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        e.id,
        e.tenant_id,
        e.event_type,
        e.aggregate_type,
        e.aggregate_id,
        e.retry_count,
        e.last_error,
        e.created_at
    FROM inventory.events_outbox e
    WHERE e.status = 'failed'
    AND (p_tenant_id IS NULL OR e.tenant_id = p_tenant_id)
    ORDER BY e.created_at DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "inventory"."get_failed_events"("p_tenant_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."get_failed_events"("p_tenant_id" "uuid", "p_limit" integer) IS 'Returns failed events for monitoring and debugging. Can be filtered by tenant_id.';



CREATE OR REPLACE FUNCTION "inventory"."get_outbox_stats"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("tenant_id" "uuid", "total_events" bigint, "pending_events" bigint, "published_events" bigint, "failed_events" bigint, "avg_processing_time_seconds" numeric, "oldest_pending_age_seconds" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        e.tenant_id,
        COUNT(*)::BIGINT AS total_events,
        COUNT(*) FILTER (WHERE e.status = 'pending')::BIGINT AS pending_events,
        COUNT(*) FILTER (WHERE e.status = 'published')::BIGINT AS published_events,
        COUNT(*) FILTER (WHERE e.status = 'failed')::BIGINT AS failed_events,
        AVG(EXTRACT(EPOCH FROM (e.published_at - e.created_at))) FILTER (WHERE e.published_at IS NOT NULL) AS avg_processing_time_seconds,
        EXTRACT(EPOCH FROM (NOW() - MIN(e.created_at) FILTER (WHERE e.status = 'pending'))) AS oldest_pending_age_seconds
    FROM inventory.events_outbox e
    WHERE p_tenant_id IS NULL OR e.tenant_id = p_tenant_id
    GROUP BY e.tenant_id;
END;
$$;


ALTER FUNCTION "inventory"."get_outbox_stats"("p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."get_outbox_stats"("p_tenant_id" "uuid") IS 'Returns statistics about outbox events for monitoring dashboards. Can be filtered by tenant_id.';



CREATE OR REPLACE FUNCTION "inventory"."get_substitutes"("p_item_id" "uuid", "p_tenant_id" "uuid") RETURNS TABLE("substitute_item_id" "uuid", "sku" "text", "name" "text", "priority" integer, "conversion_factor" numeric, "qty_available" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        s.substitute_item_id,
        ci.sku,
        ci.name,
        s.priority,
        s.conversion_factor,
        COALESCE(SUM(sb.qty_available), 0) as qty_available
    FROM inventory.item_substitutions s
    JOIN inventory.catalog_items ci ON ci.id = s.substitute_item_id
    LEFT JOIN inventory.stock_balances sb ON sb.catalog_item_id = s.substitute_item_id 
        AND sb.tenant_id = p_tenant_id
    WHERE s.item_id = p_item_id
    AND s.tenant_id = p_tenant_id
    AND s.active = TRUE
    GROUP BY s.substitute_item_id, ci.sku, ci.name, s.priority, s.conversion_factor
    ORDER BY s.priority ASC, qty_available DESC;
END;
$$;


ALTER FUNCTION "inventory"."get_substitutes"("p_item_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."get_substitutes"("p_item_id" "uuid", "p_tenant_id" "uuid") IS 'Returns active substitutes for an item, ordered by priority and availability';



CREATE OR REPLACE FUNCTION "inventory"."guard_device_secret_hash_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'inventory', 'public'
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF OLD.device_secret_hash IS NOT NULL
           AND NEW.device_secret_hash IS DISTINCT FROM OLD.device_secret_hash
           AND auth.role() <> 'service_role' THEN
            RAISE EXCEPTION 'device_secret_hash cannot be overwritten once set';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


