CREATE OR REPLACE FUNCTION "inventory"."insert_asset_event"("p_tenant_id" "uuid", "p_event_type" "text", "p_occurred_at" timestamp with time zone, "p_asset_id" "uuid", "p_actor_user_id" "uuid", "p_source_system" "text", "p_last_event_id" "text", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_id UUID;
BEGIN
    INSERT INTO inventory.asset_events (
        tenant_id,
        event_type,
        occurred_at,
        asset_id,
        actor_user_id,
        source_system,
        last_event_id,
        payload
    ) VALUES (
        p_tenant_id,
        p_event_type,
        p_occurred_at,
        p_asset_id,
        p_actor_user_id,
        p_source_system,
        p_last_event_id,
        p_payload
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_event_id;
    
    -- If conflict occurred, get existing event id
    IF v_event_id IS NULL THEN
        SELECT id INTO v_event_id
        FROM inventory.asset_events
        WHERE tenant_id = p_tenant_id AND last_event_id = p_last_event_id;
    END IF;
    
    RETURN v_event_id;
END;
$$;


