CREATE OR REPLACE FUNCTION "inventory"."insert_stock_movement"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_quantity_delta" numeric, "p_movement_type" "text", "p_source_ref_type" "text", "p_source_ref_id" "uuid", "p_unit_cost" numeric, "p_reason" "text", "p_notes" "text", "p_correlation_id" "uuid", "p_occurred_at" timestamp with time zone, "p_created_by_user_id" "uuid", "p_last_event_id" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_movement_id UUID;
BEGIN
    INSERT INTO inventory.stock_movements (
        tenant_id,
        catalog_item_id,
        location_id,
        quantity_delta,
        movement_type,
        source_ref_type,
        source_ref_id,
        unit_cost,
        reason,
        notes,
        correlation_id,
        occurred_at,
        created_by_user_id,
        last_event_id
    ) VALUES (
        p_tenant_id,
        p_catalog_item_id,
        p_location_id,
        p_quantity_delta,
        p_movement_type,
        p_source_ref_type,
        p_source_ref_id,
        p_unit_cost,
        p_reason,
        p_notes,
        p_correlation_id,
        p_occurred_at,
        p_created_by_user_id,
        p_last_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_movement_id;
    
    -- If conflict occurred, get existing movement id
    IF v_movement_id IS NULL THEN
        SELECT id INTO v_movement_id
        FROM inventory.stock_movements
        WHERE tenant_id = p_tenant_id AND last_event_id = p_last_event_id;
    END IF;
    
    RETURN v_movement_id;
END;
$$;


ALTER FUNCTION "inventory"."insert_stock_movement"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_quantity_delta" numeric, "p_movement_type" "text", "p_source_ref_type" "text", "p_source_ref_id" "uuid", "p_unit_cost" numeric, "p_reason" "text", "p_notes" "text", "p_correlation_id" "uuid", "p_occurred_at" timestamp with time zone, "p_created_by_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."insert_stock_movement"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_quantity_delta" numeric, "p_movement_type" "text", "p_source_ref_type" "text", "p_source_ref_id" "uuid", "p_unit_cost" numeric, "p_reason" "text", "p_notes" "text", "p_correlation_id" "uuid", "p_occurred_at" timestamp with time zone, "p_created_by_user_id" "uuid", "p_last_event_id" "text") IS 'Idempotently insert a stock movement with event deduplication';



CREATE OR REPLACE FUNCTION "inventory"."is_hazardous"("p_catalog_item_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_hazard_flags JSONB;
    v_key TEXT;
BEGIN
    SELECT hazard_flags INTO v_hazard_flags
    FROM inventory.catalog_items
    WHERE id = p_catalog_item_id;
    
    IF v_hazard_flags IS NULL OR v_hazard_flags = '{}' THEN
        RETURN FALSE;
    END IF;
    
    -- Check if any hazard flag is true
    FOR v_key IN SELECT jsonb_object_keys(v_hazard_flags)
    LOOP
        IF (v_hazard_flags->>v_key)::BOOLEAN = TRUE THEN
            RETURN TRUE;
        END IF;
    END LOOP;
    
    RETURN FALSE;
END;
$$;


ALTER FUNCTION "inventory"."is_hazardous"("p_catalog_item_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."is_hazardous"("p_catalog_item_id" "uuid") IS 'Returns true if catalog item has any hazard flags set to true';



CREATE OR REPLACE FUNCTION "inventory"."maintain_stock_balances"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Upsert stock_balances for this item/location combination
    -- On INSERT: Initialize with 0 and add delta
    -- On UPDATE: Add delta to existing qty_on_hand
    INSERT INTO inventory.stock_balances (
        tenant_id,
        catalog_item_id,
        location_id,
        qty_on_hand
    ) VALUES (
        NEW.tenant_id,
        NEW.catalog_item_id,
        NEW.location_id,
        GREATEST(0, NEW.quantity_delta) -- Initialize to 0 if delta is negative
    )
    ON CONFLICT (tenant_id, catalog_item_id, location_id)
    DO UPDATE SET
        qty_on_hand = inventory.stock_balances.qty_on_hand + NEW.quantity_delta,
        updated_at = NOW();
    
    -- If this would result in negative qty_on_hand after the upsert, raise error
    IF (SELECT qty_on_hand FROM inventory.stock_balances 
        WHERE tenant_id = NEW.tenant_id 
        AND catalog_item_id = NEW.catalog_item_id 
        AND location_id = NEW.location_id) < 0 THEN
        RAISE EXCEPTION 'Insufficient stock: Cannot deduct % units from location. This would result in negative inventory.', 
            ABS(NEW.quantity_delta);
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."maintain_stock_balances"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."maintain_stock_balances"() IS 'Automatically maintains stock_balances read model when stock_movements are inserted. Prevents negative inventory.';



CREATE OR REPLACE FUNCTION "inventory"."maintain_stock_reserved"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status = 'active' THEN
        -- Increase reserved quantity
        UPDATE inventory.stock_balances
        SET qty_reserved = qty_reserved + NEW.qty,
            updated_at = NOW()
        WHERE tenant_id = NEW.tenant_id
          AND catalog_item_id = NEW.catalog_item_id
          AND location_id = NEW.location_id;
          
        -- Create stock_balances record if it doesn't exist
        INSERT INTO inventory.stock_balances (
            tenant_id,
            catalog_item_id,
            location_id,
            qty_on_hand,
            qty_reserved
        ) VALUES (
            NEW.tenant_id,
            NEW.catalog_item_id,
            NEW.location_id,
            0,
            NEW.qty
        )
        ON CONFLICT (tenant_id, catalog_item_id, location_id) DO NOTHING;
        
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.status = 'active' AND NEW.status IN ('fulfilled', 'cancelled') THEN
            -- Decrease reserved quantity
            UPDATE inventory.stock_balances
            SET qty_reserved = GREATEST(0, qty_reserved - OLD.qty),
                updated_at = NOW()
            WHERE tenant_id = OLD.tenant_id
              AND catalog_item_id = OLD.catalog_item_id
              AND location_id = OLD.location_id;
        END IF;
        
    ELSIF TG_OP = 'DELETE' AND OLD.status = 'active' THEN
        -- Decrease reserved quantity on delete
        UPDATE inventory.stock_balances
        SET qty_reserved = GREATEST(0, qty_reserved - OLD.qty),
            updated_at = NOW()
        WHERE tenant_id = OLD.tenant_id
          AND catalog_item_id = OLD.catalog_item_id
          AND location_id = OLD.location_id;
    END IF;
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "inventory"."maintain_stock_reserved"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."maintain_stock_reserved"() IS 'Automatically maintains stock_balances.qty_reserved when reservations change';



CREATE OR REPLACE FUNCTION "inventory"."move_to_dead_letter"("p_event_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event RECORD;
BEGIN
    -- Fetch event from outbox
    SELECT * INTO v_event FROM inventory.events_outbox WHERE id = p_event_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Event % not found', p_event_id;
    END IF;

    -- Insert into DLQ
    INSERT INTO public.events_dead_letter (
        original_event_id,
        event_type,
        tenant_id,
        payload,
        created_at,
        final_error,
        total_attempts,
        original_metadata,
        original_scope,
        original_aggregate_type,
        original_aggregate_id,
        original_actor_user_id
    ) VALUES (
        v_event.id,
        v_event.event_type,
        v_event.tenant_id,
        v_event.payload,
        v_event.created_at,
        v_event.last_error,
        v_event.retry_count,
        v_event.metadata,
        v_event.scope,
        v_event.aggregate_type,
        v_event.aggregate_id,
        v_event.actor_user_id
    );

    -- Update status to 'dead' in outbox
    UPDATE inventory.events_outbox 
    SET status = 'dead', 
        locked_at = NULL, 
        locked_by = NULL
    WHERE id = p_event_id;

    RAISE NOTICE 'Event % moved to dead letter queue', p_event_id;
END;
$$;


ALTER FUNCTION "inventory"."move_to_dead_letter"("p_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."move_to_dead_letter"("p_event_id" "uuid") IS 'Moves failed event to dead letter queue after max retries';



CREATE OR REPLACE FUNCTION "inventory"."post_cycle_count_adjustments"("p_cycle_count_id" "uuid", "p_tenant_id" "uuid", "p_posted_by_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_count_status TEXT;
    v_posted_at TIMESTAMPTZ;
    v_correlation_id UUID;
    v_adjustments_created INTEGER := 0;
    v_lines_processed INTEGER := 0;
    v_result JSONB;
    v_line RECORD;
BEGIN
    -- Check if already posted (idempotency)
    SELECT status, posted_at
    INTO v_count_status, v_posted_at
    FROM inventory.cycle_counts
    WHERE id = p_cycle_count_id AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cycle count % not found', p_cycle_count_id;
    END IF;
    
    IF v_posted_at IS NOT NULL THEN
        RAISE NOTICE 'Cycle count % already posted at %', p_cycle_count_id, v_posted_at;
        RETURN jsonb_build_object(
            'success', TRUE,
            'message', 'Already posted',
            'posted_at', v_posted_at,
            'adjustments_created', 0
        );
    END IF;
    
    -- Verify status allows posting
    IF v_count_status NOT IN ('approved', 'under_review') THEN
        RAISE EXCEPTION 'Cannot post cycle count in status: %', v_count_status;
    END IF;
    
    -- Generate correlation ID for this posting batch
    v_correlation_id := gen_random_uuid();
    v_posted_at := NOW();
    
    -- Process SKU lines (fungible items)
    FOR v_line IN
        SELECT 
            ccl.id as line_id,
            ccl.catalog_item_id,
            ccl.location_id,
            ccl.variance
        FROM inventory.cycle_count_lines ccl
        WHERE ccl.cycle_count_id = p_cycle_count_id
            AND ccl.tenant_id = p_tenant_id
            AND ccl.variance IS NOT NULL
            AND ccl.variance <> 0
            AND ccl.posted_at IS NULL
    LOOP
        -- Create stock movement for adjustment
        INSERT INTO inventory.stock_movements (
            tenant_id,
            catalog_item_id,
            location_id,
            quantity_delta,
            movement_type,
            source_ref_type,
            source_ref_id,
            reason,
            correlation_id,
            occurred_at,
            created_by_user_id,
            last_event_id,
            posting_status
        ) VALUES (
            p_tenant_id,
            v_line.catalog_item_id,
            v_line.location_id,
            v_line.variance,
            'adjusted',
            'cycle_count',
            p_cycle_count_id,
            'Cycle count adjustment',
            v_correlation_id,
            v_posted_at,
            p_posted_by_user_id,
            'cc_adj_' || p_cycle_count_id::TEXT || '_line_' || v_line.line_id::TEXT,
            'posted'
        );
        
        -- Mark line as posted
        UPDATE inventory.cycle_count_lines
        SET posted_at = v_posted_at
        WHERE id = v_line.line_id;
        
        v_adjustments_created := v_adjustments_created + 1;
        v_lines_processed := v_lines_processed + 1;
    END LOOP;
    
    -- TODO: Process asset lines (serialized items) - future enhancement
    -- Would update asset.location_id for missing/unexpected assets
    
    -- Mark cycle count as posted
    UPDATE inventory.cycle_counts
    SET 
        status = 'posted',
        posted_at = v_posted_at
    WHERE id = p_cycle_count_id AND tenant_id = p_tenant_id;
    
    -- Emit event
    PERFORM public.emit_event(
        p_event_name := 'inventory.cycle_count.posted',
        p_tenant_id := p_tenant_id,
        p_scope := 'tenant',
        p_aggregate_type := 'cycle_count',
        p_aggregate_id := p_cycle_count_id,
        p_payload := jsonb_build_object(
            'cycle_count_id', p_cycle_count_id,
            'posted_at', v_posted_at,
            'adjustments_created', v_adjustments_created,
            'correlation_id', v_correlation_id,
            'posted_by_user_id', p_posted_by_user_id
        ),
        p_actor_user_id := p_posted_by_user_id
    );
    
    -- Build result
    v_result := jsonb_build_object(
        'success', TRUE,
        'cycle_count_id', p_cycle_count_id,
        'posted_at', v_posted_at,
        'adjustments_created', v_adjustments_created,
        'lines_processed', v_lines_processed,
        'correlation_id', v_correlation_id
    );
    
    RAISE NOTICE 'Posted cycle count %: % adjustments created', p_cycle_count_id, v_adjustments_created;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "inventory"."post_cycle_count_adjustments"("p_cycle_count_id" "uuid", "p_tenant_id" "uuid", "p_posted_by_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."post_cycle_count_adjustments"("p_cycle_count_id" "uuid", "p_tenant_id" "uuid", "p_posted_by_user_id" "uuid") IS 'Atomically posts all cycle count adjustments to stock_movements. Idempotent - checks posted_at before processing. Creates one movement per variance line with shared correlation_id.';



CREATE OR REPLACE FUNCTION "inventory"."prevent_event_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Allow status, lock, and error field updates
    IF OLD.event_type IS DISTINCT FROM NEW.event_type THEN
        RAISE EXCEPTION 'event_type cannot be modified after insert (event_id: %)', OLD.id;
    END IF;

    IF OLD.payload IS DISTINCT FROM NEW.payload THEN
        RAISE EXCEPTION 'payload cannot be modified after insert (event_id: %)', OLD.id;
    END IF;

    IF OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
        RAISE EXCEPTION 'tenant_id cannot be modified after insert (event_id: %)', OLD.id;
    END IF;

    -- Allow all other updates (status, locked_at, retry_count, etc.)
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."prevent_event_mutation"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."prevent_event_mutation"() IS 'Ensures event_type, payload, and tenant_id are immutable after insert';



CREATE OR REPLACE FUNCTION "inventory"."publish_event"("p_tenant_id" "uuid", "p_scope" "text", "p_event_type" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_id uuid;
BEGIN
    INSERT INTO inventory.events_outbox (
        tenant_id,
        scope,
        event_type,
        aggregate_type,
        aggregate_id,
        payload,
        metadata,
        status,
        retry_count
    ) VALUES (
        p_tenant_id,
        p_scope,
        p_event_type,
        p_aggregate_type,
        COALESCE(p_aggregate_id, gen_random_uuid()),
        p_payload,
        p_metadata,
        'pending',
        0
    ) RETURNING id INTO v_event_id;

    RETURN v_event_id;
END;
$$;


ALTER FUNCTION "inventory"."publish_event"("p_tenant_id" "uuid", "p_scope" "text", "p_event_type" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."publish_event"("p_tenant_id" "uuid", "p_scope" "text", "p_event_type" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb", "p_metadata" "jsonb") IS 'Publishes an event to the outbox for async processing by the events poller';



CREATE OR REPLACE FUNCTION "inventory"."publish_event"("p_tenant_id" "uuid", "p_scope" "text", "p_event_name" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb", "p_event_version" integer DEFAULT 1, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
