        p_scope,
        p_event_name,
        p_event_name,
        p_event_version,
        p_aggregate_type,
        COALESCE(p_aggregate_id, gen_random_uuid()),
        p_payload,
        p_metadata,
        'pending'
    ) RETURNING id INTO v_event_id;

    RETURN v_event_id;
