CREATE OR REPLACE FUNCTION "inventory"."rpc_calculate_abc_classification"("p_start_date" "date" DEFAULT (CURRENT_DATE - '365 days'::interval), "p_end_date" "date" DEFAULT CURRENT_DATE, "p_method" "text" DEFAULT 'value'::"text") RETURNS TABLE("items_classified" integer, "class_a_count" integer, "class_b_count" integer, "class_c_count" integer, "class_d_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_tenant_id UUID;
  v_total_value NUMERIC(18,2);
  v_items_classified INTEGER := 0;
  v_class_a INTEGER := 0;
  v_class_b INTEGER := 0;
  v_class_c INTEGER := 0;
  v_class_d INTEGER := 0;
BEGIN
  v_tenant_id := current_tenant_id();
  
  -- Calculate usage metrics for each item
  WITH item_usage AS (
    SELECT
      sm.catalog_item_id,
      SUM(ABS(sm.quantity_delta)) FILTER (WHERE sm.movement_type IN ('issued', 'consumed')) AS total_usage_qty,
      AVG(pol.unit_cost) AS avg_unit_cost
    FROM inventory.stock_movements sm
    LEFT JOIN inventory.receipt_lines rl ON rl.receipt_id::TEXT = sm.source_ref_id::TEXT AND sm.source_ref_type = 'receipt'
    LEFT JOIN inventory.purchase_order_lines pol ON pol.id = rl.po_line_id
    WHERE sm.tenant_id = v_tenant_id
      AND sm.created_at BETWEEN p_start_date AND p_end_date
      AND sm.movement_state = 'confirmed'
    GROUP BY sm.catalog_item_id
  ),
  item_metrics AS (
    SELECT
      iu.catalog_item_id,
      COALESCE(iu.total_usage_qty, 0) AS annual_usage_qty,
      COALESCE(iu.total_usage_qty, 0) * COALESCE(iu.avg_unit_cost, 0) AS annual_usage_value
    FROM item_usage iu
  ),
  ranked_items AS (
    SELECT
      catalog_item_id,
      annual_usage_qty,
      annual_usage_value,
      ROW_NUMBER() OVER (ORDER BY annual_usage_value DESC) AS value_rank,
      ROW_NUMBER() OVER (ORDER BY annual_usage_qty DESC) AS usage_rank,
      SUM(annual_usage_value) OVER (ORDER BY annual_usage_value DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_value,
      SUM(annual_usage_value) OVER () AS total_value
    FROM item_metrics
    WHERE annual_usage_value > 0
  ),
  classified_items AS (
    SELECT
      catalog_item_id,
      annual_usage_qty,
      annual_usage_value,
      cumulative_value / NULLIF(total_value, 0) AS cumulative_value_pct,
      value_rank,
      usage_rank,
      CASE
        WHEN p_method = 'value' THEN
          CASE
            WHEN cumulative_value / NULLIF(total_value, 0) <= 0.80 THEN 'A'
            WHEN cumulative_value / NULLIF(total_value, 0) <= 0.95 THEN 'B'
            ELSE 'C'
          END
        WHEN p_method = 'usage' THEN
          CASE
            WHEN usage_rank <= (SELECT COUNT(*) * 0.20 FROM ranked_items) THEN 'A'
            WHEN usage_rank <= (SELECT COUNT(*) * 0.50 FROM ranked_items) THEN 'B'
            ELSE 'C'
          END
        ELSE -- hybrid
          CASE
            WHEN (cumulative_value / NULLIF(total_value, 0) <= 0.70 AND usage_rank <= (SELECT COUNT(*) * 0.30 FROM ranked_items)) THEN 'A'
            WHEN (cumulative_value / NULLIF(total_value, 0) <= 0.90 OR usage_rank <= (SELECT COUNT(*) * 0.60 FROM ranked_items)) THEN 'B'
            ELSE 'C'
          END
      END AS classification
    FROM ranked_items
  )
  -- Insert or update classifications
  INSERT INTO inventory.abc_classification (
    tenant_id,
    catalog_item_id,
    classification,
    annual_usage_qty,
    annual_usage_value,
    cumulative_value_pct,
    classification_method,
    value_rank,
    usage_rank,
    analysis_start_date,
    analysis_end_date
  )
  SELECT
    v_tenant_id,
    ci.catalog_item_id,
    ci.classification,
    ci.annual_usage_qty,
    ci.annual_usage_value,
    ci.cumulative_value_pct,
    p_method,
    ci.value_rank,
    ci.usage_rank,
    p_start_date,
    p_end_date
  FROM classified_items ci
  ON CONFLICT (tenant_id, catalog_item_id, analysis_end_date)
  DO UPDATE SET
    classification = EXCLUDED.classification,
    annual_usage_qty = EXCLUDED.annual_usage_qty,
    annual_usage_value = EXCLUDED.annual_usage_value,
    cumulative_value_pct = EXCLUDED.cumulative_value_pct,
    classification_method = EXCLUDED.classification_method,
    value_rank = EXCLUDED.value_rank,
    usage_rank = EXCLUDED.usage_rank,
    updated_at = now();
  
  -- Get classification counts
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE classification = 'A'),
    COUNT(*) FILTER (WHERE classification = 'B'),
    COUNT(*) FILTER (WHERE classification = 'C'),
    COUNT(*) FILTER (WHERE classification = 'D')
  INTO v_items_classified, v_class_a, v_class_b, v_class_c, v_class_d
  FROM inventory.abc_classification
  WHERE tenant_id = v_tenant_id
    AND analysis_end_date = p_end_date;
  
  RETURN QUERY SELECT v_items_classified, v_class_a, v_class_b, v_class_c, v_class_d;
END;
$$;


ALTER FUNCTION "inventory"."rpc_calculate_abc_classification"("p_start_date" "date", "p_end_date" "date", "p_method" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_calculate_abc_classification"("p_start_date" "date", "p_end_date" "date", "p_method" "text") IS 'Calculates ABC classification for all items based on usage/value. A = top 80% value, B = next 15%, C = remaining 5%';



CREATE OR REPLACE FUNCTION "inventory"."rpc_create_catalog_item"("p_name" "text", "p_description" "text", "p_category_id" "uuid", "p_unit_of_measure" "text", "p_tracking_mode" "text", "p_reorder_point" numeric, "p_base_sku" "text", "p_sku" "text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "sku" "text", "base_sku" "text", "last_event_id" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'inventory', 'public'
    AS $_$
DECLARE
  v_tenant_id uuid;
  v_category record;
  v_separator text;
  v_next_sequence integer;
  v_base_sku text;
  v_sku text;
  v_prefix text;
  v_parent_prefix text;
  v_prefix_escaped text;
  v_sep_escaped text;
  v_max_base integer;
  v_max_sku integer;
  v_max_existing integer;
  v_seq integer;
  v_out_id uuid;
  v_out_sku text;
  v_out_base_sku text;
  v_out_last_event_id text;
BEGIN
  v_tenant_id := current_tenant_id();
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_name IS NULL OR trim(p_name) = '' THEN
    RAISE EXCEPTION 'Name is required';
  END IF;

  IF p_last_event_id IS NULL OR trim(p_last_event_id) = '' THEN
    p_last_event_id := gen_random_uuid()::text;
  END IF;

  IF p_category_id IS NULL THEN
    IF p_sku IS NULL OR trim(p_sku) = '' THEN
      RAISE EXCEPTION 'SKU is required when no category is selected';
    END IF;

    INSERT INTO inventory.catalog_items (
      tenant_id,
      name,
      sku,
      description,
      category_id,
      unit_of_measure,
      tracking_mode,
      reorder_point,
      base_sku,
      last_event_id
    ) VALUES (
      v_tenant_id,
      p_name,
      p_sku,
      p_description,
      p_category_id,
      p_unit_of_measure,
      p_tracking_mode,
      p_reorder_point,
      p_base_sku,
      p_last_event_id
    ) RETURNING inventory.catalog_items.id,
              inventory.catalog_items.sku,
              inventory.catalog_items.base_sku,
              inventory.catalog_items.last_event_id
      INTO v_out_id, v_out_sku, v_out_base_sku, v_out_last_event_id;

    RETURN QUERY SELECT v_out_id, v_out_sku, v_out_base_sku, v_out_last_event_id;
  END IF;

  SELECT c.id, c.sku_mode, c.sku_prefix, c.parent_category_id
  INTO v_category
  FROM inventory.item_categories c
  WHERE c.id = p_category_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Category not found';
  END IF;

  SELECT s.separator, s.next_sequence
  INTO v_separator, v_next_sequence
  FROM inventory.sku_settings s
  WHERE s.category_id = p_category_id
    AND s.tenant_id = v_tenant_id
  FOR UPDATE;

  IF v_separator IS NULL THEN
    INSERT INTO inventory.sku_settings (tenant_id, category_id, separator, next_sequence)
    VALUES (v_tenant_id, p_category_id, '-', 1)
    ON CONFLICT (category_id) DO NOTHING;

    SELECT s.separator, s.next_sequence
    INTO v_separator, v_next_sequence
    FROM inventory.sku_settings s
    WHERE s.category_id = p_category_id
      AND s.tenant_id = v_tenant_id
    FOR UPDATE;
  END IF;

  v_separator := COALESCE(v_separator, '-');
  v_prefix := COALESCE(v_category.sku_prefix, '');

  SELECT c.sku_prefix
  INTO v_parent_prefix
  FROM inventory.item_categories c
  WHERE c.id = v_category.parent_category_id;

  v_parent_prefix := COALESCE(v_parent_prefix, '');
  v_prefix_escaped := regexp_replace(upper(v_prefix), '([\\.^$|?*+()\[\]{}-])', '\\\\1', 'g');
  v_sep_escaped := regexp_replace(v_separator, '([\\.^$|?*+()\[\]{}-])', '\\\\1', 'g');

  IF v_category.sku_mode = 'manual' THEN
    IF p_sku IS NULL OR trim(p_sku) = '' THEN
      RAISE EXCEPTION 'SKU is required for manual categories';
    END IF;
    v_sku := p_sku;
    v_base_sku := p_base_sku;
  ELSE
    SELECT COALESCE(MAX(base_sku::int), 0)
    INTO v_max_base
    FROM inventory.catalog_items ci
    WHERE ci.tenant_id = v_tenant_id
      AND ci.base_sku ~ '^[0-9]+$';

    IF v_prefix <> '' THEN
      SELECT COALESCE(MAX((regexp_match(upper(ci.sku), '^' || v_prefix_escaped || v_sep_escaped || '([0-9]+)$'))[1]::int), 0)
      INTO v_max_sku
      FROM inventory.catalog_items ci
      WHERE ci.tenant_id = v_tenant_id
        AND upper(ci.sku) ~ ('^' || v_prefix_escaped || v_sep_escaped || '[0-9]+$');
    ELSE
      SELECT COALESCE(MAX((regexp_match(ci.sku, '([0-9]+)$'))[1]::int), 0)
      INTO v_max_sku
      FROM inventory.catalog_items ci
      WHERE ci.tenant_id = v_tenant_id
        AND ci.sku ~ '^[0-9]+$';
    END IF;

    v_max_existing := GREATEST(v_max_base, v_max_sku);
    v_seq := GREATEST(COALESCE(v_next_sequence, 1), v_max_existing + 1);

    IF v_category.sku_mode = 'attribute_based' AND p_base_sku IS NOT NULL AND trim(p_base_sku) <> '' THEN
      v_base_sku := upper(p_base_sku);
    ELSE
      v_base_sku := lpad(v_seq::text, 3, '0');
    END IF;

    IF v_category.sku_mode = 'attribute_based' THEN
      v_sku := concat_ws(v_separator, nullif(upper(v_parent_prefix), ''), nullif(upper(v_prefix), ''), v_base_sku);
    ELSE
      v_sku := CASE
        WHEN v_prefix = '' THEN v_base_sku
        ELSE upper(v_prefix) || v_separator || v_base_sku
      END;
    END IF;

    UPDATE inventory.sku_settings
    SET next_sequence = v_seq + 1,
        updated_at = now()
    WHERE category_id = p_category_id
      AND tenant_id = v_tenant_id;
  END IF;

  INSERT INTO inventory.catalog_items (
    tenant_id,
    name,
    sku,
    description,
    category_id,
    unit_of_measure,
    tracking_mode,
    reorder_point,
    base_sku,
    last_event_id
  ) VALUES (
    v_tenant_id,
    p_name,
    v_sku,
    p_description,
    p_category_id,
    p_unit_of_measure,
    p_tracking_mode,
    p_reorder_point,
    v_base_sku,
    p_last_event_id
  ) RETURNING inventory.catalog_items.id,
            inventory.catalog_items.sku,
            inventory.catalog_items.base_sku,
            inventory.catalog_items.last_event_id
    INTO v_out_id, v_out_sku, v_out_base_sku, v_out_last_event_id;

  RETURN QUERY SELECT v_out_id, v_out_sku, v_out_base_sku, v_out_last_event_id;
END;
$_$;


ALTER FUNCTION "inventory"."rpc_create_catalog_item"("p_name" "text", "p_description" "text", "p_category_id" "uuid", "p_unit_of_measure" "text", "p_tracking_mode" "text", "p_reorder_point" numeric, "p_base_sku" "text", "p_sku" "text", "p_last_event_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."rpc_dismiss_alert"("p_alert_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_tenant_id UUID;
  v_user_id UUID;
BEGIN
  -- Get current user
  v_user_id := auth.uid();
  v_tenant_id := current_tenant_id();
  
  -- Update alert
  UPDATE inventory.reorder_alerts
  SET
    status = 'dismissed',
    dismissed_by = v_user_id,
    dismissed_at = now(),
    dismissed_reason = p_reason,
    updated_at = now()
  WHERE id = p_alert_id
    AND tenant_id = v_tenant_id
    AND status IN ('open', 'acknowledged');
    
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert not found or already dismissed';
  END IF;
END;
$$;


ALTER FUNCTION "inventory"."rpc_dismiss_alert"("p_alert_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."rpc_get_sku_settings"("p_category_id" "uuid") RETURNS TABLE("separator" "text", "next_sequence" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'inventory', 'public'
    AS $_$
DECLARE
  v_tenant_id uuid;
  v_separator text;
  v_next_sequence integer;
  v_max_base integer;
  v_max_sku integer;
  v_max_existing integer;
  v_prefix text;
  v_prefix_escaped text;
  v_sep_escaped text;
BEGIN
  v_tenant_id := current_tenant_id();
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT s.separator, s.next_sequence
  INTO v_separator, v_next_sequence
  FROM inventory.sku_settings s
  WHERE s.category_id = p_category_id
    AND s.tenant_id = v_tenant_id;

  SELECT c.sku_prefix
  INTO v_prefix
  FROM inventory.item_categories c
  WHERE c.id = p_category_id;

  v_separator := COALESCE(v_separator, '-');
  v_prefix := COALESCE(v_prefix, '');
  v_prefix_escaped := regexp_replace(upper(v_prefix), '([\\.^$|?*+()\[\]{}-])', '\\\\1', 'g');
  v_sep_escaped := regexp_replace(v_separator, '([\\.^$|?*+()\[\]{}-])', '\\\\1', 'g');

  SELECT COALESCE(MAX(base_sku::int), 0)
  INTO v_max_base
  FROM inventory.catalog_items ci
  WHERE ci.tenant_id = v_tenant_id
    AND ci.category_id = p_category_id
    AND ci.base_sku ~ '^[0-9]+$';

  IF v_prefix <> '' THEN
    SELECT COALESCE(MAX((regexp_match(upper(ci.sku), '^' || v_prefix_escaped || v_sep_escaped || '([0-9]+)$'))[1]::int), 0)
    INTO v_max_sku
    FROM inventory.catalog_items ci
    WHERE ci.tenant_id = v_tenant_id
      AND upper(ci.sku) ~ ('^' || v_prefix_escaped || v_sep_escaped || '[0-9]+$');
  ELSE
    SELECT COALESCE(MAX((regexp_match(ci.sku, '([0-9]+)$'))[1]::int), 0)
    INTO v_max_sku
    FROM inventory.catalog_items ci
    WHERE ci.tenant_id = v_tenant_id
      AND ci.sku ~ '^[0-9]+$';
  END IF;

  v_max_existing := GREATEST(v_max_base, v_max_sku);
  v_next_sequence := GREATEST(COALESCE(v_next_sequence, 1), v_max_existing + 1);

  RETURN QUERY SELECT v_separator, v_next_sequence;
END;
$_$;


ALTER FUNCTION "inventory"."rpc_get_sku_settings"("p_category_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_asset_assign"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_assigned_to_type" "text", "p_assigned_to_id" "uuid", "p_assigned_by_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_assignment_id UUID;
    v_asset RECORD;
    v_event_id TEXT;
    v_existing_assignment UUID;
BEGIN
    -- Validate
    IF p_tenant_id IS NULL OR p_asset_id IS NULL THEN
        RAISE EXCEPTION 'tenant_id and asset_id are required';
    END IF;
    
    -- Require event ID for strict idempotency
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Get asset
    SELECT * INTO v_asset
    FROM inventory.assets
    WHERE id = p_asset_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Asset not found';
    END IF;
    
    -- Check for existing active assignment
    SELECT id INTO v_existing_assignment
    FROM inventory.asset_assignments
    WHERE asset_id = p_asset_id
    AND tenant_id = p_tenant_id
    AND returned_at IS NULL;
    
    IF v_existing_assignment IS NOT NULL THEN
        RAISE EXCEPTION 'Asset already assigned - must return before reassigning';
    END IF;
    
    -- Create assignment (idempotent)
    INSERT INTO inventory.asset_assignments (
        tenant_id,
        asset_id,
        assigned_to_type,
        assigned_to_id,
        assigned_by_user_id,
        assigned_at,
        notes,
        last_event_id
    ) VALUES (
        p_tenant_id,
        p_asset_id,
        p_assigned_to_type,
        p_assigned_to_id,
        p_assigned_by_user_id,
        NOW(),
        p_notes,
        v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_assignment_id;
    
    -- If no ID returned, assignment already exists
    IF v_assignment_id IS NULL THEN
        SELECT id INTO v_assignment_id
        FROM inventory.asset_assignments
        WHERE tenant_id = p_tenant_id
        AND last_event_id = v_event_id;
        
        RETURN v_assignment_id;
    END IF;
    
    -- Update asset status
    UPDATE inventory.assets
    SET 
        status = 'assigned',
        updated_at = NOW()
    WHERE id = p_asset_id;
    
    -- Update asset_state read model
    INSERT INTO inventory.asset_state (
        id, tenant_id, asset_id, current_status, assigned_to_ref, last_movement_at
    ) VALUES (
        p_asset_id, p_tenant_id, p_asset_id, 'assigned',
        jsonb_build_object('type', p_assigned_to_type, 'id', p_assigned_to_id),
        NOW()
    )
    ON CONFLICT (tenant_id, asset_id) DO UPDATE
    SET 
        current_status = 'assigned',
        assigned_to_ref = jsonb_build_object('type', p_assigned_to_type, 'id', p_assigned_to_id),
        last_movement_at = NOW(),
        updated_at = NOW();
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'asset',
        p_event_type => 'asset.assigned',
        p_aggregate_type => 'asset',
        p_aggregate_id => p_asset_id,
        p_payload => jsonb_build_object(
            'asset_id', p_asset_id,
            'asset_tag', v_asset.asset_tag,
            'assignment_id', v_assignment_id,
            'assigned_to_type', p_assigned_to_type,
            'assigned_to_id', p_assigned_to_id
        )
    );
    
    RETURN v_assignment_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_asset_assign"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_assigned_to_type" "text", "p_assigned_to_id" "uuid", "p_assigned_by_user_id" "uuid", "p_notes" "text", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_asset_assign"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_assigned_to_type" "text", "p_assigned_to_id" "uuid", "p_assigned_by_user_id" "uuid", "p_notes" "text", "p_last_event_id" "text") IS 'Assigns asset to employee/vehicle/job (idempotent)';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_asset_return"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_return_condition" "text" DEFAULT 'good'::"text", "p_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_assignment RECORD;
    v_asset RECORD;
    v_event_id TEXT;
BEGIN
    -- Require event ID for strict idempotency
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Get active assignment
    SELECT * INTO v_assignment
    FROM inventory.asset_assignments
    WHERE asset_id = p_asset_id
    AND tenant_id = p_tenant_id
    AND returned_at IS NULL;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'No active assignment found for asset';
    END IF;
    
    -- Get asset
    SELECT * INTO v_asset
    FROM inventory.assets
    WHERE id = p_asset_id
    AND tenant_id = p_tenant_id;
    
    -- Update assignment (idempotent check via last_event_id in notes)
    UPDATE inventory.asset_assignments
    SET 
        returned_at = NOW(),
        return_condition = p_return_condition,
        notes = COALESCE(notes, '') || E'\nReturn: ' || COALESCE(p_notes, ''),
        updated_at = NOW()
    WHERE id = v_assignment.id
    AND returned_at IS NULL; -- Double-check it hasn't been returned
    
    -- Update asset status based on condition
    UPDATE inventory.assets
    SET 
        status = CASE p_return_condition
            WHEN 'good' THEN 'available'
            WHEN 'damaged' THEN 'in_repair'
            WHEN 'needs_repair' THEN 'in_repair'
            ELSE 'out_of_service'
        END,
        updated_at = NOW()
    WHERE id = p_asset_id;
    
    -- Update asset_state read model
    UPDATE inventory.asset_state
    SET 
        current_status = CASE p_return_condition
            WHEN 'good' THEN 'available'
            WHEN 'damaged' THEN 'in_repair'
            WHEN 'needs_repair' THEN 'in_repair'
            ELSE 'out_of_service'
        END,
        assigned_to_ref = NULL,
        last_movement_at = NOW(),
        updated_at = NOW()
    WHERE asset_id = p_asset_id
    AND tenant_id = p_tenant_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'asset',
        p_event_type => 'asset.returned',
        p_aggregate_type => 'asset',
        p_aggregate_id => p_asset_id,
        p_payload => jsonb_build_object(
            'asset_id', p_asset_id,
            'asset_tag', v_asset.asset_tag,
            'assignment_id', v_assignment.id,
            'return_condition', p_return_condition,
            'days_assigned', EXTRACT(DAY FROM (NOW() - v_assignment.assigned_at))
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_asset_return"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_return_condition" "text", "p_notes" "text", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_asset_return"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_return_condition" "text", "p_notes" "text", "p_last_event_id" "text") IS 'Returns asset from assignment';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_cycle_count_approve"("p_tenant_id" "uuid", "p_cycle_count_id" "uuid", "p_approved_by_user_id" "uuid", "p_approval_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_count RECORD;
    v_pending_lines INTEGER;
BEGIN
    -- Get count
    SELECT * INTO v_count
    FROM inventory.cycle_counts
    WHERE id = p_cycle_count_id AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cycle count not found';
    END IF;
    
    IF v_count.status != 'pending_approval' THEN
        RAISE EXCEPTION 'Count is not pending approval';
    END IF;
    
    -- Check for uncounted lines
    SELECT COUNT(*) INTO v_pending_lines
    FROM inventory.cycle_count_lines
    WHERE cycle_count_id = p_cycle_count_id
    AND counted_qty IS NULL;
    
    IF v_pending_lines > 0 THEN
        RAISE EXCEPTION '% lines have not been counted', v_pending_lines;
    END IF;
    
    -- Approve
    UPDATE inventory.cycle_counts
    SET 
        status = 'approved',
        approved_by_user_id = p_approved_by_user_id,
        approved_at = NOW(),
        approval_notes = p_approval_notes,
        updated_at = NOW()
    WHERE id = p_cycle_count_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'inventory',
        p_event_type => 'cycle_count.approved',
        p_aggregate_type => 'cycle_count',
        p_aggregate_id => p_cycle_count_id,
        p_payload => jsonb_build_object(
            'cycle_count_id', p_cycle_count_id,
            'approved_by_user_id', p_approved_by_user_id
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_cycle_count_approve"("p_tenant_id" "uuid", "p_cycle_count_id" "uuid", "p_approved_by_user_id" "uuid", "p_approval_notes" "text", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_cycle_count_approve"("p_tenant_id" "uuid", "p_cycle_count_id" "uuid", "p_approved_by_user_id" "uuid", "p_approval_notes" "text", "p_last_event_id" "text") IS 'Approves cycle count for posting';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_cycle_count_record"("p_tenant_id" "uuid", "p_cycle_count_id" "uuid", "p_catalog_item_id" "uuid", "p_counted_qty" numeric, "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_count RECORD;
    v_line RECORD;
    v_item RECORD;
    v_requires_approval BOOLEAN;
    v_variance_qty NUMERIC;
    v_variance_pct NUMERIC;
BEGIN
    -- Get count header
    SELECT * INTO v_count
    FROM inventory.cycle_counts
    WHERE id = p_cycle_count_id AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cycle count not found';
    END IF;
    
    IF v_count.status != 'in_progress' THEN
        RAISE EXCEPTION 'Count is not in progress';
    END IF;
    
    -- Get line
    SELECT * INTO v_line
    FROM inventory.cycle_count_lines
    WHERE cycle_count_id = p_cycle_count_id
    AND catalog_item_id = p_catalog_item_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Item not in this count';
    END IF;
    
    -- Get item details
    SELECT * INTO v_item
    FROM inventory.catalog_items
    WHERE id = p_catalog_item_id;
    
    -- Calculate variance
    v_variance_qty := p_counted_qty - v_line.expected_qty;
    IF v_line.expected_qty = 0 THEN
        v_variance_pct := NULL;
    ELSE
        v_variance_pct := (v_variance_qty / v_line.expected_qty) * 100;
    END IF;
    
    -- Check if approval required
    v_requires_approval := inventory.check_variance_approval(
        p_tenant_id => p_tenant_id,
        p_catalog_item_id => p_catalog_item_id,
        p_location_id => v_count.location_id,
        p_item_category_id => v_item.item_category_id,
        p_variance_qty => v_variance_qty,
        p_expected_qty => v_line.expected_qty
    );
    
    -- Update line
    UPDATE inventory.cycle_count_lines
    SET 
        counted_qty = p_counted_qty,
        variance_qty = v_variance_qty,
        variance_pct = v_variance_pct,
        requires_approval = v_requires_approval,
        auto_approved = NOT v_requires_approval,
        counted_at = NOW(),
        updated_at = NOW()
    WHERE id = v_line.id;
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_cycle_count_record"("p_tenant_id" "uuid", "p_cycle_count_id" "uuid", "p_catalog_item_id" "uuid", "p_counted_qty" numeric, "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_cycle_count_record"("p_tenant_id" "uuid", "p_cycle_count_id" "uuid", "p_catalog_item_id" "uuid", "p_counted_qty" numeric, "p_last_event_id" "text") IS 'Records counted quantity and calculates variance';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_cycle_count_start"("p_tenant_id" "uuid", "p_location_id" "uuid", "p_count_type" "text", "p_catalog_item_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_item_category_id" "uuid" DEFAULT NULL::"uuid", "p_counted_by_user_id" "uuid" DEFAULT NULL::"uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_count_id UUID;
    v_event_id TEXT;
    v_item RECORD;
BEGIN
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Validate count_type
    IF p_count_type NOT IN ('full', 'partial', 'spot_check') THEN
        RAISE EXCEPTION 'Invalid count_type. Must be: full, partial, spot_check';
    END IF;
    
    -- Create count header
    INSERT INTO inventory.cycle_counts (
        tenant_id,
        location_id,
        count_type,
        status,
        counted_by_user_id,
        last_event_id
    ) VALUES (
        p_tenant_id,
        p_location_id,
        p_count_type,
        'in_progress',
        p_counted_by_user_id,
        v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_count_id;
    
    IF v_count_id IS NULL THEN
        SELECT id INTO v_count_id
        FROM inventory.cycle_counts
        WHERE tenant_id = p_tenant_id AND last_event_id = v_event_id;
        RETURN v_count_id;
    END IF;
    
    -- Create count lines based on type
    IF p_count_type = 'full' THEN
        -- All items in location
        INSERT INTO inventory.cycle_count_lines (
            tenant_id,
            cycle_count_id,
            catalog_item_id,
            expected_qty,
            last_event_id
        )
        SELECT 
            sb.tenant_id,
            v_count_id,
            sb.catalog_item_id,
            sb.qty_on_hand,
            v_event_id || '_line_' || sb.catalog_item_id::TEXT
        FROM inventory.stock_balances sb
        WHERE sb.tenant_id = p_tenant_id
        AND sb.location_id = p_location_id
        AND sb.qty_on_hand > 0
        ON CONFLICT (tenant_id, last_event_id) DO NOTHING;
        
    ELSIF p_count_type = 'partial' THEN
        -- Specific items or category
        IF p_catalog_item_ids IS NOT NULL THEN
            INSERT INTO inventory.cycle_count_lines (
                tenant_id,
                cycle_count_id,
                catalog_item_id,
                expected_qty,
                last_event_id
            )
            SELECT 
                sb.tenant_id,
                v_count_id,
                sb.catalog_item_id,
                sb.qty_on_hand,
                v_event_id || '_line_' || sb.catalog_item_id::TEXT
            FROM inventory.stock_balances sb
            WHERE sb.tenant_id = p_tenant_id
            AND sb.location_id = p_location_id
            AND sb.catalog_item_id = ANY(p_catalog_item_ids)
            ON CONFLICT (tenant_id, last_event_id) DO NOTHING;
        ELSIF p_item_category_id IS NOT NULL THEN
            INSERT INTO inventory.cycle_count_lines (
                tenant_id,
                cycle_count_id,
                catalog_item_id,
                expected_qty,
                last_event_id
            )
            SELECT 
                sb.tenant_id,
                v_count_id,
                sb.catalog_item_id,
                sb.qty_on_hand,
                v_event_id || '_line_' || sb.catalog_item_id::TEXT
            FROM inventory.stock_balances sb
            JOIN inventory.catalog_items ci ON ci.id = sb.catalog_item_id
            WHERE sb.tenant_id = p_tenant_id
            AND sb.location_id = p_location_id
            AND ci.item_category_id = p_item_category_id
            ON CONFLICT (tenant_id, last_event_id) DO NOTHING;
        ELSE
            RAISE EXCEPTION 'Partial count requires catalog_item_ids or item_category_id';
        END IF;
    END IF;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'inventory',
        p_event_type => 'cycle_count.started',
        p_aggregate_type => 'cycle_count',
        p_aggregate_id => v_count_id,
        p_payload => jsonb_build_object(
            'cycle_count_id', v_count_id,
            'location_id', p_location_id,
            'count_type', p_count_type
        )
    );
    
    RETURN v_count_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_cycle_count_start"("p_tenant_id" "uuid", "p_location_id" "uuid", "p_count_type" "text", "p_catalog_item_ids" "uuid"[], "p_item_category_id" "uuid", "p_counted_by_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_cycle_count_start"("p_tenant_id" "uuid", "p_location_id" "uuid", "p_count_type" "text", "p_catalog_item_ids" "uuid"[], "p_item_category_id" "uuid", "p_counted_by_user_id" "uuid", "p_last_event_id" "text") IS 'Starts new cycle count and creates lines based on count type';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_find_available_assets"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_reserved_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_reserved_until" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 50) RETURNS TABLE("asset_id" "uuid", "asset_tag" "text", "serial_number" "text", "status" "text", "location_id" "uuid", "location_name" "text", "is_available" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        a.id AS asset_id,
        a.asset_tag,
        a.serial_number,
        a.status,
        a.location_id,
        l.name AS location_name,
        NOT EXISTS (
            SELECT 1
            FROM inventory.reservations r
            WHERE r.tenant_id = p_tenant_id
              AND r.asset_id = a.id
              AND r.reservation_type = 'serialized'
              AND r.status = 'active'
              AND (
                  -- If time window specified, check for overlap
                  (p_reserved_from IS NOT NULL AND p_reserved_until IS NOT NULL
                   AND r.reserved_from IS NOT NULL AND r.reserved_until IS NOT NULL
                   AND tstzrange(r.reserved_from, r.reserved_until, '[)') && tstzrange(p_reserved_from, p_reserved_until, '[)'))
                  OR
                  -- If no time window, just check if any active reservation exists
                  (p_reserved_from IS NULL OR p_reserved_until IS NULL)
              )
        ) AS is_available
    FROM inventory.assets a
    LEFT JOIN inventory.locations l ON l.id = a.location_id AND l.tenant_id = p_tenant_id
    WHERE a.tenant_id = p_tenant_id
      AND a.catalog_item_id = p_catalog_item_id
      AND (p_location_id IS NULL OR a.location_id = p_location_id)
      AND a.status IN ('available', 'assigned')
    ORDER BY a.asset_tag
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_find_available_assets"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_reserved_from" timestamp with time zone, "p_reserved_until" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_find_available_assets"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_reserved_from" timestamp with time zone, "p_reserved_until" timestamp with time zone, "p_limit" integer) IS 'Finds available serialized assets of a given type (supports time window filtering)';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_fulfill_reservation_issue"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_fulfilled_by_user_id" "uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_reservation RECORD;
    v_movement_id UUID;
    v_event_id TEXT;
    v_current_qty_on_hand NUMERIC;
BEGIN
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Get reservation with all fields
    SELECT * INTO v_reservation
    FROM inventory.reservations
    WHERE id = p_reservation_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Reservation not found';
    END IF;
    
    IF v_reservation.status != 'active' THEN
        RAISE EXCEPTION 'Reservation cannot be fulfilled in status: %', v_reservation.status;
    END IF;
    
    -- Handle based on reservation type
    IF v_reservation.reservation_type = 'fungible' THEN
        -- Fungible: check stock availability
        SELECT COALESCE(qty_on_hand, 0) INTO v_current_qty_on_hand
        FROM inventory.stock_balances
        WHERE tenant_id = p_tenant_id
        AND catalog_item_id = v_reservation.catalog_item_id
        AND location_id = v_reservation.location_id;
        
        IF v_current_qty_on_hand < v_reservation.qty THEN
            RAISE EXCEPTION 'Insufficient stock on hand to fulfill reservation. Available: %, Required: %', 
                v_current_qty_on_hand, v_reservation.qty;
        END IF;
        
        -- Write stock movement (issue)
        v_movement_id := inventory.insert_stock_movement(
            p_tenant_id => p_tenant_id,
            p_catalog_item_id => v_reservation.catalog_item_id,
            p_location_id => v_reservation.location_id,
            p_quantity_delta => -v_reservation.qty,
            p_movement_type => 'issued',
            p_source_ref_type => 'reservation',
            p_source_ref_id => p_reservation_id,
            p_unit_cost => NULL,
            p_reason => 'Fulfill reservation',
            p_notes => 'Reservation fulfilled for: ' || COALESCE(v_reservation.external_order_ref, 'N/A'),
            p_correlation_id => NULL,
            p_occurred_at => NOW(),
            p_created_by_user_id => p_fulfilled_by_user_id,
            p_last_event_id => v_event_id || '_movement'
        );
        
        -- Release from stock_balances.qty_reserved
        UPDATE inventory.stock_balances
        SET 
            qty_reserved = GREATEST(0, qty_reserved - v_reservation.qty),
            updated_at = NOW()
        WHERE tenant_id = p_tenant_id
        AND catalog_item_id = v_reservation.catalog_item_id
        AND location_id = v_reservation.location_id;
        
    ELSIF v_reservation.reservation_type = 'serialized' THEN
        -- Serialized: verify asset is still in 'assigned' status
        DECLARE
            v_asset_status TEXT;
        BEGIN
            SELECT status INTO v_asset_status
            FROM inventory.assets
            WHERE id = v_reservation.asset_id
            AND tenant_id = p_tenant_id;
            
            IF v_asset_status IS NULL THEN
                RAISE EXCEPTION 'Asset not found for serialized reservation';
            END IF;
            
            IF v_asset_status != 'assigned' THEN
                RAISE EXCEPTION 'Asset is not in assigned status. Current status: %', v_asset_status;
            END IF;
            
            -- Keep asset as 'assigned' when fulfilled (asset has been given out)
            -- No status change needed - it's already assigned to the reservation
            
            -- Movement ID is null for serialized (no stock balance change)
            v_movement_id := NULL;
        END;
    ELSE
        RAISE EXCEPTION 'Unknown reservation_type: %', v_reservation.reservation_type;
    END IF;
    
    -- Update reservation status
    UPDATE inventory.reservations
    SET 
        status = 'fulfilled',
        fulfilled_by_user_id = p_fulfilled_by_user_id,
        fulfilled_at = NOW(),
        updated_at = NOW()
    WHERE id = p_reservation_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'reservation.fulfilled',
        p_aggregate_type => 'reservation',
        p_aggregate_id => p_reservation_id,
        p_payload => jsonb_build_object(
            'reservation_id', p_reservation_id,
            'reservation_type', v_reservation.reservation_type,
            'catalog_item_id', v_reservation.catalog_item_id,
            'asset_id', v_reservation.asset_id,
            'location_id', v_reservation.location_id,
            'qty', v_reservation.qty,
            'movement_id', v_movement_id
        )
    );
    
    RETURN v_movement_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_fulfill_reservation_issue"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_fulfilled_by_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_fulfill_reservation_issue"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_fulfilled_by_user_id" "uuid", "p_last_event_id" "text") IS 'Fulfills reservation by issuing stock (writes ledger entry). Validates sufficient qty_on_hand before fulfilling.';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_receive"("p_receipt_number" "text", "p_location_id" "uuid", "p_lines" "jsonb", "p_po_id" "uuid" DEFAULT NULL::"uuid", "p_received_at" timestamp with time zone DEFAULT "now"(), "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RAISE NOTICE 'DEPRECATED: inventory.rpc_inv_receive() → Use supply_chain.rpc_create_receipt()';
  
  -- Redirect to new supply_chain RPC
  RETURN supply_chain.rpc_create_receipt(
    p_receipt_number,
    p_location_id,
    p_po_id,
    p_received_at,
    p_notes,
    p_lines,
    TRUE -- auto_post
  );
END;
$$;


