CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_reserve_asset"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_allocation_type" "text" DEFAULT NULL::"text", "p_job_ref" "jsonb" DEFAULT NULL::"jsonb", "p_external_order_ref" "text" DEFAULT NULL::"text", "p_needed_by" "date" DEFAULT NULL::"date", "p_expiration_date" "date" DEFAULT NULL::"date", "p_reserved_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_reserved_until" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_notes" "text" DEFAULT NULL::"text", "p_destination_location_id" "uuid" DEFAULT NULL::"uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_reservation_id UUID;
    v_event_id TEXT;
    v_validation RECORD;
    v_asset RECORD;
BEGIN
    -- Validate inputs
    IF p_tenant_id IS NULL OR p_asset_id IS NULL THEN
        RAISE EXCEPTION 'tenant_id and asset_id are required'
        USING ERRCODE = 'invalid_parameter_value';
    END IF;

    -- Require event ID for strict idempotency
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required'
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    v_event_id := p_last_event_id;

    -- Get asset details
    SELECT 
        a.id,
        a.catalog_item_id,
        a.location_id,
        a.asset_tag
    INTO v_asset
    FROM inventory.assets a
    WHERE a.id = p_asset_id
      AND a.tenant_id = p_tenant_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Asset not found or access denied'
        USING ERRCODE = 'no_data_found';
    END IF;

    -- Validate availability
    SELECT * INTO v_validation
    FROM inventory.validate_asset_reservation_availability(
        p_tenant_id,
        p_asset_id,
        p_reserved_from,
        p_reserved_until
    );

    IF NOT v_validation.is_available THEN
        RAISE EXCEPTION '%', v_validation.message
        USING ERRCODE = 'check_violation',
              HINT = 'Choose a different asset or time window';
    END IF;

    -- Create reservation (idempotent on last_event_id)
    INSERT INTO inventory.reservations (
        tenant_id,
        catalog_item_id,
        location_id,
        destination_location_id,
        qty,
        asset_id,
        reservation_type,
        status,
        allocation_type,
        job_ref,
        external_order_ref,
        needed_by,
        expiration_date,
        reserved_from,
        reserved_until,
        notes,
        last_event_id
    ) VALUES (
        p_tenant_id,
        v_asset.catalog_item_id,
        v_asset.location_id,
        p_destination_location_id,
        1,
        p_asset_id,
        'serialized',
        'active',
        p_allocation_type,
        p_job_ref,
        p_external_order_ref,
        p_needed_by,
        p_expiration_date,
        p_reserved_from,
        p_reserved_until,
        p_notes,
