CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_reserve_fungible"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric, "p_allocation_type" "text" DEFAULT NULL::"text", "p_job_ref" "jsonb" DEFAULT NULL::"jsonb", "p_external_order_ref" "text" DEFAULT NULL::"text", "p_needed_by" "date" DEFAULT NULL::"date", "p_expiration_date" "date" DEFAULT NULL::"date", "p_reserved_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_reserved_until" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_reservation_id UUID;
    v_event_id TEXT;
    v_validation RECORD;
BEGIN
    -- Validate inputs
    IF p_tenant_id IS NULL OR p_catalog_item_id IS NULL OR p_location_id IS NULL OR p_qty IS NULL THEN
        RAISE EXCEPTION 'tenant_id, catalog_item_id, location_id, and qty are required'
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    
    IF p_qty <= 0 THEN
        RAISE EXCEPTION 'qty must be greater than 0'
        USING ERRCODE = 'check_violation';
    END IF;
    
    -- Require event ID for strict idempotency
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required'
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Validate availability
    SELECT * INTO v_validation
    FROM inventory.validate_fungible_reservation_availability(
        p_tenant_id,
        p_catalog_item_id,
        p_location_id,
        p_qty
    );
    
    IF NOT v_validation.is_available THEN
        RAISE EXCEPTION '%', v_validation.message
        USING ERRCODE = 'check_violation',
              HINT = 'Check stock levels or receive more inventory';
    END IF;
    
    -- Create reservation (idempotent on last_event_id)
    INSERT INTO inventory.reservations (
        tenant_id,
        catalog_item_id,
        location_id,
        qty,
        asset_id,
        reservation_type,
        status,
        allocation_type,
        job_ref,
        external_order_ref,
        needed_by,
        expiration_date,
        reserved_from,
        reserved_until,
        notes,
        last_event_id
    ) VALUES (
        p_tenant_id,
        p_catalog_item_id,
        p_location_id,
        p_qty,
        NULL, -- No asset_id for fungible
        'fungible',
        'active',
        p_allocation_type,
        p_job_ref,
        p_external_order_ref,
        p_needed_by,
        p_expiration_date,
        p_reserved_from,
        p_reserved_until,
        p_notes,
        v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_reservation_id;
    
    -- If no ID returned, reservation already exists (idempotent)
    IF v_reservation_id IS NULL THEN
        SELECT id INTO v_reservation_id
        FROM inventory.reservations
        WHERE tenant_id = p_tenant_id
          AND last_event_id = v_event_id;
        
        RETURN v_reservation_id;
    END IF;
    
    -- Update stock_balances.qty_reserved
    INSERT INTO inventory.stock_balances (
        tenant_id,
        catalog_item_id,
        location_id,
        qty_on_hand,
        qty_reserved
    ) VALUES (
        p_tenant_id,
        p_catalog_item_id,
        p_location_id,
        0,
        p_qty
    )
    ON CONFLICT (tenant_id, catalog_item_id, location_id)
    DO UPDATE SET
        qty_reserved = inventory.stock_balances.qty_reserved + EXCLUDED.qty_reserved,
        updated_at = NOW();
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'reservation.created.fungible',
        p_aggregate_type => 'reservation',
        p_aggregate_id => v_reservation_id,
        p_payload => jsonb_build_object(
            'reservation_id', v_reservation_id,
            'reservation_type', 'fungible',
            'catalog_item_id', p_catalog_item_id,
            'location_id', p_location_id,
            'qty', p_qty,
            'allocation_type', p_allocation_type,
            'external_order_ref', p_external_order_ref,
            'reserved_from', p_reserved_from,
            'reserved_until', p_reserved_until
        )
    );
    
    RETURN v_reservation_id;
END;
$$;


