    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_reservation_id;

    -- If no ID returned, reservation already exists (idempotent)
    IF v_reservation_id IS NULL THEN
        SELECT id INTO v_reservation_id
        FROM inventory.reservations
        WHERE tenant_id = p_tenant_id
          AND last_event_id = v_event_id;

        RETURN v_reservation_id;
    END IF;

    -- Update stock_balances.qty_reserved
    INSERT INTO inventory.stock_balances (
        tenant_id,
        catalog_item_id,
        location_id,
        qty_on_hand,
        qty_reserved
    ) VALUES (
        p_tenant_id,
        p_catalog_item_id,
        p_location_id,
        0,
        p_qty
    )
    ON CONFLICT (tenant_id, catalog_item_id, location_id)
    DO UPDATE SET
        qty_reserved = inventory.stock_balances.qty_reserved + EXCLUDED.qty_reserved,
        updated_at = NOW();

    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'reservation.created.fungible',
        p_aggregate_type => 'reservation',
        p_aggregate_id => v_reservation_id,
        p_payload => jsonb_build_object(
            'reservation_id', v_reservation_id,
            'reservation_type', 'fungible',
            'catalog_item_id', p_catalog_item_id,
            'location_id', p_location_id,
            'destination_location_id', p_destination_location_id,
            'qty', p_qty,
            'allocation_type', p_allocation_type,
            'external_order_ref', p_external_order_ref,
            'reserved_from', p_reserved_from,
            'reserved_until', p_reserved_until
        )
    );

    RETURN v_reservation_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_reserve_fungible"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric, "p_allocation_type" "text", "p_job_ref" "jsonb", "p_external_order_ref" "text", "p_needed_by" "date", "p_expiration_date" "date", "p_reserved_from" timestamp with time zone, "p_reserved_until" timestamp with time zone, "p_notes" "text", "p_destination_location_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_cancel"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_cancellation_reason" "text", "p_cancelled_by_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_transfer RECORD;
BEGIN
    SELECT * INTO v_transfer
    FROM inventory.transfers
    WHERE id = p_transfer_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer not found';
    END IF;
    
    IF v_transfer.status NOT IN ('draft', 'in_transit') THEN
        RAISE EXCEPTION 'Transfer cannot be cancelled in status: %', v_transfer.status;
    END IF;
    
    UPDATE inventory.transfers
    SET 
        status = 'cancelled',
        cancellation_reason = p_cancellation_reason,
        cancelled_at = NOW(),
        updated_at = NOW()
    WHERE id = p_transfer_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'inventory',
        p_event_type => 'transfer.cancelled',
        p_aggregate_type => 'transfer',
        p_aggregate_id => p_transfer_id,
        p_payload => jsonb_build_object(
            'transfer_id', p_transfer_id,
            'transfer_number', v_transfer.transfer_number,
            'reason', p_cancellation_reason
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_cancel"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_cancellation_reason" "text", "p_cancelled_by_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_cancel"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_cancellation_reason" "text", "p_cancelled_by_user_id" "uuid") IS 'Cancels a draft or in-transit transfer';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_create"("p_tenant_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_lines" "jsonb", "p_initiated_by_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_transfer_id uuid;
    v_transfer_number text;
    v_line jsonb;
    v_line_number integer := 1;
    v_event_id text;
    v_stock_balance record;
    v_item_name text;
    v_location_name text;
    v_tracking_mode text;
    v_available_assets integer;
    v_asset_ids jsonb;
    v_requested_qty integer;
    v_line_id uuid;
BEGIN
    IF p_tenant_id IS NULL THEN
        RAISE EXCEPTION 'tenant_id is required';
    END IF;

    IF p_from_location_id = p_to_location_id THEN
        RAISE EXCEPTION 'from_location_id and to_location_id must be different';
    END IF;

    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
        SELECT tracking_mode, name INTO v_tracking_mode, v_item_name
        FROM inventory.catalog_items
        WHERE id = (v_line->>'catalog_item_id')::uuid
          AND tenant_id = p_tenant_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Catalog item not found';
        END IF;

        SELECT name INTO v_location_name
        FROM inventory.locations
        WHERE id = p_from_location_id
          AND tenant_id = p_tenant_id;

        v_asset_ids := v_line->'asset_ids';

        IF v_tracking_mode = 'serialized' THEN
            IF v_asset_ids IS NULL OR jsonb_typeof(v_asset_ids) <> 'array' OR jsonb_array_length(v_asset_ids) = 0 THEN
                RAISE EXCEPTION 'Select assets for serialized item "%" at location "%"', v_item_name, v_location_name;
            END IF;

            v_requested_qty := COALESCE(NULLIF(v_line->>'qty', '')::integer, jsonb_array_length(v_asset_ids));

            IF v_requested_qty != jsonb_array_length(v_asset_ids) THEN
                RAISE EXCEPTION 'Qty must match selected assets for "%". Selected: %, Qty: %',
                    v_item_name,
                    jsonb_array_length(v_asset_ids),
                    v_requested_qty;
            END IF;

            SELECT COUNT(*) INTO v_available_assets
            FROM inventory.assets
            WHERE tenant_id = p_tenant_id
              AND id IN (SELECT (jsonb_array_elements_text(v_asset_ids))::uuid)
              AND catalog_item_id = (v_line->>'catalog_item_id')::uuid
              AND location_id = p_from_location_id
              AND status IN ('available', 'assigned');

            IF v_available_assets < jsonb_array_length(v_asset_ids) THEN
                RAISE EXCEPTION 'Some selected assets are not available for "%" at "%"', v_item_name, v_location_name;
            END IF;
        ELSE
            SELECT sb.qty_on_hand, sb.qty_reserved, ci.name
            INTO v_stock_balance
            FROM inventory.stock_balances sb
            JOIN inventory.catalog_items ci ON sb.catalog_item_id = ci.id
            WHERE sb.tenant_id = p_tenant_id
              AND sb.catalog_item_id = (v_line->>'catalog_item_id')::uuid
              AND sb.location_id = p_from_location_id;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Item "%" has no inventory at location "%". Cannot create transfer.',
                    v_item_name, v_location_name;
            END IF;

            IF v_stock_balance.qty_on_hand < (v_line->>'qty')::numeric THEN
                RAISE EXCEPTION 'Insufficient stock for item "%" at location "%". Available: %, Requested: %',
                    v_stock_balance.name,
                    v_location_name,
                    v_stock_balance.qty_on_hand,
                    (v_line->>'qty')::numeric;
            END IF;
        END IF;
    END LOOP;

    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;

    v_transfer_number := 'TRF-' || to_char(NOW(), 'YYYYMMDD') || '-' || LPAD(FLOOR(RANDOM() * 10000)::TEXT, 4, '0') || SUBSTRING(gen_random_uuid()::TEXT, 1, 4);

    LOOP
        BEGIN
            INSERT INTO inventory.transfers (
                tenant_id,
                transfer_number,
                from_location_id,
                to_location_id,
                status,
                initiated_by_user_id,
                notes,
                last_event_id
            ) VALUES (
                p_tenant_id,
                v_transfer_number,
                p_from_location_id,
                p_to_location_id,
                'draft',
                p_initiated_by_user_id,
                p_notes,
                v_event_id
            )
            ON CONFLICT (tenant_id, last_event_id) DO NOTHING
            RETURNING id INTO v_transfer_id;

            IF v_transfer_id IS NOT NULL THEN
                EXIT;
            END IF;

            SELECT id INTO v_transfer_id
            FROM inventory.transfers
            WHERE tenant_id = p_tenant_id
              AND last_event_id = v_event_id;

            IF v_transfer_id IS NOT NULL THEN
                RETURN v_transfer_id;
            END IF;

        EXCEPTION
            WHEN unique_violation THEN
                IF SQLERRM LIKE '%transfers_tenant_transfer_number_unique%' THEN
                    v_transfer_number := 'TRF-' || to_char(NOW(), 'YYYYMMDD') || '-' || LPAD(FLOOR(RANDOM() * 10000)::TEXT, 4, '0') || SUBSTRING(gen_random_uuid()::TEXT, 1, 4);
                    CONTINUE;
                ELSE
                    RAISE;
                END IF;
        END;
    END LOOP;

    v_line_number := 1;
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
        SELECT tracking_mode INTO v_tracking_mode
        FROM inventory.catalog_items
        WHERE id = (v_line->>'catalog_item_id')::uuid
          AND tenant_id = p_tenant_id;

        v_asset_ids := v_line->'asset_ids';

        IF v_tracking_mode = 'serialized' THEN
            v_requested_qty := jsonb_array_length(v_asset_ids);
        ELSE
            v_requested_qty := (v_line->>'qty')::integer;
        END IF;

        INSERT INTO inventory.transfer_lines (
            tenant_id,
            transfer_id,
            line_number,
            catalog_item_id,
            qty,
            last_event_id
        ) VALUES (
            p_tenant_id,
            v_transfer_id,
            v_line_number,
            (v_line->>'catalog_item_id')::uuid,
            v_requested_qty,
            v_event_id || '_line_' || v_line_number
        )
        RETURNING id INTO v_line_id;

        IF v_tracking_mode = 'serialized' THEN
            INSERT INTO inventory.transfer_assets (
                tenant_id,
                transfer_id,
                transfer_line_id,
                asset_id
            )
            SELECT
                p_tenant_id,
                v_transfer_id,
                v_line_id,
                (jsonb_array_elements_text(v_asset_ids))::uuid;
        END IF;

        v_line_number := v_line_number + 1;
    END LOOP;

    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'transfer.created',
        p_aggregate_type => 'transfer',
        p_aggregate_id => v_transfer_id,
        p_payload => jsonb_build_object(
            'transfer_id', v_transfer_id,
            'from_location_id', p_from_location_id,
            'to_location_id', p_to_location_id,
            'line_count', jsonb_array_length(p_lines)
        )
    );

    RETURN v_transfer_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_create"("p_tenant_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_lines" "jsonb", "p_initiated_by_user_id" "uuid", "p_notes" "text", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_create"("p_tenant_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_lines" "jsonb", "p_initiated_by_user_id" "uuid", "p_notes" "text", "p_last_event_id" "text") IS 'Creates transfer in draft status with validation for both fungible (stock) and serialized (assets) items';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_create_reversal"("p_tenant_id" "uuid", "p_original_transfer_id" "uuid", "p_initiated_by_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_original_transfer RECORD;
    v_reversal_id UUID;
    v_transfer_number TEXT;
    v_line RECORD;
    v_line_number INTEGER := 1;
    v_event_id TEXT;
    v_reversal_qty NUMERIC;
BEGIN
    -- Validate tenant
    IF p_tenant_id IS NULL THEN
        RAISE EXCEPTION 'tenant_id is required';
    END IF;
    
    -- Get original transfer
    SELECT * INTO v_original_transfer
    FROM inventory.transfers
    WHERE id = p_original_transfer_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Original transfer not found';
    END IF;
    
    -- Can only reverse completed transfers
    IF v_original_transfer.status != 'completed' THEN
        RAISE EXCEPTION 'Can only reverse completed transfers. Current status: %', v_original_transfer.status;
    END IF;
    
    -- Check if already reversed
    IF EXISTS (
        SELECT 1 FROM inventory.transfers 
        WHERE reversal_of_transfer_id = p_original_transfer_id
        AND status != 'cancelled'
    ) THEN
        RAISE EXCEPTION 'Transfer has already been reversed';
    END IF;
    
    -- Require event ID for strict idempotency
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Generate transfer number
    v_transfer_number := 'REV-' || v_original_transfer.transfer_number;
    
    -- Create reversal transfer (opposite direction)
    INSERT INTO inventory.transfers (
        tenant_id,
        transfer_number,
        from_location_id,
        to_location_id,
        status,
        initiated_by_user_id,
        notes,
        last_event_id,
        reversal_of_transfer_id,
        is_reversal
    ) VALUES (
        p_tenant_id,
        v_transfer_number,
        v_original_transfer.to_location_id, -- Reverse: from becomes to
        v_original_transfer.from_location_id, -- Reverse: to becomes from
        'draft',
        p_initiated_by_user_id,
        COALESCE(p_notes, 'Reversal of transfer #' || v_original_transfer.transfer_number),
        v_event_id,
        p_original_transfer_id,
        true
    )
    RETURNING id INTO v_reversal_id;
    
    -- Copy lines from original transfer
    FOR v_line IN 
        SELECT * FROM inventory.transfer_lines
        WHERE transfer_id = p_original_transfer_id
        ORDER BY line_number
    LOOP
        -- Use qty_received if available (and > 0), then qty_shipped if available (and > 0), otherwise fall back to qty
        -- This handles transfers completed before qty tracking was added
        v_reversal_qty := COALESCE(
            NULLIF(v_line.qty_received, 0), 
            NULLIF(v_line.qty_shipped, 0), 
            v_line.qty
        );
        
        IF v_reversal_qty <= 0 THEN
            RAISE EXCEPTION 'Cannot create reversal: line % has invalid quantity', v_line.line_number;
        END IF;
        
        INSERT INTO inventory.transfer_lines (
            tenant_id,
            transfer_id,
            line_number,
            catalog_item_id,
            qty,
            qty_shipped,
            last_event_id
        ) VALUES (
            p_tenant_id,
            v_reversal_id,
            v_line_number,
            v_line.catalog_item_id,
            v_reversal_qty, -- Reverse the received quantity (or original qty if not tracked)
            v_reversal_qty, -- Pre-set as shipped since we know this qty exists
            v_event_id || '_line_' || v_line_number
        );
        
        v_line_number := v_line_number + 1;
    END LOOP;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'transfer.reversal_created',
        p_aggregate_type => 'transfer',
        p_aggregate_id => v_reversal_id,
        p_payload => jsonb_build_object(
            'reversal_id', v_reversal_id,
            'reversal_number', v_transfer_number,
            'original_transfer_id', p_original_transfer_id,
            'original_transfer_number', v_original_transfer.transfer_number
        )
    );
    
    RETURN v_reversal_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_create_reversal"("p_tenant_id" "uuid", "p_original_transfer_id" "uuid", "p_initiated_by_user_id" "uuid", "p_notes" "text", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_create_reversal"("p_tenant_id" "uuid", "p_original_transfer_id" "uuid", "p_initiated_by_user_id" "uuid", "p_notes" "text", "p_last_event_id" "text") IS 'Creates a reversal transfer for a completed transfer, copying lines and reversing direction. Handles transfers completed before qty_received tracking.';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_execute"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_received_by_user_id" "uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_transfer record;
    v_line record;
    v_correlation_id uuid;
    v_event_id text;
    v_now timestamptz := now();
BEGIN
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;

    SELECT * INTO v_transfer
    FROM inventory.transfers
    WHERE id = p_transfer_id
      AND tenant_id = p_tenant_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer not found';
    END IF;

    IF v_transfer.status NOT IN ('draft', 'in_transit') THEN
        RAISE EXCEPTION 'Transfer cannot be executed in status: %', v_transfer.status;
    END IF;

    v_correlation_id := gen_random_uuid();

    FOR v_line IN
        SELECT * FROM inventory.transfer_lines
        WHERE transfer_id = p_transfer_id
        ORDER BY line_number
    LOOP
        PERFORM 1;
        IF EXISTS (
            SELECT 1
            FROM inventory.catalog_items ci
            WHERE ci.id = v_line.catalog_item_id
              AND ci.tracking_mode IN ('serialized', 'both', 'hybrid')
        ) THEN
            -- Serialized assets: skip stock balances, location is updated below
            CONTINUE;
        END IF;

        PERFORM inventory.insert_stock_movement(
            p_tenant_id => p_tenant_id,
            p_catalog_item_id => v_line.catalog_item_id,
            p_location_id => v_transfer.from_location_id,
            p_quantity_delta => -v_line.qty,
            p_movement_type => 'transferred_out',
            p_source_ref_type => 'transfer',
            p_source_ref_id => p_transfer_id,
            p_unit_cost => NULL,
            p_reason => 'Transfer to ' || (SELECT name FROM inventory.locations WHERE id = v_transfer.to_location_id),
            p_notes => 'Transfer #' || v_transfer.transfer_number,
            p_correlation_id => v_correlation_id,
            p_occurred_at => v_now,
            p_created_by_user_id => p_received_by_user_id,
            p_last_event_id => v_event_id || '_out_' || v_line.line_number
        );

        PERFORM inventory.insert_stock_movement(
            p_tenant_id => p_tenant_id,
            p_catalog_item_id => v_line.catalog_item_id,
            p_location_id => v_transfer.to_location_id,
            p_quantity_delta => v_line.qty,
            p_movement_type => 'transferred_in',
            p_source_ref_type => 'transfer',
            p_source_ref_id => p_transfer_id,
            p_unit_cost => NULL,
            p_reason => 'Transfer from ' || (SELECT name FROM inventory.locations WHERE id = v_transfer.from_location_id),
            p_notes => 'Transfer #' || v_transfer.transfer_number,
            p_correlation_id => v_correlation_id,
            p_occurred_at => v_now,
            p_created_by_user_id => p_received_by_user_id,
            p_last_event_id => v_event_id || '_in_' || v_line.line_number
        );
    END LOOP;

    UPDATE inventory.assets a
    SET
        location_id = v_transfer.to_location_id,
        updated_at = v_now
    FROM inventory.transfer_assets ta
    WHERE ta.transfer_id = p_transfer_id
      AND ta.tenant_id = p_tenant_id
      AND a.id = ta.asset_id
      AND a.tenant_id = p_tenant_id;

    UPDATE inventory.transfers
    SET
        status = 'completed',
        received_by_user_id = p_received_by_user_id,
        completed_at = v_now,
        updated_at = v_now
    WHERE id = p_transfer_id;

    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'transfer.completed',
        p_aggregate_type => 'transfer',
        p_aggregate_id => p_transfer_id,
        p_payload => jsonb_build_object(
            'transfer_id', p_transfer_id,
            'transfer_number', v_transfer.transfer_number,
            'from_location_id', v_transfer.from_location_id,
            'to_location_id', v_transfer.to_location_id,
            'correlation_id', v_correlation_id
        )
    );

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_execute"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_received_by_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_execute"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_received_by_user_id" "uuid", "p_last_event_id" "text") IS 'Executes transfer by writing paired ledger entries (idempotent) and updates serialized asset locations on receipt';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_receive_partial"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_received_by_user_id" "uuid", "p_line_quantities" "jsonb", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_transfer RECORD;
    v_line RECORD;
    v_receive_qty NUMERIC;
    v_correlation_id UUID;
    v_event_id TEXT;
    v_now TIMESTAMPTZ := NOW();
    v_all_lines_complete BOOLEAN := TRUE;
BEGIN
    -- Require event ID for strict idempotency
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Get transfer
    SELECT * INTO v_transfer
    FROM inventory.transfers
    WHERE id = p_transfer_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer not found';
    END IF;
    
    IF v_transfer.status NOT IN ('in_transit', 'partially_received') THEN
        RAISE EXCEPTION 'Transfer cannot be received in status: %. Must be in_transit or partially_received.', v_transfer.status;
    END IF;
    
    -- Generate correlation ID for paired entries
    v_correlation_id := gen_random_uuid();
    
    -- Process each line with received quantity
    FOR v_line IN 
        SELECT tl.*, (lq.value->>'qty_received')::NUMERIC as qty_to_receive
        FROM inventory.transfer_lines tl
        JOIN jsonb_array_elements(p_line_quantities) lq ON (lq.value->>'line_number')::INTEGER = tl.line_number
        WHERE tl.transfer_id = p_transfer_id
        ORDER BY tl.line_number
    LOOP
        -- Validate received quantity
        IF v_line.qty_to_receive <= 0 THEN
            RAISE EXCEPTION 'Received quantity must be greater than 0 for line %', v_line.line_number;
        END IF;
        
        IF v_line.qty_received + v_line.qty_to_receive > v_line.qty_shipped THEN
            RAISE EXCEPTION 'Cannot receive more than shipped quantity for line %. Shipped: %, Already received: %, Trying to receive: %', 
                v_line.line_number, v_line.qty_shipped, v_line.qty_received, v_line.qty_to_receive;
        END IF;
        
        -- Debit from source location (transferred_out)
        PERFORM inventory.insert_stock_movement(
            p_tenant_id => p_tenant_id,
            p_catalog_item_id => v_line.catalog_item_id,
            p_location_id => v_transfer.from_location_id,
            p_quantity_delta => -v_line.qty_to_receive,
            p_movement_type => 'transferred_out',
            p_source_ref_type => 'transfer',
            p_source_ref_id => p_transfer_id,
            p_unit_cost => NULL,
            p_reason => 'Transfer to ' || (SELECT name FROM inventory.locations WHERE id = v_transfer.to_location_id),
            p_notes => 'Transfer #' || v_transfer.transfer_number || ' - Partial receive',
            p_correlation_id => v_correlation_id,
            p_occurred_at => v_now,
            p_created_by_user_id => p_received_by_user_id,
            p_last_event_id => v_event_id || '_out_' || v_line.line_number
        );
        
        -- Credit to destination location (transferred_in)
        PERFORM inventory.insert_stock_movement(
            p_tenant_id => p_tenant_id,
            p_catalog_item_id => v_line.catalog_item_id,
            p_location_id => v_transfer.to_location_id,
            p_quantity_delta => v_line.qty_to_receive,
            p_movement_type => 'transferred_in',
            p_source_ref_type => 'transfer',
            p_source_ref_id => p_transfer_id,
            p_unit_cost => NULL,
            p_reason => 'Transfer from ' || (SELECT name FROM inventory.locations WHERE id = v_transfer.from_location_id),
            p_notes => 'Transfer #' || v_transfer.transfer_number || ' - Partial receive',
            p_correlation_id => v_correlation_id,
            p_occurred_at => v_now,
            p_created_by_user_id => p_received_by_user_id,
            p_last_event_id => v_event_id || '_in_' || v_line.line_number
        );
        
        -- Update line quantities
        UPDATE inventory.transfer_lines
        SET qty_received = qty_received + v_line.qty_to_receive
        WHERE id = v_line.id;
    END LOOP;
    
    -- Check if all lines are fully received
    SELECT BOOL_AND(qty_received >= qty_shipped) INTO v_all_lines_complete
    FROM inventory.transfer_lines
    WHERE transfer_id = p_transfer_id;
    
    -- Update transfer status
    UPDATE inventory.transfers
    SET 
        status = CASE 
            WHEN v_all_lines_complete THEN 'completed'
            ELSE 'partially_received'
        END,
        received_by_user_id = p_received_by_user_id,
        completed_at = CASE WHEN v_all_lines_complete THEN v_now ELSE NULL END,
        updated_at = v_now
    WHERE id = p_transfer_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => CASE 
            WHEN v_all_lines_complete THEN 'transfer.completed'
            ELSE 'transfer.partially_received'
        END,
        p_aggregate_type => 'transfer',
        p_aggregate_id => p_transfer_id,
        p_payload => jsonb_build_object(
            'transfer_id', p_transfer_id,
            'transfer_number', v_transfer.transfer_number,
            'from_location_id', v_transfer.from_location_id,
            'to_location_id', v_transfer.to_location_id,
            'correlation_id', v_correlation_id,
            'is_complete', v_all_lines_complete
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_receive_partial"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_received_by_user_id" "uuid", "p_line_quantities" "jsonb", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_receive_partial"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_received_by_user_id" "uuid", "p_line_quantities" "jsonb", "p_last_event_id" "text") IS 'Receives specific quantities for transfer lines, supports partial receives and multiple receive operations';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_reverse_receipt"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_reversed_by_user_id" "uuid", "p_reason" "text", "p_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_transfer RECORD;
    v_line RECORD;
    v_event_id TEXT;
    v_correlation_id UUID;
BEGIN
    -- Require event ID for strict idempotency
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    v_correlation_id := gen_random_uuid();
    
    -- Get transfer
    SELECT * INTO v_transfer
    FROM inventory.transfers
    WHERE id = p_transfer_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer not found';
    END IF;
    
    -- Can only reverse receipt if completed or partially_received
    IF v_transfer.status NOT IN ('completed', 'partially_received') THEN
        RAISE EXCEPTION 'Can only reverse receipt for completed/partially_received transfers. Current status: %', v_transfer.status;
    END IF;
    
    -- Check if already reversed
    IF v_transfer.receipt_reversed_at IS NOT NULL THEN
        RAISE EXCEPTION 'Receipt has already been reversed';
    END IF;
    
    -- Require reason
    IF p_reason IS NULL OR p_reason = '' THEN
        RAISE EXCEPTION 'Reason is required for reversing receipt';
    END IF;
    
    -- Create corrective stock movements (negate the original receive)
    FOR v_line IN 
        SELECT * FROM inventory.transfer_lines
        WHERE transfer_id = p_transfer_id
        AND qty_received > 0
    LOOP
        -- Debit from destination (negate the credit from receive)
        PERFORM inventory.insert_stock_movement(
            p_tenant_id => p_tenant_id,
            p_catalog_item_id => v_line.catalog_item_id,
            p_location_id => v_transfer.to_location_id,
            p_quantity_delta => -v_line.qty_received,
            p_movement_type => 'correction',
            p_source_ref_type => 'transfer',
            p_source_ref_id => p_transfer_id,
            p_unit_cost => NULL,
            p_reason => 'Receipt reversal: ' || p_reason,
            p_notes => 'Corrective entry - negating transfer #' || v_transfer.transfer_number,
            p_correlation_id => v_correlation_id,
            p_occurred_at => NOW(),
            p_created_by_user_id => p_reversed_by_user_id,
            p_last_event_id => v_event_id || '_to_' || v_line.line_number
        );
        
        -- Credit back to source (negate the debit from receive)
        PERFORM inventory.insert_stock_movement(
            p_tenant_id => p_tenant_id,
            p_catalog_item_id => v_line.catalog_item_id,
            p_location_id => v_transfer.from_location_id,
            p_quantity_delta => v_line.qty_received,
            p_movement_type => 'correction',
            p_source_ref_type => 'transfer',
            p_source_ref_id => p_transfer_id,
            p_unit_cost => NULL,
            p_reason => 'Receipt reversal: ' || p_reason,
            p_notes => 'Corrective entry - negating transfer #' || v_transfer.transfer_number,
            p_correlation_id => v_correlation_id,
            p_occurred_at => NOW(),
            p_created_by_user_id => p_reversed_by_user_id,
            p_last_event_id => v_event_id || '_from_' || v_line.line_number
        );
    END LOOP;
    
    -- Reset qty_received to 0 on all lines
    UPDATE inventory.transfer_lines
    SET qty_received = 0
    WHERE transfer_id = p_transfer_id;
    
    -- Revert status to in_transit
    UPDATE inventory.transfers
    SET 
        status = 'in_transit',
        completed_at = NULL,
        receipt_reversed_at = NOW(),
        receipt_reversed_by_user_id = p_reversed_by_user_id,
        receipt_reversed_reason = p_reason,
        notes = CASE 
            WHEN p_notes IS NOT NULL THEN COALESCE(notes || E'\n\n', '') || 'RECEIPT REVERSED: ' || p_notes
            ELSE notes
        END,
        updated_at = NOW()
    WHERE id = p_transfer_id;
    
    -- Publish correction event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'transfer.receipt_reversed',
        p_aggregate_type => 'transfer',
        p_aggregate_id => p_transfer_id,
        p_payload => jsonb_build_object(
            'transfer_id', p_transfer_id,
            'transfer_number', v_transfer.transfer_number,
            'reason', p_reason,
            'reversed_by', p_reversed_by_user_id,
            'correlation_id', v_correlation_id
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_reverse_receipt"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_reversed_by_user_id" "uuid", "p_reason" "text", "p_notes" "text", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_reverse_receipt"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_reversed_by_user_id" "uuid", "p_reason" "text", "p_notes" "text", "p_last_event_id" "text") IS 'Reverses a receipt (correction only - no physical movement). Creates corrective stock movements and reverts to in_transit.';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_undo_cancel"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_user_id" "uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_transfer RECORD;
    v_event_id TEXT;
BEGIN
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Get transfer
    SELECT * INTO v_transfer
    FROM inventory.transfers
    WHERE id = p_transfer_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer not found';
    END IF;
    
    IF v_transfer.status != 'cancelled' THEN
        RAISE EXCEPTION 'Can only undo cancelled transfers. Current status: %', v_transfer.status;
    END IF;
    
    -- Restore to draft status
    UPDATE inventory.transfers
    SET 
        status = 'draft',
        updated_at = NOW()
    WHERE id = p_transfer_id
    AND tenant_id = p_tenant_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'transfer.cancel_undone',
        p_aggregate_type => 'transfer',
        p_aggregate_id => p_transfer_id,
        p_payload => jsonb_build_object(
            'transfer_id', p_transfer_id,
            'from_location_id', v_transfer.from_location_id,
            'to_location_id', v_transfer.to_location_id
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_undo_cancel"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_undo_cancel"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_user_id" "uuid", "p_last_event_id" "text") IS 'Reverses a cancelled transfer back to draft status';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_undo_shipment"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_undone_by_user_id" "uuid", "p_reason" "text", "p_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_transfer RECORD;
    v_event_id TEXT;
BEGIN
    -- Require event ID for strict idempotency
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Get transfer
    SELECT * INTO v_transfer
    FROM inventory.transfers
    WHERE id = p_transfer_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer not found';
    END IF;
    
    -- Can only undo shipment if in_transit
    IF v_transfer.status != 'in_transit' THEN
        RAISE EXCEPTION 'Can only undo shipment for in_transit transfers. Current status: %', v_transfer.status;
    END IF;
    
    -- Check if already undone
    IF v_transfer.ship_undone_at IS NOT NULL THEN
        RAISE EXCEPTION 'Shipment has already been undone';
    END IF;
    
    -- Require reason
    IF p_reason IS NULL OR p_reason = '' THEN
        RAISE EXCEPTION 'Reason is required for undoing shipment';
    END IF;
    
    -- Revert status to draft
    UPDATE inventory.transfers
    SET 
        status = 'draft',
        ship_undone_at = NOW(),
        ship_undone_by_user_id = p_undone_by_user_id,
        ship_undone_reason = p_reason,
        notes = CASE 
            WHEN p_notes IS NOT NULL THEN COALESCE(notes || E'\n\n', '') || 'SHIPMENT UNDONE: ' || p_notes
            ELSE notes
        END,
        updated_at = NOW()
    WHERE id = p_transfer_id;
    
    -- Publish correction event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'transfer.shipment_undone',
        p_aggregate_type => 'transfer',
        p_aggregate_id => p_transfer_id,
        p_payload => jsonb_build_object(
            'transfer_id', p_transfer_id,
            'transfer_number', v_transfer.transfer_number,
            'reason', p_reason,
            'undone_by', p_undone_by_user_id
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_undo_shipment"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_undone_by_user_id" "uuid", "p_reason" "text", "p_notes" "text", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_undo_shipment"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_undone_by_user_id" "uuid", "p_reason" "text", "p_notes" "text", "p_last_event_id" "text") IS 'Undoes a shipment (correction only - no physical movement). Reverts in_transit → draft.';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_undo_fulfill_reservation"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_reservation RECORD;
    v_movement_id UUID;
    v_event_id TEXT;
BEGIN
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Get reservation
    SELECT * INTO v_reservation
    FROM inventory.reservations
    WHERE id = p_reservation_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Reservation not found';
    END IF;
    
    IF v_reservation.status != 'fulfilled' THEN
        RAISE EXCEPTION 'Can only undo fulfilled reservations. Current status: %', v_reservation.status;
    END IF;
    
    -- Handle based on reservation type
    IF v_reservation.reservation_type = 'fungible' THEN
        -- Fungible: reverse the stock movement and restore reservation
        
        -- Add stock back (reverse the issue)
        v_movement_id := inventory.insert_stock_movement(
            p_tenant_id => p_tenant_id,
            p_catalog_item_id => v_reservation.catalog_item_id,
            p_location_id => v_reservation.location_id,
            p_quantity_delta => v_reservation.qty,
            p_movement_type => 'adjustment',
            p_source_ref_type => 'reservation',
            p_source_ref_id => p_reservation_id,
            p_unit_cost => NULL,
            p_reason => 'Undo fulfillment',
            p_notes => 'Reversed fulfillment - restoring stock and reservation',
            p_correlation_id => NULL,
            p_occurred_at => NOW(),
            p_created_by_user_id => p_user_id,
            p_last_event_id => v_event_id || '_movement'
        );
        
        -- Restore qty_reserved
        UPDATE inventory.stock_balances
        SET 
            qty_reserved = qty_reserved + v_reservation.qty,
            updated_at = NOW()
        WHERE tenant_id = p_tenant_id
        AND catalog_item_id = v_reservation.catalog_item_id
        AND location_id = v_reservation.location_id;
        
    ELSIF v_reservation.reservation_type = 'serialized' THEN
        -- Serialized: asset is still 'assigned', no status change needed
        -- (Asset remains assigned to the reservation)
        NULL;
    ELSE
        RAISE EXCEPTION 'Unknown reservation_type: %', v_reservation.reservation_type;
    END IF;
    
    -- Update reservation back to active
    UPDATE inventory.reservations
    SET 
        status = 'active',
        fulfilled_by_user_id = NULL,
        fulfilled_at = NULL,
        updated_at = NOW()
    WHERE id = p_reservation_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'reservation.fulfill_undone',
        p_aggregate_type => 'reservation',
        p_aggregate_id => p_reservation_id,
        p_payload => jsonb_build_object(
            'reservation_id', p_reservation_id,
            'reservation_type', v_reservation.reservation_type,
            'catalog_item_id', v_reservation.catalog_item_id,
            'asset_id', v_reservation.asset_id,
            'qty', v_reservation.qty
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_undo_fulfill_reservation"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_undo_fulfill_reservation"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_last_event_id" "text") IS 'Reverses a fulfilled reservation back to active status. For fungible: adds stock back and restores qty_reserved. For serialized: keeps asset assigned.';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_undo_release_reservation"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_reservation RECORD;
    v_event_id TEXT;
    v_current_qty_available NUMERIC;
BEGIN
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Get reservation
    SELECT * INTO v_reservation
    FROM inventory.reservations
    WHERE id = p_reservation_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Reservation not found';
    END IF;
    
    IF v_reservation.status != 'released' THEN
        RAISE EXCEPTION 'Can only undo released reservations. Current status: %', v_reservation.status;
    END IF;
    
    -- Handle based on reservation type
    IF v_reservation.reservation_type = 'fungible' THEN
        -- Fungible: check if sufficient stock is available to re-reserve
        SELECT COALESCE(qty_available, 0) INTO v_current_qty_available
        FROM inventory.stock_balances
        WHERE tenant_id = p_tenant_id
        AND catalog_item_id = v_reservation.catalog_item_id
        AND location_id = v_reservation.location_id;
        
        IF v_current_qty_available < v_reservation.qty THEN
            RAISE EXCEPTION 'Insufficient stock available to restore reservation. Available: %, Required: %', 
                v_current_qty_available, v_reservation.qty;
        END IF;
        
        -- Restore qty_reserved
        UPDATE inventory.stock_balances
        SET 
            qty_reserved = qty_reserved + v_reservation.qty,
            updated_at = NOW()
        WHERE tenant_id = p_tenant_id
        AND catalog_item_id = v_reservation.catalog_item_id
        AND location_id = v_reservation.location_id;
        
    ELSIF v_reservation.reservation_type = 'serialized' THEN
        -- Serialized: verify asset is available before re-assigning
        DECLARE
            v_asset_status TEXT;
        BEGIN
            SELECT status INTO v_asset_status
            FROM inventory.assets
            WHERE id = v_reservation.asset_id
            AND tenant_id = p_tenant_id;
            
            IF v_asset_status IS NULL THEN
                RAISE EXCEPTION 'Asset not found';
            END IF;
            
            IF v_asset_status != 'available' THEN
                RAISE EXCEPTION 'Asset is not available. Current status: %', v_asset_status;
            END IF;
            
            -- Re-assign asset
            UPDATE inventory.assets
            SET 
                status = 'assigned',
                updated_at = NOW()
            WHERE id = v_reservation.asset_id
            AND tenant_id = p_tenant_id;
        END;
    ELSE
        RAISE EXCEPTION 'Unknown reservation_type: %', v_reservation.reservation_type;
    END IF;
    
    -- Update reservation back to active
    UPDATE inventory.reservations
    SET 
        status = 'active',
        updated_at = NOW()
    WHERE id = p_reservation_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'reservation.release_undone',
        p_aggregate_type => 'reservation',
        p_aggregate_id => p_reservation_id,
        p_payload => jsonb_build_object(
            'reservation_id', p_reservation_id,
            'reservation_type', v_reservation.reservation_type,
            'catalog_item_id', v_reservation.catalog_item_id,
            'asset_id', v_reservation.asset_id,
            'qty', v_reservation.qty
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_undo_release_reservation"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_undo_release_reservation"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_last_event_id" "text") IS 'Reverses a released reservation back to active status. For fungible: restores qty_reserved. For serialized: re-assigns asset.';



CREATE OR REPLACE FUNCTION "inventory"."rpc_issue_inventory"("p_location_id" "uuid", "p_items" "jsonb", "p_issued_to_type" "text" DEFAULT NULL::"text", "p_issued_to_ref" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_item JSONB;
  v_event_id TEXT;
  v_issued_count INT := 0;
  v_result JSONB;
BEGIN
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Process each item
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_event_id := 'issue-' || gen_random_uuid()::TEXT || '-' || extract(epoch from now())::TEXT;
    
    -- Check availability
    IF NOT EXISTS (
      SELECT 1 FROM inventory.stock_balances
      WHERE tenant_id = v_tenant_id
        AND catalog_item_id = (v_item->>'catalog_item_id')::UUID
        AND location_id = p_location_id
        AND qty_available >= (v_item->>'qty_issued')::NUMERIC
    ) THEN
      RAISE EXCEPTION 'Insufficient stock for item % at location %',
        v_item->>'catalog_item_id', p_location_id;
    END IF;
    
    -- Insert inventory event
    INSERT INTO inventory.inventory_events (
      tenant_id,
      catalog_item_id,
      location_id,
      event_type,
      quantity_delta,
      payload,
      occurred_at,
      actor_user_id,
      last_event_id
    ) VALUES (
      v_tenant_id,
      (v_item->>'catalog_item_id')::UUID,
      p_location_id,
      'issue',
      -(v_item->>'qty_issued')::NUMERIC, -- NEGATIVE
      jsonb_build_object(
        'issued_to_type', p_issued_to_type,
        'issued_to_ref', p_issued_to_ref,
        'reason', p_reason
      ),
      NOW(),
      (auth.jwt() ->> 'user_id')::UUID,
      v_event_id
    );
    
    -- Insert stock movement
    INSERT INTO inventory.stock_movements (
      tenant_id,
      catalog_item_id,
      location_id,
      quantity_delta,
      movement_type,
      source_ref_type,
      reason,
      notes,
      occurred_at,
      created_by_user_id,
      last_event_id
    ) VALUES (
      v_tenant_id,
      (v_item->>'catalog_item_id')::UUID,
      p_location_id,
      -(v_item->>'qty_issued')::NUMERIC, -- NEGATIVE
      'issued',
      p_issued_to_type,
      p_reason,
      p_notes,
      NOW(),
      (auth.jwt() ->> 'user_id')::UUID,
      v_event_id
    );
    
    -- Update stock balances
    UPDATE inventory.stock_balances
    SET
      qty_on_hand = qty_on_hand - (v_item->>'qty_issued')::NUMERIC,
      qty_available = qty_available - (v_item->>'qty_issued')::NUMERIC,
      last_event_id = v_event_id,
      updated_at = NOW()
    WHERE tenant_id = v_tenant_id
      AND catalog_item_id = (v_item->>'catalog_item_id')::UUID
      AND location_id = p_location_id;
    
    v_issued_count := v_issued_count + 1;
  END LOOP;
  
  v_result := jsonb_build_object(
    'success', true,
    'issued_count', v_issued_count,
    'location_id', p_location_id,
    'issued_to', jsonb_build_object('type', p_issued_to_type, 'ref', p_issued_to_ref)
  );
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION "inventory"."rpc_issue_inventory"("p_location_id" "uuid", "p_items" "jsonb", "p_issued_to_type" "text", "p_issued_to_ref" "text", "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_issue_inventory"("p_location_id" "uuid", "p_items" "jsonb", "p_issued_to_type" "text", "p_issued_to_ref" "text", "p_reason" "text", "p_notes" "text") IS 'Frontend RPC: Issue inventory from a location.
Validates availability, creates events and movements, updates balances.
Returns: {success, issued_count, location_id, issued_to}';



CREATE OR REPLACE FUNCTION "inventory"."rpc_mark_alert_ordered"("p_alert_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_tenant_id UUID;
BEGIN
  v_tenant_id := current_tenant_id();
  
  -- Update alert
  UPDATE inventory.reorder_alerts
  SET
    status = 'ordered',
    updated_at = now()
  WHERE id = p_alert_id
    AND tenant_id = v_tenant_id
    AND status IN ('open', 'acknowledged');
    
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert not found or already processed';
  END IF;
END;
$$;


ALTER FUNCTION "inventory"."rpc_mark_alert_ordered"("p_alert_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."rpc_reverse_stock_movement"("p_tenant_id" "uuid", "p_movement_id" "uuid", "p_reason" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'inventory', 'public'
    AS $$
DECLARE
    v_movement RECORD;
    v_reversal_id UUID;
    v_event_id TEXT;
BEGIN
    IF p_last_event_id IS NULL THEN
        RAISE EXCEPTION 'p_last_event_id is required';
    END IF;
    v_event_id := p_last_event_id;
    
    -- Get original movement
    SELECT * INTO v_movement
    FROM inventory.stock_movements
    WHERE id = p_movement_id
      AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Stock movement not found';
    END IF;
    
    -- Validate can be reversed
    IF v_movement.posting_status = 'reversed' THEN
        RAISE EXCEPTION 'Movement already reversed';
    END IF;
    
    IF v_movement.posting_status = 'pending' THEN
        RAISE EXCEPTION 'Cannot reverse pending movement, delete it instead';
    END IF;
    
    -- Check if already has reversal
    IF EXISTS (
        SELECT 1 FROM inventory.stock_movements 
        WHERE reversal_ref_id = p_movement_id 
        AND posting_status = 'posted'
    ) THEN
        RAISE EXCEPTION 'Movement already has an active reversal';
    END IF;
    
    -- Create offsetting movement
    v_reversal_id := inventory.insert_stock_movement(
        p_tenant_id => p_tenant_id,
        p_catalog_item_id => v_movement.catalog_item_id,
        p_location_id => v_movement.location_id,
        p_quantity_delta => -v_movement.quantity_delta,  -- Negate original delta
        p_movement_type => 'adjusted',
        p_source_ref_type => 'reversal',
        p_source_ref_id => p_movement_id,
        p_unit_cost => v_movement.unit_cost,
        p_reason => 'REVERSAL: ' || COALESCE(p_reason, 'Correcting erroneous movement'),
        p_notes => 'Reverses movement ' || p_movement_id::TEXT || '. Original: ' || COALESCE(v_movement.notes, 'N/A'),
        p_correlation_id => v_movement.correlation_id,
        p_occurred_at => NOW(),
        p_created_by_user_id => p_user_id,
        p_last_event_id => v_event_id
    );
    
    -- Update reversal reference
    UPDATE inventory.stock_movements
    SET reversal_ref_id = p_movement_id
    WHERE id = v_reversal_id;
    
    -- Mark original as reversed
    UPDATE inventory.stock_movements
    SET posting_status = 'reversed'
    WHERE id = p_movement_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'stock_movement.reversed',
        p_aggregate_type => 'stock_movement',
        p_aggregate_id => p_movement_id,
        p_payload => jsonb_build_object(
            'original_movement_id', p_movement_id,
            'reversal_movement_id', v_reversal_id,
            'catalog_item_id', v_movement.catalog_item_id,
            'location_id', v_movement.location_id,
            'original_delta', v_movement.quantity_delta,
            'reversal_delta', -v_movement.quantity_delta,
            'reason', p_reason
        ),
        p_metadata => jsonb_build_object(
            'reversed_by_user_id', p_user_id,
            'reversed_at', NOW()
        )
    );
    
    RETURN v_reversal_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_reverse_stock_movement"("p_tenant_id" "uuid", "p_movement_id" "uuid", "p_reason" "text", "p_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_reverse_stock_movement"("p_tenant_id" "uuid", "p_movement_id" "uuid", "p_reason" "text", "p_user_id" "uuid", "p_last_event_id" "text") IS 'Reverses a stock movement by creating an offsetting entry. Original marked as reversed, new movement references original. Idempotent via last_event_id.';



CREATE OR REPLACE FUNCTION "inventory"."seed_default_assignment_types"("p_tenant_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Only seed if tenant has no assignment types
    IF NOT EXISTS (SELECT 1 FROM inventory.assignment_types WHERE tenant_id = p_tenant_id) THEN
        INSERT INTO inventory.assignment_types (tenant_id, type_key, display_name, icon, is_system, sort_order, description) VALUES
            (p_tenant_id, 'employee', 'Employee', '👤', true, 10, 'Assign to individual employee'),
            (p_tenant_id, 'crew', 'Crew', '👥', false, 20, 'Assign to work crew or team'),
            (p_tenant_id, 'vehicle', 'Vehicle', '🚛', true, 30, 'Assign to company vehicle or truck'),
            (p_tenant_id, 'job', 'Job Site', '🏗️', true, 40, 'Assign to specific job or project'),
            (p_tenant_id, 'yard', 'Yard/Location', '📍', true, 50, 'Assign to yard, warehouse, or storage location'),
            (p_tenant_id, 'department', 'Department', '🏢', false, 60, 'Assign to department or division');
        
        RAISE NOTICE 'Seeded default assignment types for tenant %', p_tenant_id;
    END IF;
END;
$$;


ALTER FUNCTION "inventory"."seed_default_assignment_types"("p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."seed_default_assignment_types"("p_tenant_id" "uuid") IS 'Seeds default assignment types for a new tenant. Idempotent - only runs if tenant has no types.';



CREATE OR REPLACE FUNCTION "inventory"."set_audit_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid;
  v_uid_exists boolean;
BEGIN
  v_uid := auth.uid();
  v_uid_exists := v_uid IS NOT NULL AND EXISTS (
    SELECT 1 FROM auth.users WHERE id = v_uid
  );

  IF TG_OP = 'INSERT' THEN
    IF v_uid_exists THEN
      NEW.created_by = v_uid;
      NEW.updated_by = v_uid;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF v_uid_exists THEN
      NEW.updated_by = v_uid;
    END IF;

    IF OLD.created_by IS NOT NULL THEN
      NEW.created_by = OLD.created_by;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."set_audit_fields"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."set_audit_fields"() IS 'Automatically sets created_by and updated_by from auth.uid()';



CREATE OR REPLACE FUNCTION "inventory"."setup_test_scenario"() RETURNS TABLE("tenant_id" "uuid", "location_id" "uuid", "item1_id" "uuid", "item2_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_location_id UUID;
    v_item1_id UUID;
    v_item2_id UUID;
BEGIN
    -- Create tenant
    v_tenant_id := inventory.create_test_tenant('Epic Inventory Test');
    
    -- Create location
    v_location_id := inventory.create_test_location(v_tenant_id, 'Main Warehouse');
    
    -- Create items
    v_item1_id := inventory.create_test_item(v_tenant_id, 'WIDGET-100', 'Standard Widget', 'stock');
    v_item2_id := inventory.create_test_item(v_tenant_id, 'GADGET-200', 'Premium Gadget', 'stock');
    
    -- Add stock
    PERFORM inventory.add_test_stock(v_tenant_id, v_item1_id, v_location_id, 100);
    PERFORM inventory.add_test_stock(v_tenant_id, v_item2_id, v_location_id, 50);
    
    RETURN QUERY SELECT v_tenant_id, v_location_id, v_item1_id, v_item2_id;
END;
$$;


ALTER FUNCTION "inventory"."setup_test_scenario"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."setup_test_scenario"() IS 'Quick test data setup: tenant, location, 2 items with stock';



CREATE OR REPLACE FUNCTION "inventory"."soft_delete_catalog_item"("p_item_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_has_stock BOOLEAN;
BEGIN
    -- Check if item has any stock
    SELECT EXISTS(
        SELECT 1 FROM inventory.stock_balances 
        WHERE catalog_item_id = p_item_id AND qty_on_hand > 0
    ) INTO v_has_stock;
    
    IF v_has_stock THEN
        RAISE EXCEPTION 'Cannot delete item with existing stock on hand'
        USING HINT = 'Transfer or adjust stock to zero before deleting';
    END IF;
    
    -- Soft delete
    UPDATE inventory.catalog_items
    SET 
        deleted_at = NOW(),
        deleted_by_user_id = p_user_id,
        updated_at = NOW()
    WHERE id = p_item_id;
    
    RETURN FOUND;
END;
$$;


ALTER FUNCTION "inventory"."soft_delete_catalog_item"("p_item_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."soft_delete_catalog_item"("p_item_id" "uuid", "p_user_id" "uuid") IS 'Safely soft-deletes a catalog item after validating no stock exists';



CREATE OR REPLACE FUNCTION "inventory"."trg_validate_reservation_before_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_fungible_validation RECORD;
    v_asset_validation RECORD;
BEGIN
    -- Only validate for active reservations
    IF NEW.status != 'active' THEN
        RETURN NEW;
    END IF;
    
    -- Validate based on reservation type
    IF NEW.reservation_type = 'fungible' THEN
        -- Validate fungible stock availability
        SELECT * INTO v_fungible_validation
        FROM inventory.validate_fungible_reservation_availability(
            NEW.tenant_id,
            NEW.catalog_item_id,
            NEW.location_id,
            NEW.qty
        );
        
        IF NOT v_fungible_validation.is_available THEN
            RAISE EXCEPTION '%', v_fungible_validation.message
            USING ERRCODE = 'check_violation',
                  HINT = 'Check stock availability before creating reservation';
        END IF;
        
    ELSIF NEW.reservation_type = 'serialized' THEN
        -- Validate asset availability
        SELECT * INTO v_asset_validation
        FROM inventory.validate_asset_reservation_availability(
            NEW.tenant_id,
            NEW.asset_id,
            NEW.reserved_from,
            NEW.reserved_until
        );
        
        IF NOT v_asset_validation.is_available THEN
            RAISE EXCEPTION '%', v_asset_validation.message
            USING ERRCODE = 'check_violation',
                  HINT = 'Choose a different asset or time window';
        END IF;
    ELSE
        RAISE EXCEPTION 'Invalid reservation_type: %', NEW.reservation_type
        USING ERRCODE = 'check_violation';
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."trg_validate_reservation_before_insert"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."trg_validate_reservation_before_insert"() IS 'Validates both fungible and serialized reservations before insert';



CREATE OR REPLACE FUNCTION "inventory"."update_updated_at_column"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."update_updated_at_column"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."validate_asset_reservation_availability"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_reserved_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_reserved_until" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_exclude_reservation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("is_available" boolean, "conflicting_reservation_id" "uuid", "message" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_asset RECORD;
    v_conflict RECORD;
BEGIN
    -- Get asset info
    SELECT 
        a.id,
        a.asset_tag,
        a.status,
        ci.name AS item_name
    INTO v_asset
    FROM inventory.assets a
    LEFT JOIN inventory.catalog_items ci ON ci.id = a.catalog_item_id
    WHERE a.id = p_asset_id
      AND a.tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RETURN QUERY SELECT 
            false AS is_available,
            NULL::UUID AS conflicting_reservation_id,
            format('✗ Asset not found or access denied') AS message;
        RETURN;
    END IF;
    
    -- Check asset status
    IF v_asset.status NOT IN ('available', 'assigned') THEN
        RETURN QUERY SELECT 
            false AS is_available,
            NULL::UUID AS conflicting_reservation_id,
            format('✗ Asset "%s" is %s (not available)', v_asset.asset_tag, v_asset.status) AS message;
        RETURN;
    END IF;
    
    -- Check for overlapping reservations
    IF p_reserved_from IS NOT NULL AND p_reserved_until IS NOT NULL THEN
        -- Time window specified - check for overlaps
        SELECT r.id, r.reserved_from, r.reserved_until
        INTO v_conflict
        FROM inventory.reservations r
        WHERE r.tenant_id = p_tenant_id
          AND r.asset_id = p_asset_id
          AND r.reservation_type = 'serialized'
          AND r.status = 'active'
          AND r.reserved_from IS NOT NULL
          AND r.reserved_until IS NOT NULL
          AND (r.id != p_exclude_reservation_id OR p_exclude_reservation_id IS NULL)
          AND tstzrange(r.reserved_from, r.reserved_until, '[)') && tstzrange(p_reserved_from, p_reserved_until, '[)')
        LIMIT 1;
        
        IF FOUND THEN
            RETURN QUERY SELECT 
                false AS is_available,
                v_conflict.id AS conflicting_reservation_id,
                format('✗ Asset "%s" already reserved from %s to %s', 
                       v_asset.asset_tag, 
                       v_conflict.reserved_from::TEXT, 
                       v_conflict.reserved_until::TEXT) AS message;
            RETURN;
        END IF;
    ELSE
        -- No time window - check for any active reservation
        SELECT r.id
        INTO v_conflict
        FROM inventory.reservations r
        WHERE r.tenant_id = p_tenant_id
          AND r.asset_id = p_asset_id
          AND r.reservation_type = 'serialized'
          AND r.status = 'active'
          AND (r.id != p_exclude_reservation_id OR p_exclude_reservation_id IS NULL)
        LIMIT 1;
        
        IF FOUND THEN
            RETURN QUERY SELECT 
                false AS is_available,
                v_conflict.id AS conflicting_reservation_id,
                format('✗ Asset "%s" is already reserved', v_asset.asset_tag) AS message;
            RETURN;
        END IF;
    END IF;
    
    -- Asset is available
    RETURN QUERY SELECT 
        true AS is_available,
        NULL::UUID AS conflicting_reservation_id,
        format('✓ Asset "%s" (%s) is available', v_asset.asset_tag, v_asset.item_name) AS message;
END;
$$;


ALTER FUNCTION "inventory"."validate_asset_reservation_availability"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_reserved_from" timestamp with time zone, "p_reserved_until" timestamp with time zone, "p_exclude_reservation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."validate_asset_reservation_availability"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_reserved_from" timestamp with time zone, "p_reserved_until" timestamp with time zone, "p_exclude_reservation_id" "uuid") IS 'Checks if serialized asset is available for reservation (supports time windows, tenant-scoped)';



CREATE OR REPLACE FUNCTION "inventory"."validate_assignment_type"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_type_exists BOOLEAN;
BEGIN
    -- Check if the assignment type exists and is active for this tenant
    SELECT EXISTS(
        SELECT 1 FROM inventory.assignment_types
        WHERE tenant_id = NEW.tenant_id
        AND type_key = NEW.assigned_to_type
        AND is_active = true
    ) INTO v_type_exists;
    
    IF NOT v_type_exists THEN
        RAISE EXCEPTION 'Invalid or inactive assignment type: %. Please use a valid assignment type from your configuration.',
            NEW.assigned_to_type
        USING 
            ERRCODE = 'check_violation',
            HINT = 'Check inventory.assignment_types table for valid assignment types';
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."validate_assignment_type"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."validate_assignment_type"() IS 'Validates assigned_to_type exists in assignment_types table and is active';



CREATE OR REPLACE FUNCTION "inventory"."validate_catalog_item_active"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_is_active BOOLEAN;
  v_item_sku TEXT;
BEGIN
  -- Check if catalog item is active
  SELECT active, sku INTO v_is_active, v_item_sku
  FROM inventory.catalog_items
  WHERE id = NEW.catalog_item_id;

  IF NOT v_is_active THEN
    RAISE EXCEPTION 'Cannot create PO line for inactive item: % (SKU: %)', 
      NEW.catalog_item_id, v_item_sku
    USING HINT = 'Reactivate the catalog item before adding to purchase orders';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."validate_catalog_item_active"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."validate_catalog_item_active"() IS 'Prevents PO lines from being created for inactive catalog items';



CREATE OR REPLACE FUNCTION "inventory"."validate_fungible_reservation_availability"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric, "p_exclude_reservation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("available_qty" numeric, "is_available" boolean, "message" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_qty_on_hand NUMERIC;
    v_qty_reserved NUMERIC;
    v_qty_available NUMERIC;
    v_item_name TEXT;
    v_location_name TEXT;
BEGIN
    -- Get stock balance and descriptive info
    SELECT 
        COALESCE(sb.qty_on_hand, 0),
        COALESCE(sb.qty_reserved, 0),
        COALESCE(sb.qty_available, 0),
        ci.name,
        l.name
    INTO 
        v_qty_on_hand,
        v_qty_reserved,
        v_qty_available,
        v_item_name,
        v_location_name
    FROM inventory.stock_balances sb
    LEFT JOIN inventory.catalog_items ci ON ci.id = p_catalog_item_id AND ci.tenant_id = p_tenant_id
    LEFT JOIN inventory.locations l ON l.id = p_location_id AND l.tenant_id = p_tenant_id
    WHERE sb.tenant_id = p_tenant_id
      AND sb.catalog_item_id = p_catalog_item_id
      AND sb.location_id = p_location_id;
    
    -- Default to 0 if no stock balance exists
    v_qty_available := COALESCE(v_qty_available, 0);
    
    -- If excluding an existing reservation (for updates), add its qty back
    IF p_exclude_reservation_id IS NOT NULL THEN
        DECLARE
            v_excluded_qty NUMERIC;
        BEGIN
            SELECT qty INTO v_excluded_qty
            FROM inventory.reservations
            WHERE id = p_exclude_reservation_id
              AND tenant_id = p_tenant_id
              AND reservation_type = 'fungible';
            
            v_qty_available := v_qty_available + COALESCE(v_excluded_qty, 0);
        END;
    END IF;
    
    -- Return result
    RETURN QUERY SELECT 
        v_qty_available AS available_qty,
        (v_qty_available >= p_qty) AS is_available,
        CASE 
            WHEN v_qty_available >= p_qty THEN 
                format('✓ Available: %s units of "%s" at "%s"', v_qty_available, v_item_name, v_location_name)
            ELSE 
                format('✗ Insufficient stock: %s units requested but only %s available for "%s" at "%s"', 
                       p_qty, v_qty_available, v_item_name, v_location_name)
        END AS message;
END;
$$;


ALTER FUNCTION "inventory"."validate_fungible_reservation_availability"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric, "p_exclude_reservation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."validate_fungible_reservation_availability"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric, "p_exclude_reservation_id" "uuid") IS 'Checks if sufficient fungible stock is available for reservation (tenant-scoped, concurrency-safe)';



CREATE OR REPLACE FUNCTION "inventory"."validate_reservation_allocation_type"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_type_exists BOOLEAN;
BEGIN
    IF NEW.allocation_type IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT EXISTS(
        SELECT 1 FROM inventory.reservation_types
        WHERE type_key = NEW.allocation_type
          AND is_active = true
          AND (tenant_id = NEW.tenant_id OR tenant_id IS NULL)
    ) INTO v_type_exists;

    IF NOT v_type_exists THEN
        RAISE EXCEPTION 'Invalid or inactive reservation allocation type: %', NEW.allocation_type
        USING ERRCODE = 'check_violation',
              HINT = 'Check inventory.reservation_types for valid allocation types';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."validate_reservation_allocation_type"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."validate_reservation_availability"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_available NUMERIC;
    v_item_sku TEXT;
    v_location_name TEXT;
BEGIN
    -- Only validate for active reservations
    IF NEW.status != 'active' THEN
        RETURN NEW;
    END IF;
    
    -- Get current available quantity and descriptive info
    SELECT 
        COALESCE(sb.qty_available, 0),
        ci.sku,
        l.name
    INTO v_available, v_item_sku, v_location_name
    FROM inventory.stock_balances sb
    JOIN inventory.catalog_items ci ON ci.id = NEW.catalog_item_id
    JOIN inventory.locations l ON l.id = NEW.location_id
    WHERE sb.tenant_id = NEW.tenant_id
      AND sb.catalog_item_id = NEW.catalog_item_id
      AND sb.location_id = NEW.location_id;
    
    -- If no stock balance exists, available is 0
    v_available := COALESCE(v_available, 0);
    
    IF NEW.qty > v_available THEN
        RAISE EXCEPTION 'Insufficient available stock for reservation: % units requested for item "%" at location "%", but only % units available',
            NEW.qty, v_item_sku, v_location_name, v_available
        USING 
            ERRCODE = 'check_violation',
            HINT = 'Check stock availability before creating reservation or receive more inventory';
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."validate_reservation_availability"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."validate_reservation_availability"() IS 'Prevents over-booking by validating reservation quantity against available stock';



CREATE OR REPLACE FUNCTION "inventory"."validate_single_active_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_count INTEGER;
    v_existing_assignment RECORD;
BEGIN
    -- Only validate for active assignments
    IF NEW.returned_at IS NOT NULL THEN
        RETURN NEW;
    END IF;
    
    -- Check for existing active assignment
    SELECT 
        aa.id,
        aa.assigned_to_type,
        aa.assigned_to_id,
        aa.assigned_at
    INTO v_existing_assignment
    FROM inventory.asset_assignments aa
    WHERE aa.asset_id = NEW.asset_id
      AND aa.returned_at IS NULL
      AND aa.id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::UUID)
    LIMIT 1;
    
    IF FOUND THEN
        RAISE EXCEPTION 'Asset % already has an active assignment (ID: %, assigned to % % on %)',
            NEW.asset_id,
            v_existing_assignment.id,
            v_existing_assignment.assigned_to_type,
            v_existing_assignment.assigned_to_id,
            v_existing_assignment.assigned_at
        USING 
            ERRCODE = 'unique_violation',
            HINT = 'Return the existing assignment before creating a new one';
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."validate_single_active_assignment"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."validate_single_active_assignment"() IS 'Ensures only one active assignment per asset at any time';



CREATE OR REPLACE FUNCTION "inventory"."verify_quantity_integrity"("p_tenant_id" "uuid") RETURNS TABLE("check_name" "text", "status" "text", "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Check 1: No negative on-hand (after accounting for all movements)
    RETURN QUERY
    SELECT
        'No Negative On-Hand'::TEXT,
        CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END::TEXT,
        CASE WHEN COUNT(*) = 0 
            THEN 'All locations have non-negative on-hand quantities'
            ELSE COUNT(*)::TEXT || ' locations have negative on-hand'
        END::TEXT
    FROM inventory.v_on_hand_by_item_location
    WHERE tenant_id = p_tenant_id
      AND qty_on_hand < 0;
    
    -- Check 2: Reserved doesn't exceed on-hand
    RETURN QUERY
    SELECT
        'Reserved <= On-Hand'::TEXT,
        CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'WARNING' END::TEXT,
        CASE WHEN COUNT(*) = 0 
            THEN 'All reservations are backed by on-hand stock'
            ELSE COUNT(*)::TEXT || ' locations have over-reserved stock'
        END::TEXT
    FROM inventory.v_core_quantities
    WHERE tenant_id = p_tenant_id
      AND qty_reserved > qty_on_hand;
    
    -- Check 3: All stock movements have last_event_id
    RETURN QUERY
    SELECT
        'Stock Movements Idempotency'::TEXT,
        CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END::TEXT,
        CASE WHEN COUNT(*) = 0 
            THEN 'All stock movements have last_event_id'
            ELSE COUNT(*)::TEXT || ' movements missing last_event_id'
        END::TEXT
    FROM inventory.stock_movements
    WHERE tenant_id = p_tenant_id
      AND last_event_id IS NULL;
    
    -- Check 4: No direct quantity columns on catalog_items
    RETURN QUERY
    SELECT
        'No Quantity on Master Data'::TEXT,
        'PASS'::TEXT,
        'Catalog items correctly have no qty_on_hand column'::TEXT
    WHERE NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'inventory'
          AND table_name = 'catalog_items'
          AND column_name IN ('qty_on_hand', 'quantity', 'stock_level')
    );
    
    -- Check 5: All active reservations have future or null needed_by
    RETURN QUERY
    SELECT
        'Reservation Expiry'::TEXT,
        CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'WARNING' END::TEXT,
        CASE WHEN COUNT(*) = 0 
            THEN 'No overdue active reservations'
            ELSE COUNT(*)::TEXT || ' active reservations past needed_by date'
        END::TEXT
    FROM inventory.reservations
    WHERE tenant_id = p_tenant_id
      AND status = 'active'
      AND needed_by < CURRENT_DATE;
END;
$$;


ALTER FUNCTION "inventory"."verify_quantity_integrity"("p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."verify_quantity_integrity"("p_tenant_id" "uuid") IS 'Run integrity checks on inventory quantities and statuses';



CREATE OR REPLACE FUNCTION "public"."current_tenant_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_tenant_id uuid;
BEGIN
  v_tenant_id := NULLIF(current_setting('app.current_tenant_id', true), '')::uuid;

  IF v_tenant_id IS NULL THEN
    v_tenant_id := (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid;
  END IF;

  IF v_tenant_id IS NULL THEN
    v_tenant_id := (auth.jwt() -> 'app_metadata' ->> 'tenantId')::uuid;
  END IF;

  IF v_tenant_id IS NULL THEN
    v_tenant_id := (auth.jwt() ->> 'tenant_id')::uuid;
  END IF;

  RETURN v_tenant_id;
END;
$$;


ALTER FUNCTION "public"."current_tenant_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."emit_dashboard_event"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_event_name text;
  v_payload jsonb;
  v_metadata jsonb;
  v_changes jsonb;
BEGIN
  v_metadata := jsonb_build_object(
    'source', 'dashboard',
    'actor_user_id', auth.uid(),
    'request_id', current_setting('request.id', true)
  );

  IF TG_OP = 'INSERT' THEN
    v_event_name := 'dashboard.created';
    v_payload := jsonb_build_object(
      'dashboard_id', NEW.id,
      'tenant_id', NEW.tenant_id,
      'name', NEW.name,
      'scope', NEW.scope,
      'owner_user_id', NEW.owner_user_id,
      'created_by', NEW.created_by,
      'created_at', NEW.created_at
    );
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
      v_event_name := 'dashboard.deleted';
      v_payload := jsonb_build_object(
        'dashboard_id', NEW.id,
        'tenant_id', NEW.tenant_id,
        'deleted_at', NEW.deleted_at
      );
    ELSE
      v_event_name := 'dashboard.updated';
      v_changes := jsonb_strip_nulls(
        jsonb_build_object(
          'name', CASE WHEN NEW.name IS DISTINCT FROM OLD.name THEN jsonb_build_object('old', OLD.name, 'new', NEW.name) END,
          'description', CASE WHEN NEW.description IS DISTINCT FROM OLD.description THEN jsonb_build_object('old', OLD.description, 'new', NEW.description) END,
          'is_default', CASE WHEN NEW.is_default IS DISTINCT FROM OLD.is_default THEN jsonb_build_object('old', OLD.is_default, 'new', NEW.is_default) END,
          'scope', CASE WHEN NEW.scope IS DISTINCT FROM OLD.scope THEN jsonb_build_object('old', OLD.scope, 'new', NEW.scope) END
        )
      );
      v_payload := jsonb_build_object(
        'dashboard_id', NEW.id,
        'tenant_id', NEW.tenant_id,
        'changes', COALESCE(v_changes, '{}'::jsonb)
      );
    END IF;
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO inventory.events_outbox (
    tenant_id,
    scope,
    event_type,
    aggregate_type,
    aggregate_id,
    actor_user_id,
    payload,
    metadata,
    event_name,
    event_version,
    status,
    created_at
  ) VALUES (
    NEW.tenant_id,
    'tenant',
    v_event_name,
    'dashboard',
    NEW.id,
    auth.uid(),
    v_payload,
    v_metadata,
    v_event_name,
    1,
    'pending',
    now()
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."emit_dashboard_event"() OWNER TO "postgres";


