CREATE OR REPLACE FUNCTION "public"."emit_event"("p_event_type" "text", "p_payload" "jsonb", "p_tenant_id" "uuid", "p_scope" "text" DEFAULT 'tenant'::"text", "p_aggregate_type" "text" DEFAULT NULL::"text", "p_aggregate_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_id UUID;
    v_event_name TEXT;
    v_event_version INT;
BEGIN
    -- Parse event_type to extract event_name and version if provided
    -- Format: "inventory.stock.adjusted" or "inventory.stock.adjusted@2"
    IF p_event_type LIKE '%@%' THEN
        v_event_name := split_part(p_event_type, '@', 1);
        v_event_version := split_part(p_event_type, '@', 2)::int;
    ELSE
        v_event_name := p_event_type;
        v_event_version := 1;  -- Default version
    END IF;

    -- Call existing publish_event function (with event_name signature)
    v_event_id := inventory.publish_event(
        p_tenant_id := p_tenant_id,
        p_scope := p_scope,
        p_event_name := v_event_name,
        p_aggregate_type := COALESCE(p_aggregate_type, v_event_name),
        p_aggregate_id := COALESCE(p_aggregate_id, gen_random_uuid()),
        p_payload := p_payload,
        p_event_version := v_event_version,
        p_metadata := p_metadata
    );

    RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."emit_event"("p_event_type" "text", "p_payload" "jsonb", "p_tenant_id" "uuid", "p_scope" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."emit_event"("p_event_type" "text", "p_payload" "jsonb", "p_tenant_id" "uuid", "p_scope" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_metadata" "jsonb") IS 'Standard event emission interface - wraps inventory.publish_event for hub protocol compliance';



CREATE OR REPLACE FUNCTION "public"."emit_event"("p_type" "text", "p_payload" "jsonb", "p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_trace_id" "uuid" DEFAULT NULL::"uuid", "p_correlation_id" "uuid" DEFAULT NULL::"uuid", "p_aggregate_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_id UUID;
  v_version INTEGER;
  v_agg_type TEXT;
BEGIN
  -- Lookup version and aggregate type
  SELECT event_version, aggregate_type INTO v_version, v_agg_type 
  FROM event_catalog 
  WHERE event_key = p_type;
  
  -- Handle unregistered events gracefully (Default to v1 / system)
  IF v_version IS NULL THEN 
    v_version := 1; 
    v_agg_type := 'system';
  END IF;

  INSERT INTO events_outbox (
    event_type, event_version, payload, 
    tenant_id, actor_user_id, 
    trace_id, correlation_id, 
    aggregate_type, aggregate_id
  ) VALUES (
    p_type, v_version, p_payload, 
    p_tenant_id, p_actor_id, 
    COALESCE(p_trace_id, gen_random_uuid()), p_correlation_id,
    v_agg_type, p_aggregate_id
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."emit_event"("p_type" "text", "p_payload" "jsonb", "p_tenant_id" "uuid", "p_actor_id" "uuid", "p_trace_id" "uuid", "p_correlation_id" "uuid", "p_aggregate_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_tenant_exists"("p_tenant_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_name TEXT;
BEGIN
  IF p_tenant_id IS NULL THEN
    RETURN;
  END IF;

  SELECT name INTO v_name
  FROM public.tenants
  WHERE id = p_tenant_id;

  IF NOT FOUND THEN
    v_name := COALESCE(
      auth.jwt() -> 'app_metadata' ->> 'tenant_name',
      auth.jwt() -> 'app_metadata' ->> 'tenantName',
      auth.jwt() -> 'app_metadata' ->> 'name',
      'Tenant ' || p_tenant_id::text
    );

    INSERT INTO public.tenants (
      id,
      name,
      last_event_id,
      metadata
    ) VALUES (
      p_tenant_id,
      v_name,
      'bootstrap_tenant_' || p_tenant_id::text,
      jsonb_build_object('bootstrap', true)
    )
    ON CONFLICT (id) DO NOTHING;
  END IF;
END;
$$;


ALTER FUNCTION "public"."ensure_tenant_exists"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_prevent_event_modification"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.payload IS DISTINCT FROM NEW.payload OR 
     OLD.event_type IS DISTINCT FROM NEW.event_type THEN
      RAISE EXCEPTION 'Events are immutable. You cannot modify the payload or type of an existing event.';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_prevent_event_modification"() OWNER TO "postgres";


