CREATE OR REPLACE FUNCTION "public"."register_event"("p_key" "text", "p_name" "text", "p_desc" "text", "p_example" "jsonb", "p_schema" "jsonb" DEFAULT NULL::"jsonb", "p_agg_type" "text" DEFAULT 'system'::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  INSERT INTO event_catalog (
    event_key, display_name, description, payload_example, payload_schema, aggregate_type
  ) VALUES (p_key, p_name, p_desc, p_example, p_schema, p_agg_type)
  ON CONFLICT (event_key) DO UPDATE SET
    display_name = EXCLUDED.display_name,
    description = EXCLUDED.description,
    payload_example = EXCLUDED.payload_example,
    payload_schema = COALESCE(EXCLUDED.payload_schema, event_catalog.payload_schema),
    aggregate_type = EXCLUDED.aggregate_type,
    updated_at = NOW();
END;
$$;


ALTER FUNCTION "public"."register_event"("p_key" "text", "p_name" "text", "p_desc" "text", "p_example" "jsonb", "p_schema" "jsonb", "p_agg_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_event"("p_event_name" "text", "p_version" integer DEFAULT 1, "p_producer" "text" DEFAULT 'inventory'::"text", "p_description" "text" DEFAULT ''::"text", "p_payload_schema" "jsonb" DEFAULT NULL::"jsonb", "p_example_payload" "jsonb" DEFAULT NULL::"jsonb", "p_status" "text" DEFAULT 'active'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_definition_id UUID;
BEGIN
    -- Upsert event definition
    INSERT INTO public.event_definitions (
        event_name,
        version,
        producer,
        description,
        payload_schema,
        example_payload,
        status,
        created_at,
        updated_at
    ) VALUES (
        p_event_name,
        p_version,
        p_producer,
        p_description,
        p_payload_schema,
        p_example_payload,
        p_status,
        NOW(),
        NOW()
    )
    ON CONFLICT (event_name, version) 
    DO UPDATE SET
        description = EXCLUDED.description,
        payload_schema = EXCLUDED.payload_schema,
        example_payload = EXCLUDED.example_payload,
        status = EXCLUDED.status,
        updated_at = NOW()
    RETURNING id INTO v_definition_id;

    RETURN v_definition_id;
END;
$$;


