CREATE OR REPLACE FUNCTION "public"."rfid_add_tag_to_bulk_session"("p_session_id" "uuid", "p_tenant_id" "uuid", "p_epc" "text", "p_added_by" "uuid") RETURNS TABLE("tag_id" "uuid", "tag_count_in_session" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_session RECORD;
    v_tag_id UUID;
    v_tag_count INTEGER;
BEGIN
    -- Get session
    SELECT * INTO v_session
    FROM public.rfid_bulk_assignment_sessions
    WHERE session_id = p_session_id
      AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Session not found: %', p_session_id;
    END IF;
    
    IF v_session.session_status != 'in_progress' THEN
        RAISE EXCEPTION 'Session is not in progress (status=%)', v_session.session_status;
    END IF;
    
    -- Create tag
    v_tag_id := gen_random_uuid();
    
    INSERT INTO public.rfid_tags (
        tag_id,
        tenant_id,
        epc,
        tag_category,
        asset_id,
        bulk_catalog_item_id,
        bulk_assignment_session_id,
        tag_status
    ) VALUES (
        v_tag_id,
        p_tenant_id,
        p_epc,
        'bulk_item_tag',
        NULL,
        v_session.catalog_item_id,
        p_session_id,
        'active'
    );
    
    -- Record assignment history
    INSERT INTO public.rfid_tag_assignment_history (
        tenant_id,
        tag_id,
        epc,
        assignment_type,
        asset_id,
        catalog_item_id,
        assigned_by,
        assignment_notes
    ) VALUES (
        p_tenant_id,
        v_tag_id,
        p_epc,
        'assigned',
        NULL,
        v_session.catalog_item_id,
        p_added_by,
        format('Bulk session: %s', v_session.session_number)
    );
    
    -- Update session tag count
    UPDATE public.rfid_bulk_assignment_sessions
    SET 
        tag_count = COALESCE(tag_count, 0) + 1,
        updated_at = NOW()
    WHERE session_id = p_session_id
    RETURNING tag_count INTO v_tag_count;
    
    RETURN QUERY
    SELECT v_tag_id, v_tag_count;
END;
$$;


ALTER FUNCTION "public"."rfid_add_tag_to_bulk_session"("p_session_id" "uuid", "p_tenant_id" "uuid", "p_epc" "text", "p_added_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rfid_add_tag_to_bulk_session"("p_session_id" "uuid", "p_tenant_id" "uuid", "p_epc" "text", "p_added_by" "uuid") IS 'Adds RFID tag to bulk assignment session (pooled tag for fungible item).';



CREATE OR REPLACE FUNCTION "public"."rfid_retire_tag"("p_tag_id" "uuid", "p_tenant_id" "uuid", "p_reason" "text", "p_retired_by" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_tag RECORD;
    v_event_id UUID;
BEGIN
    -- Get tag
    SELECT * INTO v_tag
    FROM public.rfid_tags
    WHERE tag_id = p_tag_id
      AND tenant_id = p_tenant_id
    FOR UPDATE;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tag not found: %', p_tag_id;
    END IF;
    
    -- Update tag status
    UPDATE public.rfid_tags
    SET 
        tag_status = 'retired',
        retired_at = NOW(),
        notes = COALESCE(notes || E'\n', '') || format('Retired: %s', p_reason),
        updated_at = NOW()
    WHERE tag_id = p_tag_id;
    
    -- Record history
    INSERT INTO public.rfid_tag_assignment_history (
        tenant_id,
        tag_id,
        epc,
        assignment_type,
        asset_id,
        catalog_item_id,
        assigned_by,
        assignment_notes
    ) VALUES (
        p_tenant_id,
        p_tag_id,
        v_tag.epc,
        'retired',
        v_tag.asset_id,
        v_tag.bulk_catalog_item_id,
        p_retired_by,
        p_reason
    );
    
    -- Emit event
    v_event_id := emit_event(
        p_tenant_id,
        'inventory.rfid.tag_retired',
        1,
        jsonb_build_object(
            'tag_id', p_tag_id,
            'tenant_id', p_tenant_id,
            'epc', v_tag.epc,
            'reason', p_reason,
            'retired_by', p_retired_by,
            'retired_at', NOW()
        ),
        'inventory',
        p_tag_id
    );
    
    RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."rfid_retire_tag"("p_tag_id" "uuid", "p_tenant_id" "uuid", "p_reason" "text", "p_retired_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rfid_retire_tag"("p_tag_id" "uuid", "p_tenant_id" "uuid", "p_reason" "text", "p_retired_by" "uuid") IS 'Retires RFID tag from active use. Emits inventory.rfid.tag_retired event.';



CREATE OR REPLACE FUNCTION "public"."rfid_start_bulk_assignment_session"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_started_by" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("session_id" "uuid", "session_number" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_session_id UUID;
    v_session_number TEXT;
    v_catalog_item RECORD;
BEGIN
    -- Verify catalog item exists and is bulk-tracked
    SELECT * INTO v_catalog_item
    FROM public.catalog_items
    WHERE tenant_id = p_tenant_id
      AND catalog_item_id = p_catalog_item_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Catalog item not found: %', p_catalog_item_id;
    END IF;
    
    IF v_catalog_item.tracking_mode != 'bulk' THEN
        RAISE EXCEPTION 'Catalog item must be bulk-tracked for bulk tag assignment'
            USING HINT = format('Item %s has tracking_mode=%s', v_catalog_item.item_code, v_catalog_item.tracking_mode);
    END IF;
    
    -- Generate session ID and number
    v_session_id := gen_random_uuid();
    v_session_number := 'BULK-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(NEXTVAL('session_number_seq')::TEXT, 5, '0');
    
    -- Create session
    INSERT INTO public.rfid_bulk_assignment_sessions (
        session_id,
        tenant_id,
        session_number,
        catalog_item_id,
        session_status,
        started_by,
        notes
    ) VALUES (
        v_session_id,
        p_tenant_id,
        v_session_number,
        p_catalog_item_id,
        'in_progress',
        p_started_by,
        p_notes
    );
    
    RETURN QUERY
    SELECT v_session_id, v_session_number;
END;
$$;


ALTER FUNCTION "public"."rfid_start_bulk_assignment_session"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_started_by" "uuid", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rfid_start_bulk_assignment_session"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_started_by" "uuid", "p_notes" "text") IS 'Starts bulk tag assignment session for pooled tags (fungible items).';



CREATE OR REPLACE FUNCTION "public"."rpc_claim_device"("p_claim_code" "text", "p_device_name" "text", "p_role" "text" DEFAULT 'handheld_scanner'::"text", "p_scope" "jsonb" DEFAULT NULL::"jsonb", "p_initial_config" "jsonb" DEFAULT NULL::"jsonb") RETURNS TABLE("device_id" "uuid", "tenant_id" "uuid", "status" "text", "role" "text", "name" "text", "config_version" integer, "config" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'inventory', 'public'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_user_id UUID;
    v_code RECORD;
    v_device RECORD;
    v_config JSONB;
    v_version INTEGER;
    v_existing_config RECORD;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    v_tenant_id := current_tenant_id();
    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'Tenant not found in session';
    END IF;

    SELECT * INTO v_code
    FROM inventory.rfid_device_claim_codes
    WHERE code = p_claim_code
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Invalid claim code';
    END IF;

    IF v_code.expires_at <= NOW() THEN
        RAISE EXCEPTION 'Claim code expired';
    END IF;

    IF v_code.consumed_at IS NOT NULL THEN
        IF v_code.consumed_by_user_id = v_user_id THEN
            SELECT * INTO v_device
            FROM inventory.rfid_devices
            WHERE id = v_code.device_id;

            SELECT c.version, c.config INTO v_existing_config
            FROM inventory.rfid_device_configs c
            WHERE c.device_id = v_code.device_id
            ORDER BY c.version DESC
            LIMIT 1;

            RETURN QUERY
            SELECT v_device.id,
                   v_device.tenant_id,
                   v_device.status,
                   v_device.role,
                   v_device.name,
                   v_existing_config.version,
                   v_existing_config.config;
            RETURN;
        END IF;

        RAISE EXCEPTION 'Claim code already used';
    END IF;

    SELECT * INTO v_device
    FROM inventory.rfid_devices d
    WHERE d.id = v_code.device_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Device not found for claim code';
    END IF;

    IF v_device.tenant_id IS NOT NULL AND v_device.tenant_id <> v_tenant_id THEN
        RAISE EXCEPTION 'Device already claimed by another tenant';
    END IF;

    UPDATE inventory.rfid_device_claim_codes
    SET consumed_at = NOW(),
        consumed_by_user_id = v_user_id
    WHERE id = v_code.id;

    UPDATE inventory.rfid_devices
    SET tenant_id = v_tenant_id,
        status = 'active',
        role = COALESCE(p_role, role),
        name = COALESCE(p_device_name, name),
        updated_at = NOW()
    WHERE id = v_device.id;

    INSERT INTO inventory.rfid_device_claims (
        device_id,
        tenant_id,
        claimed_by_user_id,
        claimed_at,
        reason
    ) VALUES (
        v_device.id,
        v_tenant_id,
        v_user_id,
        NOW(),
        'claimed'
    );

    SELECT COALESCE(MAX(version), 0) + 1
      INTO v_version
      FROM inventory.rfid_device_configs
     WHERE device_id = v_device.id;

    v_config := jsonb_build_object(
        'role', COALESCE(p_role, 'handheld_scanner')
    );

    IF p_scope IS NOT NULL THEN
        v_config := v_config || jsonb_build_object('scope', p_scope);
    END IF;

    IF p_initial_config IS NOT NULL THEN
        v_config := v_config || p_initial_config;
    END IF;

    INSERT INTO inventory.rfid_device_configs (
        device_id,
        version,
        config,
        published_by_user_id
    ) VALUES (
        v_device.id,
        v_version,
        v_config,
        v_user_id
    );

    UPDATE inventory.rfid_devices
    SET current_config_version = v_version
    WHERE id = v_device.id;

    RETURN QUERY
    SELECT v_device.id,
           v_tenant_id,
           'active',
           COALESCE(p_role, 'handheld_scanner'),
           COALESCE(p_device_name, v_device.name),
           v_version,
           v_config;
END;
$$;


ALTER FUNCTION "public"."rpc_claim_device"("p_claim_code" "text", "p_device_name" "text", "p_role" "text", "p_scope" "jsonb", "p_initial_config" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rpc_claim_device"("p_claim_code" "text", "p_device_name" "text", "p_role" "text", "p_scope" "jsonb", "p_initial_config" "jsonb") IS 'Claims an unassigned RFID device via claim code, assigns tenant and initial config. Option A onboarding.';



CREATE OR REPLACE FUNCTION "public"."set_dashboard_audit_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF NEW.tenant_id IS NULL THEN
    NEW.tenant_id := public.current_tenant_id();
  END IF;

  IF NEW.created_at IS NULL THEN
    NEW.created_at := now();
  END IF;

  NEW.updated_at := now();

  IF TG_OP = 'INSERT' THEN
    IF NEW.created_by IS NULL THEN
      NEW.created_by := v_user_id;
    END IF;

    IF NEW.owner_user_id IS NULL AND NEW.scope = 'user' THEN
      NEW.owner_user_id := v_user_id;
    END IF;
  END IF;

  NEW.updated_by := v_user_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_dashboard_audit_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dashboard_widget_audit_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.tenant_id IS NULL THEN
    NEW.tenant_id := public.current_tenant_id();
  END IF;

  IF NEW.created_at IS NULL THEN
    NEW.created_at := now();
  END IF;

  NEW.updated_at := now();
  NEW.created_by := COALESCE(NEW.created_by, auth.uid());
  NEW.updated_by := auth.uid();

  RETURN NEW;
END;
$$;


