CREATE OR REPLACE FUNCTION "public"."update_event_catalog_item"("p_event_key" "text", "p_display_name" "text", "p_description" "text", "p_category" "text", "p_owner_module" "text", "p_aggregate_type" "text", "p_is_internal" boolean, "p_is_deprecated" boolean, "p_deprecated_reason" "text", "p_payload_example" "jsonb", "p_payload_schema" "jsonb", "p_payload_notes" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE public.event_catalog
  SET 
    display_name = COALESCE(p_display_name, display_name),
    description = COALESCE(p_description, description),
    category = COALESCE(p_category, category),
    owner_module = COALESCE(p_owner_module, owner_module),
    aggregate_type = COALESCE(p_aggregate_type, aggregate_type),
    is_internal = COALESCE(p_is_internal, is_internal),
    is_deprecated = COALESCE(p_is_deprecated, is_deprecated),
    deprecated_reason = COALESCE(p_deprecated_reason, deprecated_reason),
    payload_example = COALESCE(p_payload_example, payload_example),
    payload_schema = COALESCE(p_payload_schema, payload_schema),
    payload_notes = COALESCE(p_payload_notes, payload_notes),
    updated_at = NOW()
  WHERE event_key = p_event_key;
END;
$$;


ALTER FUNCTION "public"."update_event_catalog_item"("p_event_key" "text", "p_display_name" "text", "p_description" "text", "p_category" "text", "p_owner_module" "text", "p_aggregate_type" "text", "p_is_internal" boolean, "p_is_deprecated" boolean, "p_deprecated_reason" "text", "p_payload_example" "jsonb", "p_payload_schema" "jsonb", "p_payload_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_event_status"("p_event_id" "uuid", "p_status" "text", "p_published_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_retry_count" integer DEFAULT NULL::integer, "p_last_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE inventory.events_outbox
  SET
    status = p_status,
    published_at = COALESCE(p_published_at, published_at),
    retry_count = COALESCE(p_retry_count, retry_count),
    last_error = COALESCE(p_last_error, last_error),
    error_message = COALESCE(p_last_error, error_message),
    last_attempt_at = now(),
    last_retry_at = CASE WHEN p_status IN ('pending', 'failed') THEN now() ELSE last_retry_at END,
    next_attempt_at = CASE WHEN p_status IN ('pending', 'failed') THEN now() ELSE next_attempt_at END
  WHERE id = p_event_id;
END;
$$;


