CREATE OR REPLACE FUNCTION "public"."validate_event_in_catalog"("p_event_name" "text", "p_event_version" integer DEFAULT 1) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_exists BOOLEAN;
BEGIN
    SELECT EXISTS(
        SELECT 1 
        FROM public.event_definitions 
        WHERE event_name = p_event_name 
        AND version = p_event_version
        AND status IN ('active', 'draft')
    ) INTO v_exists;
    
    IF NOT v_exists THEN
        RAISE WARNING 'Event % version % not found in catalog or is deprecated', p_event_name, p_event_version;
    END IF;
    
    RETURN v_exists;
END;
$$;


