CREATE OR REPLACE FUNCTION "supply_chain"."emit_vendor_performance_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Emit event to outbox for external processing
  INSERT INTO inventory.events_outbox (
    tenant_id,
    scope,
    event_type,
    aggregate_type,
    aggregate_id,
    payload,
    status,
    event_name,
    event_version
  ) VALUES (
    NEW.tenant_id,
    'tenant',
    CONCAT('supply_chain.vendor_performance.', NEW.event_type),
    'vendor_performance',
    NEW.vendor_id,
    jsonb_build_object(
      'event_id', NEW.id,
      'vendor_id', NEW.vendor_id,
      'event_type', NEW.event_type,
      'event_date', NEW.event_date,
      'po_id', NEW.po_id,
      'receipt_id', NEW.receipt_id,
      'quantity', NEW.quantity,
      'amount', NEW.amount,
      'days_late', NEW.days_late,
      'expected_date', NEW.expected_date,
      'actual_date', NEW.actual_date,
      'metadata', NEW.metadata
    ),
    'pending',
    CONCAT('supply_chain.vendor_performance.', NEW.event_type),
    1
  );
  
  RETURN NEW;
END;
$$;


