CREATE OR REPLACE FUNCTION "supply_chain"."enforce_vendor_code_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'public'
    AS $_$
DECLARE
  v_settings supply_chain.tenant_settings;
  v_code TEXT;
  v_has_usage BOOLEAN;
BEGIN
  SELECT * INTO v_settings
  FROM supply_chain.tenant_settings
  WHERE tenant_id = NEW.tenant_id;

  IF NOT FOUND THEN
    v_settings := supply_chain.get_or_create_tenant_settings(NEW.tenant_id);
  END IF;

  -- Skip validation when deactivating OR reactivating a vendor
  IF TG_OP = 'UPDATE' AND NEW.active IS DISTINCT FROM OLD.active THEN
    RETURN NEW;
  END IF;

  v_code := NULLIF(BTRIM(NEW.code), '');

  -- Auto-generate if configured and code not provided
  IF v_code IS NULL THEN
    IF v_settings.vendor_code_strategy IN ('sequential', 'hybrid') THEN
      v_code := supply_chain.generate_vendor_code(NEW.tenant_id);
    ELSIF v_settings.vendor_code_required THEN
      RAISE EXCEPTION 'Vendor code is required by tenant settings';
    ELSE
      NEW.code := NULL;
      RETURN NEW;
    END IF;
  END IF;

  -- Normalize case
  IF v_settings.vendor_code_case = 'upper' THEN
    v_code := UPPER(v_code);
  ELSIF v_settings.vendor_code_case = 'lower' THEN
    v_code := LOWER(v_code);
  END IF;

  -- Validate length
  IF v_settings.vendor_code_min_length IS NOT NULL AND LENGTH(v_code) < v_settings.vendor_code_min_length THEN
    RAISE EXCEPTION 'Vendor code must be at least % characters', v_settings.vendor_code_min_length;
  END IF;
  IF v_settings.vendor_code_max_length IS NOT NULL AND LENGTH(v_code) > v_settings.vendor_code_max_length THEN
    RAISE EXCEPTION 'Vendor code must be at most % characters', v_settings.vendor_code_max_length;
  END IF;

  -- Validate prefix/suffix
  IF v_settings.vendor_code_prefix IS NOT NULL AND v_settings.vendor_code_prefix <> '' THEN
    IF v_code NOT LIKE v_settings.vendor_code_prefix || '%' THEN
      RAISE EXCEPTION 'Vendor code must start with %', v_settings.vendor_code_prefix;
    END IF;
  END IF;

  IF v_settings.vendor_code_suffix IS NOT NULL AND v_settings.vendor_code_suffix <> '' THEN
    IF v_code NOT LIKE '%' || v_settings.vendor_code_suffix THEN
      RAISE EXCEPTION 'Vendor code must end with %', v_settings.vendor_code_suffix;
    END IF;
  END IF;

  -- Validate allowed chars
  IF v_settings.vendor_code_allowed_chars IS NOT NULL AND v_settings.vendor_code_allowed_chars <> '' THEN
    IF v_code !~ ('^[' || v_settings.vendor_code_allowed_chars || ']+$') THEN
      RAISE EXCEPTION 'Vendor code contains invalid characters';
    END IF;
  END IF;

  -- Validate regex
  IF v_settings.vendor_code_regex IS NOT NULL AND v_settings.vendor_code_regex <> '' THEN
    IF v_code !~ v_settings.vendor_code_regex THEN
      RAISE EXCEPTION 'Vendor code does not match required format';
    END IF;
  END IF;

  -- Prevent unauthorized edits
  IF TG_OP = 'UPDATE' AND NEW.code IS DISTINCT FROM OLD.code THEN
    IF v_settings.vendor_code_user_editable IS FALSE THEN
      RAISE EXCEPTION 'Vendor code editing is disabled by tenant settings';
    END IF;

    IF v_settings.vendor_code_immutable_after_use THEN
      SELECT EXISTS (
        SELECT 1 FROM supply_chain.purchase_orders po WHERE po.vendor_id = NEW.id
      ) OR EXISTS (
        SELECT 1 FROM supply_chain.receipts r WHERE r.vendor_id = NEW.id
      ) INTO v_has_usage;

      IF v_has_usage THEN
        RAISE EXCEPTION 'Vendor code cannot be changed after purchase activity exists';
      END IF;
    END IF;
  END IF;

  NEW.code := v_code;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "supply_chain"."enforce_vendor_code_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."generate_po_number"("p_tenant_id" "uuid", "p_format" "text" DEFAULT 'sequential-year'::"text", "p_prefix" "text" DEFAULT ''::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_year integer;
  v_year_short text;
  v_next_number integer;
  v_po_number text;
  v_format_prefix text;
BEGIN
  -- Get current year
  v_year := EXTRACT(YEAR FROM CURRENT_DATE);
  v_year_short := RIGHT(v_year::text, 2);
  
  -- Lock the row for this tenant to prevent race conditions
  -- Insert if doesn't exist, or update and return next sequence
  INSERT INTO supply_chain.po_number_sequences (tenant_id, current_year, current_sequence)
  VALUES (p_tenant_id, v_year, 1)
  ON CONFLICT (tenant_id) DO UPDATE
  SET 
    -- Reset sequence if year changed
    current_sequence = CASE 
      WHEN po_number_sequences.current_year <> v_year THEN 1
      ELSE po_number_sequences.current_sequence + 1
    END,
    current_year = v_year,
    updated_at = now()
  RETURNING current_sequence INTO v_next_number;
  
  -- Build PO number based on format
  IF p_format = 'sequential-year' THEN
    -- Format: YY-#### or PREFIX-YY-####
    IF p_prefix <> '' THEN
      v_po_number := p_prefix || '-' || v_year_short || '-' || LPAD(v_next_number::text, 4, '0');
    ELSE
      v_po_number := v_year_short || '-' || LPAD(v_next_number::text, 4, '0');
    END IF;
  ELSIF p_format = 'sequential' THEN
    -- Format: #### or PREFIX-####
    IF p_prefix <> '' THEN
      v_po_number := p_prefix || '-' || LPAD(v_next_number::text, 4, '0');
    ELSE
      v_po_number := LPAD(v_next_number::text, 4, '0');
    END IF;
  ELSE
    -- Default to PREFIX-#### format
    v_format_prefix := COALESCE(NULLIF(p_prefix, ''), 'PO');
    v_po_number := v_format_prefix || '-' || LPAD(v_next_number::text, 4, '0');
  END IF;
  
  RETURN v_po_number;
END;
$$;


ALTER FUNCTION "supply_chain"."generate_po_number"("p_tenant_id" "uuid", "p_format" "text", "p_prefix" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."generate_po_number"("p_tenant_id" "uuid", "p_format" "text", "p_prefix" "text") IS 'Atomically generates unique PO numbers with configurable format, preventing race conditions';



CREATE OR REPLACE FUNCTION "supply_chain"."generate_reorder_pos"("p_tenant_id" "uuid") RETURNS TABLE("vendor_id" "uuid", "location_id" "uuid", "items_count" integer, "total_estimated_cost" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- This function can be called by a cron job
    -- It creates draft POs grouped by vendor and delivery location
    
    RETURN QUERY
    WITH reorders AS (
        SELECT
            rs.preferred_vendor_id,
            rs.location_id,
            rs.catalog_item_id,
            rs.suggested_order_qty,
            rs.estimated_unit_cost,
            ROW_NUMBER() OVER (
                PARTITION BY rs.preferred_vendor_id, rs.location_id
                ORDER BY rs.inventory_position ASC
            ) AS line_number
        FROM inventory.v_reorder_suggestions rs
        WHERE rs.tenant_id = p_tenant_id
          AND rs.preferred_vendor_id IS NOT NULL
          AND rs.suggested_order_qty > 0
    ),
    po_groups AS (
        SELECT
            preferred_vendor_id,
            location_id,
            COUNT(*) AS items_count,
            SUM(suggested_order_qty * COALESCE(estimated_unit_cost, 0)) AS total_cost
        FROM reorders
        GROUP BY preferred_vendor_id, location_id
    )
    SELECT
        pg.preferred_vendor_id AS vendor_id,
        pg.location_id,
        pg.items_count::INTEGER,
        pg.total_cost
    FROM po_groups pg;
    
    -- Note: Actual PO creation would be done by calling application
    -- to avoid side effects in this function
END;
$$;


