COMMENT ON FUNCTION "supply_chain"."generate_reorder_pos"("p_tenant_id" "uuid") IS 'Analyze reorder suggestions and return draft PO groupings';



CREATE OR REPLACE FUNCTION "supply_chain"."generate_vendor_code"("p_tenant_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'public'
    AS $$
DECLARE
  v_settings supply_chain.tenant_settings;
  v_seq INTEGER;
  v_code TEXT;
  v_padding INTEGER;
BEGIN
  SELECT * INTO v_settings
  FROM supply_chain.tenant_settings
  WHERE tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_settings := supply_chain.get_or_create_tenant_settings(p_tenant_id);
  END IF;

  v_padding := GREATEST(1, COALESCE(v_settings.vendor_code_sequence_padding, 4));

  LOOP
    v_seq := COALESCE(v_settings.vendor_code_next_seq, 0) + 1;
    v_code := LPAD(v_seq::TEXT, v_padding, '0');

    IF v_settings.vendor_code_prefix IS NOT NULL THEN
      v_code := v_settings.vendor_code_prefix || v_code;
    END IF;

    IF v_settings.vendor_code_suffix IS NOT NULL THEN
      v_code := v_code || v_settings.vendor_code_suffix;
    END IF;

    EXIT WHEN NOT EXISTS (
      SELECT 1
      FROM supply_chain.vendors
      WHERE tenant_id = p_tenant_id AND code = v_code
    );

    v_settings.vendor_code_next_seq := v_seq;
  END LOOP;

  UPDATE supply_chain.tenant_settings
  SET vendor_code_next_seq = v_seq,
      updated_at = NOW()
  WHERE tenant_id = p_tenant_id;

  RETURN v_code;
END;
$$;


ALTER FUNCTION "supply_chain"."generate_vendor_code"("p_tenant_id" "uuid") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "supply_chain"."tenant_settings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "po_number_format" "text" DEFAULT 'sequential-year'::"text" NOT NULL,
    "po_number_prefix" "text",
    "po_number_current_seq" integer DEFAULT 0,
    "po_number_custom_template" "text",
    "auto_approve_enabled" boolean DEFAULT false,
    "auto_approve_limit" numeric(12,2),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "vendor_auto_approve_limits" "jsonb" DEFAULT '{}'::"jsonb",
    "cycle_count_number_format" "text" DEFAULT 'date-sequential'::"text",
    "cycle_count_number_prefix" "text" DEFAULT 'CC'::"text",
    "last_event_id" "text" NOT NULL,
    "vendor_code_strategy" "text" DEFAULT 'manual'::"text" NOT NULL,
    "vendor_code_required" boolean DEFAULT false NOT NULL,
    "vendor_code_case" "text" DEFAULT 'preserve'::"text" NOT NULL,
    "vendor_code_min_length" integer,
    "vendor_code_max_length" integer,
    "vendor_code_prefix" "text",
    "vendor_code_suffix" "text",
    "vendor_code_allowed_chars" "text",
    "vendor_code_regex" "text",
    "vendor_code_user_editable" boolean DEFAULT true NOT NULL,
    "vendor_code_immutable_after_use" boolean DEFAULT true NOT NULL,
    "vendor_code_sequence_padding" integer DEFAULT 4 NOT NULL,
    "vendor_code_next_seq" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "check_cycle_count_number_format" CHECK (("cycle_count_number_format" = ANY (ARRAY['date-sequential'::"text", 'sequential-year'::"text", 'sequential'::"text"]))),
    CONSTRAINT "tenant_settings_vendor_code_case_check" CHECK (("vendor_code_case" = ANY (ARRAY['upper'::"text", 'lower'::"text", 'preserve'::"text"]))),
    CONSTRAINT "tenant_settings_vendor_code_strategy_check" CHECK (("vendor_code_strategy" = ANY (ARRAY['manual'::"text", 'sequential'::"text", 'hybrid'::"text", 'import'::"text"])))
);


ALTER TABLE "supply_chain"."tenant_settings" OWNER TO "postgres";


COMMENT ON TABLE "supply_chain"."tenant_settings" IS 'Tenant-specific settings for purchase order numbering and approval rules';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."po_number_format" IS 'Format type: sequential-year (26-0001), sequential (0001), timestamp (PO-ABC123), or custom';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."auto_approve_limit" IS 'POs under this total amount will be auto-approved if enabled';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."vendor_auto_approve_limits" IS 'Per-vendor auto-approve limits as JSON: {"vendor_id": amount}. If set, overrides global limit for that vendor.';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."cycle_count_number_format" IS 'Format for cycle count numbers: date-sequential (CC-20260129-00001), sequential-year (CC-26-0001), or sequential (CC-0001)';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."cycle_count_number_prefix" IS 'Optional prefix for cycle count numbers (e.g., CC, COUNT)';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."vendor_code_strategy" IS 'manual | sequential | hybrid | import';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."vendor_code_required" IS 'If true, vendor code is required unless auto-generated.';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."vendor_code_case" IS 'upper | lower | preserve';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."vendor_code_allowed_chars" IS 'Character class for validation, e.g. A-Z0-9_-';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."vendor_code_regex" IS 'Optional regex validation for vendor codes.';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."vendor_code_sequence_padding" IS 'Left-pad length for sequential codes.';



COMMENT ON COLUMN "supply_chain"."tenant_settings"."vendor_code_next_seq" IS 'Next sequence number for sequential vendor codes.';



CREATE OR REPLACE FUNCTION "supply_chain"."get_or_create_tenant_settings"("p_tenant_id" "uuid") RETURNS "supply_chain"."tenant_settings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_settings supply_chain.tenant_settings;
BEGIN
  SELECT * INTO v_settings
  FROM supply_chain.tenant_settings
  WHERE tenant_id = p_tenant_id;

  IF NOT FOUND THEN
    PERFORM public.ensure_tenant_exists(p_tenant_id);

    INSERT INTO supply_chain.tenant_settings (
      tenant_id,
      po_number_format,
      po_number_prefix,
      po_number_current_seq,
      auto_approve_enabled,
      auto_approve_limit,
      vendor_code_strategy,
      vendor_code_required,
      vendor_code_case,
      vendor_code_min_length,
      vendor_code_max_length,
      vendor_code_prefix,
      vendor_code_suffix,
      vendor_code_allowed_chars,
      vendor_code_regex,
      vendor_code_user_editable,
      vendor_code_immutable_after_use,
      vendor_code_sequence_padding,
      vendor_code_next_seq,
      last_event_id
    ) VALUES (
      p_tenant_id,
      'sequential-year',
      NULL,
      0,
      false,
      NULL,
      'manual',
      false,
      'preserve',
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      true,
      true,
      4,
      0,
      gen_random_uuid()::text
    )
    RETURNING * INTO v_settings;
  END IF;

  RETURN v_settings;
END;
$$;


ALTER FUNCTION "supply_chain"."get_or_create_tenant_settings"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."get_vendor_auto_approve_limit"("p_tenant_id" "uuid", "p_vendor_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_settings supply_chain.tenant_settings;
  v_vendor_limit NUMERIC;
BEGIN
  -- Get tenant settings
  SELECT * INTO v_settings
  FROM supply_chain.tenant_settings
  WHERE tenant_id = p_tenant_id;
  
  -- If no settings or auto-approve not enabled, return null
  IF NOT FOUND OR NOT v_settings.auto_approve_enabled THEN
    RETURN NULL;
  END IF;
  
  -- Check for vendor-specific limit first
  IF v_settings.vendor_auto_approve_limits IS NOT NULL THEN
    v_vendor_limit := (v_settings.vendor_auto_approve_limits->>p_vendor_id::text)::numeric;
    
    IF v_vendor_limit IS NOT NULL THEN
      RETURN v_vendor_limit;
    END IF;
  END IF;
  
  -- Fall back to global limit
  RETURN v_settings.auto_approve_limit;
END;
$$;


ALTER FUNCTION "supply_chain"."get_vendor_auto_approve_limit"("p_tenant_id" "uuid", "p_vendor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."poll_pending_events"("p_batch_size" integer DEFAULT 100, "p_max_attempts" integer DEFAULT 5) RETURNS TABLE("id" "uuid", "tenant_id" "uuid", "scope" "text", "event_type" "text", "aggregate_type" "text", "aggregate_id" "uuid", "payload" "jsonb", "metadata" "jsonb", "status" "text", "retry_count" integer, "created_at" timestamp with time zone, "last_error" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        e.id,
        e.tenant_id,
        e.scope,
        e.event_type,
        e.aggregate_type,
        e.aggregate_id,
        e.payload,
        e.metadata,
        e.status,
        e.retry_count,
        e.created_at,
        e.last_error
    FROM inventory.events_outbox e
    WHERE e.status = 'pending'
    AND e.retry_count < p_max_attempts
    AND e.created_at <= NOW() -- Only process events in the past
    ORDER BY e.created_at ASC
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED; -- Critical: prevents concurrent processing
END;
$$;


ALTER FUNCTION "supply_chain"."poll_pending_events"("p_batch_size" integer, "p_max_attempts" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."poll_pending_events"("p_batch_size" integer, "p_max_attempts" integer) IS 'Selects pending events for processing by events-poller Edge Function. Uses row-level locking to prevent concurrent processing.';



CREATE OR REPLACE FUNCTION "supply_chain"."process_stock_receipt"("p_tenant_id" "uuid", "p_po_id" "uuid", "p_location_id" "uuid", "p_received_items" "jsonb", "p_received_by_user_id" "uuid", "p_last_event_id" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_receipt_id UUID;
    v_item JSONB;
    v_po_line RECORD;
    v_movement_id UUID;
BEGIN
    -- Create receipt record
    INSERT INTO inventory.receipts (
        tenant_id,
        po_id,
        receipt_number,
        received_at,
        received_by_user_id,
        location_id,
        last_event_id
    ) VALUES (
        p_tenant_id,
        p_po_id,
        'RCV-' || EXTRACT(EPOCH FROM NOW())::BIGINT::TEXT,
        NOW(),
        p_received_by_user_id,
        p_location_id,
        p_last_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_receipt_id;
    
    -- If already processed, return existing receipt
    IF v_receipt_id IS NULL THEN
        SELECT id INTO v_receipt_id
        FROM inventory.receipts
        WHERE tenant_id = p_tenant_id AND last_event_id = p_last_event_id;
        RETURN v_receipt_id;
    END IF;
    
    -- Process each received item
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_received_items)
    LOOP
        -- Get PO line details
        SELECT * INTO v_po_line
        FROM inventory.purchase_order_lines
        WHERE id = (v_item->>'po_line_id')::UUID
          AND tenant_id = p_tenant_id;
        
        IF v_po_line.id IS NULL THEN
            RAISE EXCEPTION 'PO line not found: %', v_item->>'po_line_id';
        END IF;
        
        -- Create receipt line
        INSERT INTO inventory.receipt_lines (
            tenant_id,
            receipt_id,
            po_line_id,
            line_number,
            catalog_item_id,
            qty_received
        ) VALUES (
            p_tenant_id,
            v_receipt_id,
            v_po_line.id,
            (v_item->>'line_number')::INTEGER,
            v_po_line.catalog_item_id,
            (v_item->>'qty_received')::NUMERIC
        );
        
        -- Create stock movement
        v_movement_id := inventory.insert_stock_movement(
            p_tenant_id,
            v_po_line.catalog_item_id,
            p_location_id,
            (v_item->>'qty_received')::NUMERIC,
            'received',
            'receipt',
            v_receipt_id,
            (v_item->>'unit_cost')::NUMERIC,
            'Received from PO ' || v_po_line.po_id::TEXT,
            NULL,
            NULL,
            NOW(),
            p_received_by_user_id,
            p_last_event_id || '_line_' || v_po_line.id::TEXT
        );
        
        -- Update PO line received quantity
        UPDATE inventory.purchase_order_lines
        SET qty_received = qty_received + (v_item->>'qty_received')::NUMERIC,
            status = CASE
                WHEN qty_received + (v_item->>'qty_received')::NUMERIC >= qty_ordered THEN 'received'
                ELSE 'partially_received'
            END
        WHERE id = v_po_line.id;
    END LOOP;
    
    -- Update PO status
    UPDATE inventory.purchase_orders
    SET status = CASE
        WHEN EXISTS (
            SELECT 1 FROM inventory.purchase_order_lines
            WHERE po_id = p_po_id AND status != 'received'
        ) THEN 'partially_received'
        ELSE 'received'
    END
    WHERE id = p_po_id;
    
    RETURN v_receipt_id;
END;
$$;


ALTER FUNCTION "supply_chain"."process_stock_receipt"("p_tenant_id" "uuid", "p_po_id" "uuid", "p_location_id" "uuid", "p_received_items" "jsonb", "p_received_by_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."process_stock_receipt"("p_tenant_id" "uuid", "p_po_id" "uuid", "p_location_id" "uuid", "p_received_items" "jsonb", "p_received_by_user_id" "uuid", "p_last_event_id" "text") IS 'Idempotently process a stock receipt from a purchase order';



CREATE OR REPLACE FUNCTION "supply_chain"."record_po_vendor_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Record PO creation
  IF TG_OP = 'INSERT' THEN
    INSERT INTO supply_chain.vendor_performance_events (
      tenant_id,
      vendor_id,
      event_type,
      event_date,
      po_id,
      amount,
      metadata
    )
    SELECT
      NEW.tenant_id,
      v.id as vendor_id,
      'po_created',
      NEW.created_at,
      NEW.id,
      (SELECT SUM(qty_ordered * COALESCE(unit_cost, 0)) FROM supply_chain.purchase_order_lines WHERE po_id = NEW.id),
      jsonb_build_object('po_number', NEW.po_number, 'status', NEW.status)
    FROM supply_chain.vendors v
    JOIN inventory.locations vl ON vl.id = NEW.vendor_location_id
    WHERE v.tenant_id = NEW.tenant_id
    LIMIT 1;

  -- Record PO cancellation
  ELSIF TG_OP = 'UPDATE' AND OLD.status != 'cancelled' AND NEW.status = 'cancelled' THEN
    INSERT INTO supply_chain.vendor_performance_events (
      tenant_id,
      vendor_id,
      event_type,
      event_date,
      po_id,
      amount,
      metadata
    )
    SELECT
      NEW.tenant_id,
      v.id as vendor_id,
      'po_cancelled',
      now(),
      NEW.id,
      (SELECT SUM(qty_ordered * COALESCE(unit_cost, 0)) FROM supply_chain.purchase_order_lines WHERE po_id = NEW.id),
      jsonb_build_object('po_number', NEW.po_number, 'cancelled_reason', NEW.notes)
    FROM supply_chain.vendors v
    JOIN inventory.locations vl ON vl.id = NEW.vendor_location_id
    WHERE v.tenant_id = NEW.tenant_id
    LIMIT 1;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "supply_chain"."record_po_vendor_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."record_po_vendor_event"() IS 'FIXED: Records vendor performance events when POs are created or cancelled';



CREATE OR REPLACE FUNCTION "supply_chain"."record_receipt_vendor_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_vendor_id UUID;
  v_expected_date DATE;
  v_days_late INTEGER;
BEGIN
  -- Get vendor from associated PO
  SELECT 
    v.id,
    po.expected_delivery_date
  INTO v_vendor_id, v_expected_date
  FROM supply_chain.purchase_orders po
  JOIN inventory.locations vl ON vl.id = po.vendor_location_id
  JOIN supply_chain.vendors v ON v.tenant_id = po.tenant_id
  WHERE po.id = NEW.po_id
  LIMIT 1;

  IF v_vendor_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Calculate lateness
  v_days_late := GREATEST(0, EXTRACT(DAY FROM NEW.received_at::date - v_expected_date));

  -- Record delivery event
  IF v_days_late = 0 THEN
    INSERT INTO supply_chain.vendor_performance_events (
      tenant_id,
      vendor_id,
      event_type,
      event_date,
      po_id,
      receipt_id,
      expected_date,
      actual_date,
      days_late,
      metadata
    ) VALUES (
      NEW.tenant_id,
      v_vendor_id,
      'delivery_on_time',
      NEW.received_at,
      NEW.po_id,
      NEW.id,
      v_expected_date,
      NEW.received_at::date,
      0,
      jsonb_build_object('receipt_number', NEW.receipt_number)
    );
  ELSE
    INSERT INTO supply_chain.vendor_performance_events (
      tenant_id,
      vendor_id,
      event_type,
      event_date,
      po_id,
      receipt_id,
      expected_date,
      actual_date,
      days_late,
      metadata
    ) VALUES (
      NEW.tenant_id,
      v_vendor_id,
      'delivery_late',
      NEW.received_at,
      NEW.po_id,
      NEW.id,
      v_expected_date,
      NEW.received_at::date,
      v_days_late,
      jsonb_build_object('receipt_number', NEW.receipt_number, 'days_late', v_days_late)
    );
  END IF;

  -- Record items received
  INSERT INTO supply_chain.vendor_performance_events (
    tenant_id,
    vendor_id,
    event_type,
    event_date,
    po_id,
    receipt_id,
    quantity,
    metadata
  )
  SELECT
    NEW.tenant_id,
    v_vendor_id,
    'items_received',
    NEW.received_at,
    NEW.po_id,
    NEW.id,
    SUM(rl.qty_received),
    jsonb_build_object('receipt_number', NEW.receipt_number, 'line_count', COUNT(*))
  FROM supply_chain.receipt_lines rl
  WHERE rl.receipt_id = NEW.id
  GROUP BY NEW.tenant_id, NEW.po_id, NEW.id, NEW.received_at, NEW.receipt_number;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "supply_chain"."record_receipt_vendor_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."record_receipt_vendor_event"() IS 'FIXED: Records vendor performance events for deliveries (on-time/late tracking)';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_calculate_vendor_metrics"("p_start_date" "date" DEFAULT (CURRENT_DATE - '90 days'::interval), "p_end_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("vendor_id" "uuid", "vendor_name" "text", "overall_rating" numeric, "on_time_rate" numeric, "quality_score" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    vps.vendor_id,
    vps.vendor_name,
    vps.overall_rating,
    vps.on_time_delivery_rate,
    vps.quality_score
  FROM inventory.v_vendor_performance_summary vps
  WHERE vps.tenant_id = current_tenant_id()
    AND vps.pos_last_90_days > 0
  ORDER BY vps.overall_rating DESC NULLS LAST;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_calculate_vendor_metrics"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."rpc_cancel_receipt"("p_receipt_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_user_id UUID;
  v_receipt supply_chain.receipts%ROWTYPE;
BEGIN
  -- Get tenant and user from JWT
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  v_user_id := (auth.jwt() ->> 'user_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Fetch receipt
  SELECT * INTO v_receipt
  FROM supply_chain.receipts
  WHERE id = p_receipt_id
    AND tenant_id = v_tenant_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt not found';
  END IF;
  
  -- Check if already confirmed (cannot cancel after posting)
  IF v_receipt.status = 'confirmed' THEN
    RAISE EXCEPTION 'Cannot cancel confirmed receipt. Use reverse receipt function instead.';
  END IF;
  
  IF v_receipt.status = 'cancelled' THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Receipt already cancelled',
      'receipt_id', p_receipt_id
    );
  END IF;
  
  -- Update status to cancelled
  UPDATE supply_chain.receipts
  SET
    status = 'cancelled',
    notes = CASE 
      WHEN p_reason IS NOT NULL THEN COALESCE(notes || E'\n\n', '') || 'CANCELLED: ' || p_reason
      ELSE notes
    END,
    updated_at = NOW(),
    updated_by = v_user_id
  WHERE id = p_receipt_id
    AND tenant_id = v_tenant_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'receipt_id', p_receipt_id,
    'receipt_number', v_receipt.receipt_number,
    'status', 'cancelled',
    'message', 'Receipt cancelled successfully'
  );
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_cancel_receipt"("p_receipt_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_cancel_receipt"("p_receipt_id" "uuid", "p_reason" "text") IS 'Cancel a draft receipt. Cannot cancel confirmed receipts (use reverse instead).';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_confirm_receipt"("p_receipt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_user_id UUID;
  v_receipt supply_chain.receipts%ROWTYPE;
  v_post_result JSONB;
BEGIN
  -- Get tenant and user from JWT
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  v_user_id := (auth.jwt() ->> 'user_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Fetch receipt
  SELECT * INTO v_receipt
  FROM supply_chain.receipts
  WHERE id = p_receipt_id
    AND tenant_id = v_tenant_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt not found';
  END IF;
  
  -- Check current status
  IF v_receipt.status = 'cancelled' THEN
    RAISE EXCEPTION 'Cannot confirm cancelled receipt';
  END IF;
  
  IF v_receipt.status = 'confirmed' THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Receipt already confirmed',
      'receipt_id', p_receipt_id
    );
  END IF;
  
  -- Post to inventory (this will update status to 'confirmed')
  v_post_result := supply_chain.rpc_post_receipt_to_inventory_v2(
    p_receipt_id,
    v_user_id
  );
  
  RETURN v_post_result;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_confirm_receipt"("p_receipt_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_confirm_receipt"("p_receipt_id" "uuid") IS 'Confirm a draft receipt and post it to inventory. Idempotent.';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_create_purchase_order"("p_vendor_id" "uuid", "p_po_number" "text", "p_delivery_method" "text" DEFAULT 'ship'::"text", "p_needed_by_date" "date" DEFAULT NULL::"date", "p_cost_context" "text" DEFAULT 'yard'::"text", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_delivery_location_id" "uuid" DEFAULT NULL::"uuid", "p_pickup_location_id" "uuid" DEFAULT NULL::"uuid", "p_max_authorized_spend" numeric DEFAULT NULL::numeric, "p_vendor_quote_ref" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_attachments" "jsonb" DEFAULT '[]'::"jsonb", "p_lines" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_user_id UUID;
    v_po_id UUID;
    v_line JSONB;
    v_line_number INT := 0;
    v_total_estimated_cost NUMERIC := 0;
    v_has_unknown_pricing BOOLEAN := false;
    v_event_id UUID;
    v_vendor_name TEXT;
    v_vendor_code TEXT;
    v_result JSONB;
    v_generated_po_number TEXT;
BEGIN
    -- Support both JWT tenant_id paths (app_metadata or root)
    v_tenant_id := COALESCE(
        (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::UUID,
        (auth.jwt() ->> 'tenant_id')::UUID
    );
    v_user_id := COALESCE(
        (auth.jwt() -> 'app_metadata' ->> 'user_id')::UUID,
        (auth.jwt() ->> 'user_id')::UUID,
        (auth.jwt() ->> 'sub')::UUID
    );

    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required - no tenant_id in JWT';
    END IF;

    IF p_delivery_method = 'ship' AND p_delivery_location_id IS NULL THEN
        RAISE EXCEPTION 'delivery_location_id required when delivery_method = ship';
    END IF;

    IF p_delivery_method = 'pickup' AND p_pickup_location_id IS NULL THEN
        RAISE EXCEPTION 'pickup_location_id required when delivery_method = pickup';
    END IF;

    IF p_cost_context = 'job' AND p_job_id IS NULL THEN
        RAISE EXCEPTION 'job_id required when cost_context = job';
    END IF;

    -- Auto-generate PO number if not provided
    IF p_po_number IS NULL OR p_po_number = '' THEN
        v_generated_po_number := supply_chain.generate_po_number(v_tenant_id);
    ELSE
        v_generated_po_number := p_po_number;
    END IF;

    SELECT name, code INTO v_vendor_name, v_vendor_code
    FROM supply_chain.vendors
    WHERE id = p_vendor_id AND tenant_id = v_tenant_id;

    v_event_id := gen_random_uuid();

    INSERT INTO supply_chain.purchase_orders (
        tenant_id,
        po_number,
        vendor_id,
        vendor_name_snapshot,
        vendor_code_snapshot,
        delivery_method,
        needed_by_date,
        cost_context,
        job_id,
        delivery_location_id,
        pickup_location_id,
        max_authorized_spend,
        vendor_quote_ref,
        notes,
        attachments,
        status,
        order_date,
        last_event_id
    ) VALUES (
        v_tenant_id,
        v_generated_po_number,
        p_vendor_id,
        v_vendor_name,
        v_vendor_code,
        p_delivery_method,
        p_needed_by_date,
        p_cost_context,
        p_job_id,
        p_delivery_location_id,
        p_pickup_location_id,
        p_max_authorized_spend,
        p_vendor_quote_ref,
        p_notes,
        p_attachments,
        'draft',
        CURRENT_DATE,
        v_event_id
    )
    RETURNING id INTO v_po_id;

    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
        v_line_number := v_line_number + 1;

        INSERT INTO supply_chain.purchase_order_lines (
            tenant_id,
            po_id,
            line_number,
            catalog_item_id,
            item_description,
            unit_of_measure,
            qty_ordered,
            unit_cost,
            estimated_unit_cost,
            price_basis,
            is_approximate_qty,
            line_notes,
            status,
            last_event_id
        ) VALUES (
            v_tenant_id,
            v_po_id,
            v_line_number,
            (v_line->>'catalog_item_id')::UUID,
            v_line->>'item_description',
            v_line->>'unit_of_measure',
            (v_line->>'qty_ordered')::NUMERIC,
            (v_line->>'unit_cost')::NUMERIC,
            (v_line->>'estimated_unit_cost')::NUMERIC,
            COALESCE(v_line->>'price_basis', 'fixed'),
            COALESCE((v_line->>'is_approximate_qty')::BOOLEAN, false),
            v_line->>'line_notes',
            'pending',
            v_event_id
        );

        IF (v_line->>'unit_cost') IS NOT NULL THEN
            v_total_estimated_cost := v_total_estimated_cost + 
                ((v_line->>'qty_ordered')::NUMERIC * (v_line->>'unit_cost')::NUMERIC);
        ELSIF (v_line->>'estimated_unit_cost') IS NOT NULL THEN
            v_total_estimated_cost := v_total_estimated_cost + 
                ((v_line->>'qty_ordered')::NUMERIC * (v_line->>'estimated_unit_cost')::NUMERIC);
        ELSE
            v_has_unknown_pricing := true;
        END IF;
    END LOOP;

    -- Event will be created by triggers, not manually here

    v_result := jsonb_build_object(
        'success', true,
        'po_id', v_po_id,
        'po_number', v_generated_po_number,
        'line_count', v_line_number,
        'status', 'draft'
    );

    RETURN v_result;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_create_purchase_order"("p_vendor_id" "uuid", "p_po_number" "text", "p_delivery_method" "text", "p_needed_by_date" "date", "p_cost_context" "text", "p_job_id" "uuid", "p_delivery_location_id" "uuid", "p_pickup_location_id" "uuid", "p_max_authorized_spend" numeric, "p_vendor_quote_ref" "text", "p_notes" "text", "p_attachments" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_create_purchase_order"("p_vendor_id" "uuid", "p_po_number" "text", "p_delivery_method" "text", "p_needed_by_date" "date", "p_cost_context" "text", "p_job_id" "uuid", "p_delivery_location_id" "uuid", "p_pickup_location_id" "uuid", "p_max_authorized_spend" numeric, "p_vendor_quote_ref" "text", "p_notes" "text", "p_attachments" "jsonb", "p_lines" "jsonb") IS 'Create a purchase order with construction-friendly flexible line items. Supports both JWT tenant_id paths.';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_create_receipt"("p_receipt_number" "text", "p_location_id" "uuid", "p_lines" "jsonb", "p_po_id" "uuid" DEFAULT NULL::"uuid", "p_received_at" timestamp with time zone DEFAULT "now"(), "p_notes" "text" DEFAULT NULL::"text", "p_auto_post" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_receipt_id UUID;
  v_line JSONB;
  v_line_number INT := 0;
  v_post_result JSONB;
  v_result JSONB;
BEGIN
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Insert receipt header
  INSERT INTO supply_chain.receipts (
    tenant_id,
    receipt_number,
    location_id,
    po_id,
    received_at,
    notes,
    created_by_user_id
  ) VALUES (
    v_tenant_id,
    p_receipt_number,
    p_location_id,
    p_po_id,
    p_received_at,
    p_notes,
    (auth.jwt() ->> 'user_id')::UUID
  )
  RETURNING id INTO v_receipt_id;
  
  -- Insert receipt lines
  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_line_number := v_line_number + 1;
    
    INSERT INTO supply_chain.receipt_lines (
      tenant_id,
      receipt_id,
      line_number,
      catalog_item_id,
      qty_received,
      po_line_id
    ) VALUES (
      v_tenant_id,
      v_receipt_id,
      v_line_number,
      (v_line->>'catalog_item_id')::UUID,
      (v_line->>'qty_received')::NUMERIC,
      (v_line->>'po_line_id')::UUID
    );
  END LOOP;
  
  -- Auto-post to inventory if requested
  IF p_auto_post THEN
    v_post_result := supply_chain.rpc_post_receipt_to_inventory(
      v_receipt_id,
      (auth.jwt() ->> 'user_id')::UUID
    );
    
    v_result := jsonb_build_object(
      'success', true,
      'receipt_id', v_receipt_id,
      'receipt_number', p_receipt_number,
      'line_count', v_line_number,
      'posted_to_inventory', true,
      'post_result', v_post_result
    );
  ELSE
    v_result := jsonb_build_object(
      'success', true,
      'receipt_id', v_receipt_id,
      'receipt_number', p_receipt_number,
      'line_count', v_line_number,
      'posted_to_inventory', false
    );
  END IF;
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_create_receipt"("p_receipt_number" "text", "p_location_id" "uuid", "p_lines" "jsonb", "p_po_id" "uuid", "p_received_at" timestamp with time zone, "p_notes" "text", "p_auto_post" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_create_receipt"("p_receipt_number" "text", "p_location_id" "uuid", "p_lines" "jsonb", "p_po_id" "uuid", "p_received_at" timestamp with time zone, "p_notes" "text", "p_auto_post" boolean) IS 'Frontend RPC: Create a receipt (and optionally auto-post to inventory).
Set p_auto_post=false to create receipt without posting.
Returns: {success, receipt_id, receipt_number, line_count, posted_to_inventory, post_result}';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_create_receipt_v2"("p_receipt_number" "text" DEFAULT NULL::"text", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_lines" "jsonb" DEFAULT NULL::"jsonb", "p_po_id" "uuid" DEFAULT NULL::"uuid", "p_vendor_id" "uuid" DEFAULT NULL::"uuid", "p_received_at" timestamp with time zone DEFAULT "now"(), "p_notes" "text" DEFAULT NULL::"text", "p_packing_slip_no" "text" DEFAULT NULL::"text", "p_vendor_invoice_no" "text" DEFAULT NULL::"text", "p_source_type" "text" DEFAULT 'delivery'::"text", "p_status" "text" DEFAULT 'confirmed'::"text", "p_auto_post" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $_$
DECLARE
  v_tenant_id UUID;
  v_user_id UUID;
  v_receipt_id UUID;
  v_receipt_number TEXT;
  v_line JSONB;
  v_line_number INT := 0;
  v_post_result JSONB;
  v_result JSONB;
  v_event_id TEXT;
  v_next_seq INT;
BEGIN
  -- Support both JWT tenant_id paths (app_metadata or root)
  v_tenant_id := COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::UUID,
    (auth.jwt() ->> 'tenant_id')::UUID
  );
  
  -- Support both JWT user_id paths
  v_user_id := COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'user_id')::UUID,
    (auth.jwt() ->> 'user_id')::UUID,
    (auth.jwt() ->> 'sub')::UUID
  );
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required - no tenant_id in JWT';
  END IF;
  
  IF p_location_id IS NULL THEN
    RAISE EXCEPTION 'location_id is required';
  END IF;
  
  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'At least one line item is required';
  END IF;
  
  -- Auto-generate receipt number if not provided
  IF p_receipt_number IS NULL OR p_receipt_number = '' THEN
    -- Get next sequence number for this tenant
    SELECT COALESCE(MAX(CAST(SUBSTRING(receipt_number FROM '[0-9]+$') AS INTEGER)), 0) + 1
    INTO v_next_seq
    FROM supply_chain.receipts
    WHERE tenant_id = v_tenant_id
      AND receipt_number ~ '^RCV-[0-9]+$';
    
    v_receipt_number := 'RCV-' || LPAD(v_next_seq::TEXT, 6, '0');
  ELSE
    v_receipt_number := p_receipt_number;
  END IF;
  
  -- Validate status
  IF p_status NOT IN ('draft', 'confirmed', 'cancelled') THEN
    RAISE EXCEPTION 'Invalid status: %. Must be draft, confirmed, or cancelled.', p_status;
  END IF;
  
  -- Validate source_type
  IF p_source_type NOT IN ('delivery', 'pickup', 'transfer', 'return') THEN
    RAISE EXCEPTION 'Invalid source_type: %. Must be delivery, pickup, transfer, or return.', p_source_type;
  END IF;
  
  -- Generate idempotency event_id for receipt
  v_event_id := 'receipt-create-' || v_receipt_number || '-' || extract(epoch from now())::TEXT;
  
  -- Insert receipt header
  INSERT INTO supply_chain.receipts (
    tenant_id,
    receipt_number,
    location_id,
    po_id,
    vendor_id,
    received_at,
    notes,
    packing_slip_no,
    vendor_invoice_no,
    source_type,
    status,
    received_by_user_id,
    last_event_id
  ) VALUES (
    v_tenant_id,
    v_receipt_number,
    p_location_id,
    p_po_id,
    p_vendor_id,
    COALESCE(p_received_at, now()),
    p_notes,
    p_packing_slip_no,
    p_vendor_invoice_no,
    p_source_type,
    p_status,
    v_user_id,
    v_event_id
  )
  ON CONFLICT (tenant_id, last_event_id) DO NOTHING
  RETURNING id INTO v_receipt_id;
  
  -- Check for duplicate (idempotency)
  IF v_receipt_id IS NULL THEN
    SELECT id INTO v_receipt_id
    FROM supply_chain.receipts
    WHERE tenant_id = v_tenant_id AND last_event_id = v_event_id;
    
    RETURN jsonb_build_object(
      'success', true,
      'receipt_id', v_receipt_id,
      'receipt_number', v_receipt_number,
      'message', 'Receipt already exists (idempotent)',
      'posted_to_inventory', false
    );
  END IF;
  
  -- Insert receipt lines
  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_line_number := v_line_number + 1;
    v_event_id := 'receipt-' || v_receipt_id::TEXT || '-line-' || v_line_number::TEXT || '-' || extract(epoch from now())::TEXT;
    
    INSERT INTO supply_chain.receipt_lines (
      tenant_id,
      receipt_id,
      line_number,
      catalog_item_id,
      qty_received,
      po_line_id,
      condition_status,
      destination_location_id,
      unit_cost_actual,
      uom,
      notes,
      last_event_id
    ) VALUES (
      v_tenant_id,
      v_receipt_id,
      v_line_number,
      (v_line->>'catalog_item_id')::UUID,
      (v_line->>'qty_received')::NUMERIC,
      (v_line->>'po_line_id')::UUID,
      COALESCE(v_line->>'condition_status', 'accepted'),
      (v_line->>'destination_location_id')::UUID,
      (v_line->>'unit_cost_actual')::NUMERIC,
      v_line->>'uom',
      v_line->>'notes',
      v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING;
  END LOOP;
  
  -- Auto-post to inventory if requested and status is confirmed
  IF p_auto_post AND p_status = 'confirmed' THEN
    BEGIN
      v_post_result := supply_chain.rpc_post_receipt_to_inventory(v_receipt_id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Failed to auto-post receipt % to inventory: %', v_receipt_id, SQLERRM;
      v_post_result := jsonb_build_object('success', false, 'error', SQLERRM);
    END;
  ELSE
    v_post_result := jsonb_build_object('success', false, 'message', 'Auto-post not requested or status is not confirmed');
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'receipt_id', v_receipt_id,
    'receipt_number', v_receipt_number,
    'lines_created', v_line_number,
    'auto_post_result', v_post_result
  );
END;
$_$;


ALTER FUNCTION "supply_chain"."rpc_create_receipt_v2"("p_receipt_number" "text", "p_location_id" "uuid", "p_lines" "jsonb", "p_po_id" "uuid", "p_vendor_id" "uuid", "p_received_at" timestamp with time zone, "p_notes" "text", "p_packing_slip_no" "text", "p_vendor_invoice_no" "text", "p_source_type" "text", "p_status" "text", "p_auto_post" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_create_receipt_v2"("p_receipt_number" "text", "p_location_id" "uuid", "p_lines" "jsonb", "p_po_id" "uuid", "p_vendor_id" "uuid", "p_received_at" timestamp with time zone, "p_notes" "text", "p_packing_slip_no" "text", "p_vendor_invoice_no" "text", "p_source_type" "text", "p_status" "text", "p_auto_post" boolean) IS 'Enhanced receipt creation with support for status, vendor_id, condition tracking, and more.
  If status=confirmed and auto_post=true, will automatically post to inventory.
  If status=draft, receipt is saved but not posted (allows for review/approval).';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_get_open_pos_for_receiving"("p_vendor_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("po_id" "uuid", "po_number" "text", "vendor_id" "uuid", "vendor_name" "text", "vendor_code" "text", "vendor_location_id" "uuid", "order_date" "date", "expected_delivery_date" "date", "delivery_location_id" "uuid", "delivery_location_name" "text", "delivery_method" "text", "status" "text", "total_lines" integer, "open_lines" integer, "partially_received_lines" integer, "fully_received_lines" integer, "total_ordered_value" numeric, "notes" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
BEGIN
  -- Support both JWT tenant_id paths (app_metadata or root)
  v_tenant_id := COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::UUID,
    (auth.jwt() ->> 'tenant_id')::UUID
  );

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  RETURN QUERY
  SELECT
    po.id AS po_id,
    po.po_number,
    po.vendor_id,
    COALESCE(po.vendor_name_snapshot, v.name) AS vendor_name,
    COALESCE(po.vendor_code_snapshot, v.code) AS vendor_code,
    po.vendor_location_id,
    po.order_date,
    po.expected_delivery_date,
    po.delivery_location_id,
    dl.name AS delivery_location_name,
    po.delivery_method,
    po.status,
    COUNT(pol.id)::INT AS total_lines,
    COUNT(pol.id) FILTER (WHERE pol.status = 'open')::INT AS open_lines,
    COUNT(pol.id) FILTER (WHERE pol.status = 'partially_received')::INT AS partially_received_lines,
    COUNT(pol.id) FILTER (WHERE pol.status = 'fully_received')::INT AS fully_received_lines,
    SUM(pol.qty_ordered * COALESCE(pol.unit_cost, pol.estimated_unit_cost, 0))::NUMERIC AS total_ordered_value,
    po.notes,
    po.created_at
  FROM supply_chain.purchase_orders po
  LEFT JOIN supply_chain.vendors v ON v.id = po.vendor_id
  LEFT JOIN inventory.locations dl ON dl.id = po.delivery_location_id
  LEFT JOIN supply_chain.purchase_order_lines pol ON pol.po_id = po.id AND pol.tenant_id = po.tenant_id
  WHERE po.tenant_id = v_tenant_id
    AND po.status IN ('placed', 'acknowledged', 'partially_received', 'approved')
    AND (p_vendor_id IS NULL OR po.vendor_id = p_vendor_id)
    AND (p_search IS NULL OR
         po.po_number ILIKE '%' || p_search || '%' OR
         COALESCE(po.vendor_name_snapshot, v.name) ILIKE '%' || p_search || '%' OR
         COALESCE(po.vendor_code_snapshot, v.code) ILIKE '%' || p_search || '%')
  GROUP BY
    po.id, po.po_number, po.vendor_id, po.vendor_location_id,
    po.order_date, po.expected_delivery_date, po.delivery_location_id,
    dl.name, po.delivery_method, po.status, po.notes, po.created_at,
    po.vendor_name_snapshot, po.vendor_code_snapshot, v.name, v.code
  ORDER BY
    po.expected_delivery_date ASC NULLS LAST,
    po.order_date DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_get_open_pos_for_receiving"("p_vendor_id" "uuid", "p_search" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."rpc_get_po_receipt_history"("p_po_id" "uuid") RETURNS TABLE("receipt_id" "uuid", "receipt_number" "text", "received_at" timestamp with time zone, "received_by_user_id" "uuid", "location_id" "uuid", "location_name" "text", "status" "text", "total_lines" integer, "total_qty_received" numeric, "packing_slip_no" "text", "vendor_invoice_no" "text", "notes" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
BEGIN
  -- Get tenant from JWT
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  RETURN QUERY
  SELECT 
    r.id AS receipt_id,
    r.receipt_number,
    r.received_at,
    r.received_by_user_id,
    r.location_id,
    l.name AS location_name,
    r.status,
    COUNT(rl.id)::INT AS total_lines,
    SUM(rl.qty_received)::NUMERIC AS total_qty_received,
    r.packing_slip_no,
    r.vendor_invoice_no,
    r.notes,
    r.created_at
  FROM supply_chain.receipts r
  LEFT JOIN inventory.locations l ON l.id = r.location_id
  LEFT JOIN supply_chain.receipt_lines rl ON rl.receipt_id = r.id AND rl.tenant_id = r.tenant_id
  WHERE r.po_id = p_po_id
    AND r.tenant_id = v_tenant_id
  GROUP BY 
    r.id, r.receipt_number, r.received_at, r.received_by_user_id,
    r.location_id, l.name, r.status, r.packing_slip_no, 
    r.vendor_invoice_no, r.notes, r.created_at
  ORDER BY r.received_at DESC, r.created_at DESC;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_get_po_receipt_history"("p_po_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_get_po_receipt_history"("p_po_id" "uuid") IS 'Get all receipts for a specific PO, ordered by received_at DESC';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_get_po_receiving_detail"("p_po_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_result JSONB;
  v_lines JSONB;
BEGIN
  -- Support both JWT tenant_id paths (app_metadata or root)
  v_tenant_id := COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::UUID,
    (auth.jwt() ->> 'tenant_id')::UUID
  );

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT jsonb_build_object(
    'po_id', po.id,
    'po_number', po.po_number,
    'vendor_id', po.vendor_id,
    'vendor_name', COALESCE(po.vendor_name_snapshot, v.name),
    'vendor_code', COALESCE(po.vendor_code_snapshot, v.code),
    'vendor_location_id', po.vendor_location_id,
    'status', po.status,
    'order_date', po.order_date,
    'expected_delivery_date', po.expected_delivery_date,
    'delivery_location_id', po.delivery_location_id,
    'delivery_method', po.delivery_method,
    'notes', po.notes
  ) INTO v_result
  FROM supply_chain.purchase_orders po
  LEFT JOIN supply_chain.vendors v ON v.id = po.vendor_id AND v.tenant_id = po.tenant_id
  WHERE po.id = p_po_id
    AND po.tenant_id = v_tenant_id;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'PO not found or access denied';
  END IF;

  -- Get lines with receiving details
  SELECT jsonb_agg(
    jsonb_build_object(
      'line_id', pol.id,
      'catalog_item_id', pol.catalog_item_id,
      'item_name', COALESCE(ci.name, pol.item_description),
      'item_description', pol.item_description,
      'unit_of_measure', pol.unit_of_measure,
      'qty_ordered', pol.qty_ordered,
      'qty_received', COALESCE(
        (
          SELECT SUM(rl.qty_received)
          FROM supply_chain.receipt_lines rl
          JOIN supply_chain.receipts r ON r.id = rl.receipt_id
          WHERE rl.po_line_id = pol.id
            AND r.status = 'confirmed'
            AND rl.tenant_id = v_tenant_id
        ),
        0
      ),
      'qty_remaining', pol.qty_ordered - COALESCE(
        (
          SELECT SUM(rl.qty_received)
          FROM supply_chain.receipt_lines rl
          JOIN supply_chain.receipts r ON r.id = rl.receipt_id
          WHERE rl.po_line_id = pol.id
            AND r.status = 'confirmed'
            AND rl.tenant_id = v_tenant_id
        ),
        0
      ),
      'unit_cost', pol.unit_cost,
      'estimated_unit_cost', pol.estimated_unit_cost,
      'line_notes', pol.line_notes
    )
    ORDER BY pol.created_at
  ) INTO v_lines
  FROM supply_chain.purchase_order_lines pol
  LEFT JOIN inventory.catalog_items ci ON ci.id = pol.catalog_item_id AND ci.tenant_id = pol.tenant_id
  WHERE pol.po_id = p_po_id
    AND pol.tenant_id = v_tenant_id;

  v_result := v_result || jsonb_build_object('lines', COALESCE(v_lines, '[]'::jsonb));

  RETURN v_result;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_get_po_receiving_detail"("p_po_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."rpc_get_receipt_detail"("p_receipt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_result JSONB;
  v_lines JSONB;
BEGIN
  -- Get tenant from JWT
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Build receipt header JSON
  SELECT jsonb_build_object(
    'receipt_id', r.id,
    'receipt_number', r.receipt_number,
    'po_id', r.po_id,
    'po_number', po.po_number,
    'vendor_id', r.vendor_id,
    'vendor_name', v.name,
    'location_id', r.location_id,
    'location_name', l.name,
    'received_at', r.received_at,
    'received_by_user_id', r.received_by_user_id,
    'status', r.status,
    'source_type', r.source_type,
    'packing_slip_no', r.packing_slip_no,
    'vendor_invoice_no', r.vendor_invoice_no,
    'notes', r.notes,
    'created_at', r.created_at,
    'created_by', r.created_by,
    'updated_at', r.updated_at
  )
  INTO v_result
  FROM supply_chain.receipts r
  LEFT JOIN supply_chain.purchase_orders po ON po.id = r.po_id
  LEFT JOIN supply_chain.vendors v ON v.id = r.vendor_id
  LEFT JOIN inventory.locations l ON l.id = r.location_id
  WHERE r.id = p_receipt_id
    AND r.tenant_id = v_tenant_id;
  
  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Receipt % not found', p_receipt_id;
  END IF;
  
  -- Build lines array
  SELECT jsonb_agg(
    jsonb_build_object(
      'line_id', rl.id,
      'line_number', rl.line_number,
      'po_line_id', rl.po_line_id,
      'catalog_item_id', rl.catalog_item_id,
      'item_name', ci.name,
      'item_sku', ci.sku,
      'qty_received', rl.qty_received,
      'condition_status', rl.condition_status,
      'destination_location_id', rl.destination_location_id,
      'destination_location_name', dl.name,
      'unit_cost_actual', rl.unit_cost_actual,
      'uom', rl.uom,
      'notes', rl.notes,
      'created_at', rl.created_at
    )
    ORDER BY rl.line_number
  )
  INTO v_lines
  FROM supply_chain.receipt_lines rl
  LEFT JOIN inventory.catalog_items ci ON ci.id = rl.catalog_item_id
  LEFT JOIN inventory.locations dl ON dl.id = rl.destination_location_id
  WHERE rl.receipt_id = p_receipt_id
    AND rl.tenant_id = v_tenant_id;
  
  -- Combine header + lines
  v_result := v_result || jsonb_build_object('lines', COALESCE(v_lines, '[]'::jsonb));
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_get_receipt_detail"("p_receipt_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_get_receipt_detail"("p_receipt_id" "uuid") IS 'Get full receipt details including all lines, vendor info, and location info';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_get_recent_receipts"("p_days" integer DEFAULT 30) RETURNS TABLE("receipt_id" "uuid", "receipt_number" "text", "po_id" "uuid", "po_number" "text", "vendor_id" "uuid", "vendor_name" "text", "vendor_code" "text", "location_id" "uuid", "location_name" "text", "status" "text", "total_qty" numeric, "received_at" timestamp with time zone, "received_by_user_id" "uuid", "packing_slip_no" "text", "notes" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
BEGIN
  -- Support both JWT tenant_id paths (app_metadata or root)
  v_tenant_id := COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::UUID,
    (auth.jwt() ->> 'tenant_id')::UUID
  );

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  RETURN QUERY
  SELECT 
    r.id as receipt_id,
    r.receipt_number,
    r.po_id,
    po.po_number,
    r.vendor_id,
    COALESCE(r.vendor_name_snapshot, v.name) as vendor_name,
    COALESCE(r.vendor_code_snapshot, v.code) as vendor_code,
    r.location_id,
    l.name as location_name,
    r.status,
    COALESCE(SUM(rl.qty_received), 0) as total_qty,
    r.received_at,
    r.received_by_user_id,
    r.packing_slip_no,
    r.notes
  FROM supply_chain.receipts r
  LEFT JOIN supply_chain.purchase_orders po ON r.po_id = po.id AND po.tenant_id = v_tenant_id
  LEFT JOIN supply_chain.vendors v ON r.vendor_id = v.id AND v.tenant_id = v_tenant_id
  LEFT JOIN inventory.locations l ON r.location_id = l.id AND l.tenant_id = v_tenant_id
  LEFT JOIN supply_chain.receipt_lines rl ON rl.receipt_id = r.id AND rl.tenant_id = v_tenant_id
  WHERE r.tenant_id = v_tenant_id
    AND r.status = 'confirmed'
    AND r.received_at >= NOW() - (p_days || ' days')::INTERVAL
  GROUP BY 
    r.id, r.receipt_number, r.po_id, po.po_number, r.vendor_id,
    r.vendor_name_snapshot, r.vendor_code_snapshot, v.name, v.code,
    r.location_id, l.name, r.status, r.received_at, r.received_by_user_id,
    r.packing_slip_no, r.notes
  ORDER BY r.received_at DESC;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_get_recent_receipts"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."rpc_get_tenant_settings"() RETURNS "supply_chain"."tenant_settings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_settings supply_chain.tenant_settings;
BEGIN
  v_tenant_id := public.current_tenant_id();
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required - no tenant_id in JWT';
  END IF;

  SELECT * INTO v_settings
  FROM supply_chain.tenant_settings
  WHERE tenant_id = v_tenant_id;

  IF NOT FOUND THEN
    v_settings := supply_chain.get_or_create_tenant_settings(v_tenant_id);
  END IF;

  RETURN v_settings;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_get_tenant_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."rpc_mark_po_ordered"("p_po_id" "uuid", "p_external_order_number" "text" DEFAULT NULL::"text", "p_order_placement_method" "text" DEFAULT 'portal'::"text", "p_order_placement_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_user_id UUID;
    v_po RECORD;
    v_event_id UUID;
    v_result JSONB;
BEGIN
    -- Get tenant and user from auth context
    v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
    v_user_id := (auth.jwt() ->> 'user_id')::UUID;
    
    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required - no tenant_id in JWT';
    END IF;
    
    -- Get PO and validate
    SELECT * INTO v_po
    FROM supply_chain.purchase_orders
    WHERE id = p_po_id
        AND tenant_id = v_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Purchase order not found';
    END IF;
    
    -- Validate status allows ordering
    IF v_po.status NOT IN ('draft', 'approved') THEN
        RAISE EXCEPTION 'Cannot mark PO as ordered - status is %', v_po.status;
    END IF;
    
    -- Generate event ID
    v_event_id := gen_random_uuid();
    
    -- Update PO with external order details
    UPDATE supply_chain.purchase_orders
    SET 
        status = 'placed',
        external_order_number = p_external_order_number,
        ordered_at = NOW(),
        ordered_by_user_id = v_user_id,
        order_placement_method = p_order_placement_method,
        order_placement_notes = p_order_placement_notes,
        updated_at = NOW(),
        updated_by = v_user_id
    WHERE id = p_po_id;
    
    -- Emit event
    PERFORM inventory.publish_event(
        p_tenant_id := v_tenant_id,
        p_scope := 'supply_chain',
        p_event_name := 'purchase_order.ordered_externally',
        p_aggregate_type := 'purchase_order',
        p_aggregate_id := p_po_id,
        p_payload := jsonb_build_object(
            'po_id', p_po_id,
            'po_number', v_po.po_number,
            'external_order_number', p_external_order_number,
            'order_placement_method', p_order_placement_method,
            'vendor_id', v_po.vendor_id
        ),
        p_event_version := 1,
        p_metadata := jsonb_build_object(
            'ordered_by', v_user_id,
            'source', 'rpc_mark_po_ordered'
        )
    );
    
    -- Build result
    v_result := jsonb_build_object(
        'success', true,
        'po_id', p_po_id,
        'po_number', v_po.po_number,
        'status', 'placed',
        'external_order_number', p_external_order_number,
        'ordered_at', NOW(),
        'event_id', v_event_id
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_mark_po_ordered"("p_po_id" "uuid", "p_external_order_number" "text", "p_order_placement_method" "text", "p_order_placement_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_mark_po_ordered"("p_po_id" "uuid", "p_external_order_number" "text", "p_order_placement_method" "text", "p_order_placement_notes" "text") IS 'Record that order was placed with vendor (portal/phone/email). 
PO remains the internal authorization regardless of how order was placed.';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_match_expense_to_po"("p_tenant_id" "uuid", "p_expense_id" "uuid", "p_po_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'inventory', 'public'
    AS $$
DECLARE
    v_expense RECORD;
    v_po RECORD;
BEGIN
    -- Verify expense exists and is matchable
    SELECT * INTO v_expense
    FROM inventory.accounting_expenses
    WHERE id = p_expense_id
      AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Expense not found';
    END IF;
    
    IF v_expense.status NOT IN ('posted', 'disputed') THEN
        RAISE EXCEPTION 'Expense cannot be matched in status: %', v_expense.status;
    END IF;
    
    -- Verify PO exists
    SELECT * INTO v_po
    FROM inventory.purchase_orders
    WHERE id = p_po_id
      AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Purchase order not found';
    END IF;
    
    -- Perform match
    UPDATE inventory.accounting_expenses
    SET 
        status = 'matched',
        po_id = p_po_id,
        matched_at = NOW(),
        updated_at = NOW()
    WHERE id = p_expense_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'accounting_expense.matched',
        p_aggregate_type => 'accounting_expense',
        p_aggregate_id => p_expense_id,
        p_payload => jsonb_build_object(
            'expense_id', p_expense_id,
            'po_id', p_po_id,
            'amount', v_expense.amount,
            'matched_by_user_id', p_user_id
        ),
        p_metadata => jsonb_build_object(
            'manual_match', true,
            'matched_at', NOW()
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_match_expense_to_po"("p_tenant_id" "uuid", "p_expense_id" "uuid", "p_po_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_match_expense_to_po"("p_tenant_id" "uuid", "p_expense_id" "uuid", "p_po_id" "uuid", "p_user_id" "uuid") IS 'Manually match an accounting expense to a purchase order. Validates status and publishes event.';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_post_receipt_to_inventory"("p_receipt_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_receipt supply_chain.receipts%ROWTYPE;
  v_line supply_chain.receipt_lines%ROWTYPE;
  v_catalog_item inventory.catalog_items%ROWTYPE;
  v_location inventory.locations%ROWTYPE;
  v_event_id TEXT;
  v_movement_id UUID;
  v_posted_count INT := 0;
  v_skipped_count INT := 0;
  v_result JSONB;
BEGIN
  -- Get tenant from JWT
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'No tenant_id in JWT. Authentication required.';
  END IF;
  
  -- Fetch receipt header
  SELECT * INTO v_receipt
  FROM supply_chain.receipts
  WHERE id = p_receipt_id
    AND tenant_id = v_tenant_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt % not found for tenant %', p_receipt_id, v_tenant_id;
  END IF;
  
  -- Validate receipt hasn't already been posted
  IF v_receipt.last_event_id IS NOT NULL THEN
    -- Check if inventory events already exist with this event_id
    IF EXISTS (
      SELECT 1 FROM inventory.inventory_events
      WHERE tenant_id = v_tenant_id
        AND payload->>'receipt_id' = p_receipt_id::TEXT
        AND last_event_id = v_receipt.last_event_id
    ) THEN
      RAISE NOTICE 'Receipt % already posted to inventory (idempotent). Skipping.', p_receipt_id;
      
      RETURN jsonb_build_object(
        'success', true,
        'receipt_id', p_receipt_id,
        'posted_lines', 0,
        'skipped_lines', 0,
        'message', 'Already posted (idempotent)'
      );
    END IF;
  END IF;
  
  -- Validate location exists in inventory
  SELECT * INTO v_location
  FROM inventory.locations
  WHERE id = v_receipt.location_id
    AND tenant_id = v_tenant_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Location % not found in inventory schema', v_receipt.location_id;
  END IF;
  
  -- Process each receipt line
  FOR v_line IN
    SELECT *
    FROM supply_chain.receipt_lines
    WHERE receipt_id = p_receipt_id
      AND tenant_id = v_tenant_id
    ORDER BY line_number
  LOOP
    -- Validate catalog item exists
    SELECT * INTO v_catalog_item
    FROM inventory.catalog_items
    WHERE id = v_line.catalog_item_id
      AND tenant_id = v_tenant_id;
    
    IF NOT FOUND THEN
      RAISE WARNING 'Catalog item % not found. Skipping line %.', v_line.catalog_item_id, v_line.line_number;
      v_skipped_count := v_skipped_count + 1;
      CONTINUE;
    END IF;
    
    -- Check if this line already posted (idempotency at line level)
    IF v_line.last_event_id IS NOT NULL THEN
      IF EXISTS (
        SELECT 1 FROM inventory.inventory_events
        WHERE tenant_id = v_tenant_id
          AND catalog_item_id = v_line.catalog_item_id
          AND location_id = v_receipt.location_id
          AND last_event_id = v_line.last_event_id
      ) THEN
        RAISE NOTICE 'Receipt line % already posted. Skipping.', v_line.line_number;
        v_skipped_count := v_skipped_count + 1;
        CONTINUE;
      END IF;
    END IF;
    
    -- Generate unique event_id for this line
    v_event_id := 'receipt-' || p_receipt_id::TEXT || '-line-' || v_line.line_number::TEXT || '-' || extract(epoch from now())::TEXT;
    
    -- 1. INSERT INVENTORY EVENT (ledger)
    INSERT INTO inventory.inventory_events (
      tenant_id,
      catalog_item_id,
      location_id,
      event_type,
      quantity_delta,
      payload,
      correlation_id,
      occurred_at,
      actor_user_id,
      last_event_id
    ) VALUES (
      v_tenant_id,
      v_line.catalog_item_id,
      v_receipt.location_id,
      'received',
      v_line.qty_received,
      jsonb_build_object(
        'receipt_id', p_receipt_id,
        'receipt_number', v_receipt.receipt_number,
        'receipt_line_id', v_line.id,
        'line_number', v_line.line_number,
        'po_id', v_receipt.po_id,
        'po_line_id', v_line.po_line_id
      ),
      p_receipt_id, -- correlation to group all lines
      v_receipt.received_at,
      COALESCE(p_actor_user_id, v_receipt.created_by_user_id),
      v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING;
    
    IF NOT FOUND THEN
      RAISE NOTICE 'Inventory event for line % already exists (idempotent). Skipping.', v_line.line_number;
      v_skipped_count := v_skipped_count + 1;
      CONTINUE;
    END IF;
    
    -- 2. INSERT STOCK MOVEMENT (authoritative ledger)
    INSERT INTO inventory.stock_movements (
      tenant_id,
      catalog_item_id,
      location_id,
      quantity_delta,
      movement_type,
      source_ref_type,
      source_ref_id,
      unit_cost,
      currency,
      notes,
      correlation_id,
      occurred_at,
      created_by_user_id,
      last_event_id
    ) VALUES (
      v_tenant_id,
      v_line.catalog_item_id,
      v_receipt.location_id,
      v_line.qty_received, -- POSITIVE (increase)
      'received',
      'receipt',
      p_receipt_id,
      NULL, -- unit_cost from PO if linked
      'USD',
      'Posted from receipt ' || v_receipt.receipt_number,
      p_receipt_id,
      v_receipt.received_at,
      COALESCE(p_actor_user_id, v_receipt.created_by_user_id),
      v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_movement_id;
    
    IF v_movement_id IS NULL THEN
      RAISE NOTICE 'Stock movement for line % already exists (idempotent). Skipping balance update.', v_line.line_number;
      v_skipped_count := v_skipped_count + 1;
      CONTINUE;
    END IF;
    
    -- 3. UPDATE STOCK BALANCES (read model)
    -- This is the ONLY place stock_balances should be updated for receipts
    INSERT INTO inventory.stock_balances (
      tenant_id,
      catalog_item_id,
      location_id,
      qty_on_hand,
      qty_reserved,
      qty_available,
      last_event_id
    ) VALUES (
      v_tenant_id,
      v_line.catalog_item_id,
      v_receipt.location_id,
      v_line.qty_received,
      0,
      v_line.qty_received,
      v_event_id
    )
    ON CONFLICT (tenant_id, catalog_item_id, location_id)
    DO UPDATE SET
      qty_on_hand = inventory.stock_balances.qty_on_hand + EXCLUDED.qty_on_hand,
      qty_available = inventory.stock_balances.qty_available + EXCLUDED.qty_available,
      last_event_id = EXCLUDED.last_event_id,
      updated_at = NOW();
    
    -- 4. UPDATE PO LINE STATUS (if linked)
    IF v_line.po_line_id IS NOT NULL THEN
      UPDATE supply_chain.purchase_order_lines
      SET
        qty_received = qty_received + v_line.qty_received,
        status = CASE
          WHEN qty_received + v_line.qty_received >= qty_ordered THEN 'received'
          WHEN qty_received + v_line.qty_received > 0 THEN 'partially_received'
          ELSE 'pending'
        END,
        updated_at = NOW()
      WHERE id = v_line.po_line_id
        AND tenant_id = v_tenant_id;
    END IF;
    
    v_posted_count := v_posted_count + 1;
    
    RAISE NOTICE '✓ Posted receipt line % to inventory: % x %',
      v_line.line_number, v_line.qty_received, v_catalog_item.name;
  END LOOP;
  
  -- 5. UPDATE PO HEADER STATUS (if linked)
  IF v_receipt.po_id IS NOT NULL THEN
    -- Check if all lines received
    UPDATE supply_chain.purchase_orders po
    SET status = (
      SELECT CASE
        WHEN COUNT(*) = COUNT(*) FILTER (WHERE pol.status = 'received') THEN 'received'
        WHEN COUNT(*) FILTER (WHERE pol.status IN ('received', 'partially_received')) > 0 THEN 'partially_received'
        ELSE 'in_transit'
      END
      FROM supply_chain.purchase_order_lines pol
      WHERE pol.po_id = po.id
        AND pol.tenant_id = po.tenant_id
    ),
    updated_at = NOW()
    WHERE id = v_receipt.po_id
      AND tenant_id = v_tenant_id;
  END IF;
  
  -- 6. MARK RECEIPT AS POSTED (update last_event_id)
  UPDATE supply_chain.receipts
  SET
    last_event_id = 'posted-' || p_receipt_id::TEXT || '-' || extract(epoch from now())::TEXT,
    updated_at = NOW()
  WHERE id = p_receipt_id
    AND tenant_id = v_tenant_id;
  
  -- Build result
  v_result := jsonb_build_object(
    'success', true,
    'receipt_id', p_receipt_id,
    'receipt_number', v_receipt.receipt_number,
    'posted_lines', v_posted_count,
    'skipped_lines', v_skipped_count,
    'location_id', v_receipt.location_id,
    'location_name', v_location.name,
    'received_at', v_receipt.received_at,
    'message', format('Posted %s lines to inventory, skipped %s', v_posted_count, v_skipped_count)
  );
  
  RAISE NOTICE '✅ Receipt % posted to inventory: % lines posted, % skipped',
    p_receipt_id, v_posted_count, v_skipped_count;
  
  RETURN v_result;
  
EXCEPTION
  WHEN OTHERS THEN
    RAISE EXCEPTION 'Failed to post receipt % to inventory: %', p_receipt_id, SQLERRM;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_post_receipt_to_inventory"("p_receipt_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_post_receipt_to_inventory"("p_receipt_id" "uuid", "p_actor_user_id" "uuid") IS 'ATOMIC BRIDGE: Posts receipt from supply_chain to inventory ledger.
This is the ONLY allowed way to post receipts to inventory.
Enforces idempotency via last_event_id on receipts, receipt_lines, inventory_events, and stock_movements.
Updates stock_balances (read model) and PO line status.
';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_post_receipt_to_inventory_v2"("p_receipt_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_receipt supply_chain.receipts%ROWTYPE;
  v_line supply_chain.receipt_lines%ROWTYPE;
  v_catalog_item inventory.catalog_items%ROWTYPE;
  v_location inventory.locations%ROWTYPE;
  v_event_id TEXT;
  v_movement_id UUID;
  v_posted_count INT := 0;
  v_skipped_count INT := 0;
  v_rejected_count INT := 0;
  v_damaged_count INT := 0;
  v_result JSONB;
  v_movement_type TEXT;
BEGIN
  -- Get tenant from JWT
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'No tenant_id in JWT. Authentication required.';
  END IF;
  
  -- Fetch receipt header
  SELECT * INTO v_receipt
  FROM supply_chain.receipts
  WHERE id = p_receipt_id
    AND tenant_id = v_tenant_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt % not found for tenant %', p_receipt_id, v_tenant_id;
  END IF;
  
  -- Check status
  IF v_receipt.status = 'cancelled' THEN
    RAISE EXCEPTION 'Cannot post cancelled receipt %', p_receipt_id;
  END IF;
  
  -- Check if already posted
  IF v_receipt.status = 'confirmed' AND EXISTS (
    SELECT 1 FROM inventory.stock_movements
    WHERE tenant_id = v_tenant_id
      AND source_ref_type = 'receipt'
      AND source_ref_id = p_receipt_id
  ) THEN
    RAISE NOTICE 'Receipt % already posted to inventory (idempotent). Skipping.', p_receipt_id;
    
    RETURN jsonb_build_object(
      'success', true,
      'receipt_id', p_receipt_id,
      'posted_lines', 0,
      'message', 'Already posted (idempotent)'
    );
  END IF;
  
  -- Validate location exists in inventory
  SELECT * INTO v_location
  FROM inventory.locations
  WHERE id = v_receipt.location_id
    AND tenant_id = v_tenant_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Location % not found in inventory schema', v_receipt.location_id;
  END IF;
  
  -- Process each receipt line
  FOR v_line IN
    SELECT *
    FROM supply_chain.receipt_lines
    WHERE receipt_id = p_receipt_id
      AND tenant_id = v_tenant_id
    ORDER BY line_number
  LOOP
    -- Validate catalog item exists
    SELECT * INTO v_catalog_item
    FROM inventory.catalog_items
    WHERE id = v_line.catalog_item_id
      AND tenant_id = v_tenant_id;
    
    IF NOT FOUND THEN
      RAISE WARNING 'Catalog item % not found. Skipping line %.', v_line.catalog_item_id, v_line.line_number;
      v_skipped_count := v_skipped_count + 1;
      CONTINUE;
    END IF;
    
    -- Generate unique event_id for this line
    v_event_id := 'receipt-' || p_receipt_id::TEXT || '-line-' || v_line.line_number::TEXT || '-post-' || extract(epoch from now())::TEXT;
    
    -- Handle based on condition_status
    CASE v_line.condition_status
      WHEN 'rejected' THEN
        -- Rejected items: Log event but DO NOT add to inventory
        INSERT INTO inventory.inventory_events (
          tenant_id,
          catalog_item_id,
          location_id,
          event_type,
          quantity_delta,
          payload,
          correlation_id,
          occurred_at,
          actor_user_id,
          last_event_id
        ) VALUES (
          v_tenant_id,
          v_line.catalog_item_id,
          COALESCE(v_line.destination_location_id, v_receipt.location_id),
          'rejected',
          0,  -- Zero delta (not added to inventory)
          jsonb_build_object(
            'receipt_id', p_receipt_id,
            'receipt_number', v_receipt.receipt_number,
            'receipt_line_id', v_line.id,
            'line_number', v_line.line_number,
            'qty_received', v_line.qty_received,
            'condition', 'rejected',
            'reason', 'Items rejected during receiving'
          ),
          p_receipt_id,
          v_receipt.received_at,
          COALESCE(p_actor_user_id, v_receipt.created_by_user_id),
          v_event_id
        )
        ON CONFLICT (tenant_id, last_event_id) DO NOTHING;
        
        v_rejected_count := v_rejected_count + 1;
        RAISE NOTICE '⚠ Rejected line %: % x % (not added to inventory)', 
          v_line.line_number, v_line.qty_received, v_catalog_item.name;
      
      WHEN 'damaged' THEN
        -- Damaged items: Add to inventory but flag as damaged
        v_damaged_count := v_damaged_count + 1;
        v_movement_type := 'damaged';
        
        -- Continue to post below
      
      WHEN 'quarantine' THEN
        -- Quarantine items: Add to inventory but flag
        v_movement_type := 'received';
        
        -- Future: Could route to quarantine location
        -- For now, just add to inventory with event flag
      
      ELSE  -- 'accepted' or NULL
        v_movement_type := 'received';
    END CASE;
    
    -- Skip further processing for rejected items
    IF v_line.condition_status = 'rejected' THEN
      CONTINUE;
    END IF;
    
    -- 1. INSERT INVENTORY EVENT (ledger)
    INSERT INTO inventory.inventory_events (
      tenant_id,
      catalog_item_id,
      location_id,
      event_type,
      quantity_delta,
      payload,
      correlation_id,
      occurred_at,
      actor_user_id,
      last_event_id
    ) VALUES (
      v_tenant_id,
      v_line.catalog_item_id,
      COALESCE(v_line.destination_location_id, v_receipt.location_id),
      v_movement_type,
      v_line.qty_received,
      jsonb_build_object(
        'receipt_id', p_receipt_id,
        'receipt_number', v_receipt.receipt_number,
        'receipt_line_id', v_line.id,
        'line_number', v_line.line_number,
        'po_id', v_receipt.po_id,
        'po_line_id', v_line.po_line_id,
        'condition_status', v_line.condition_status,
        'unit_cost_actual', v_line.unit_cost_actual
      ),
      p_receipt_id,
      v_receipt.received_at,
      COALESCE(p_actor_user_id, v_receipt.created_by_user_id),
      v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING;
    
    -- 2. INSERT STOCK MOVEMENT (authoritative ledger)
    INSERT INTO inventory.stock_movements (
      tenant_id,
      catalog_item_id,
      location_id,
      quantity_delta,
      movement_type,
      source_ref_type,
      source_ref_id,
      unit_cost,
      currency,
      notes,
      correlation_id,
      occurred_at,
      created_by_user_id,
      last_event_id
    ) VALUES (
      v_tenant_id,
      v_line.catalog_item_id,
      COALESCE(v_line.destination_location_id, v_receipt.location_id),
      v_line.qty_received,  -- POSITIVE (increase)
      v_movement_type,
      'receipt',
      p_receipt_id,
      COALESCE(v_line.unit_cost_actual, (
        SELECT unit_cost FROM supply_chain.purchase_order_lines 
        WHERE id = v_line.po_line_id
      )),
      'USD',
      CASE 
        WHEN v_line.condition_status = 'damaged' THEN 'Received as DAMAGED - ' || COALESCE(v_line.notes, '')
        WHEN v_line.condition_status = 'quarantine' THEN 'Received in QUARANTINE - ' || COALESCE(v_line.notes, '')
        ELSE 'Posted from receipt ' || v_receipt.receipt_number
      END,
      p_receipt_id,
      v_receipt.received_at,
      COALESCE(p_actor_user_id, v_receipt.created_by_user_id),
      v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_movement_id;
    
    IF v_movement_id IS NULL THEN
      RAISE NOTICE 'Stock movement for line % already exists (idempotent). Skipping.', v_line.line_number;
      v_skipped_count := v_skipped_count + 1;
      CONTINUE;
    END IF;
    
    -- 3. Stock balances updated automatically via trigger (maintain_stock_balances)
    
    -- 4. UPDATE PO LINE STATUS (if linked) - only for accepted/damaged/quarantine
    IF v_line.po_line_id IS NOT NULL THEN
      UPDATE supply_chain.purchase_order_lines
      SET
        qty_received = qty_received + v_line.qty_received,
        status = CASE
          WHEN qty_received + v_line.qty_received >= qty_ordered THEN 'fully_received'
          WHEN qty_received + v_line.qty_received > 0 THEN 'partially_received'
          ELSE status
        END,
        updated_at = NOW(),
        updated_by = COALESCE(p_actor_user_id, v_receipt.created_by_user_id)
      WHERE id = v_line.po_line_id
        AND tenant_id = v_tenant_id;
    END IF;
    
    v_posted_count := v_posted_count + 1;
    
    RAISE NOTICE '✓ Posted receipt line %: % x % (condition: %)',
      v_line.line_number, v_line.qty_received, v_catalog_item.name, v_line.condition_status;
  END LOOP;
  
  -- 5. UPDATE PO HEADER STATUS (if linked)
  IF v_receipt.po_id IS NOT NULL THEN
    UPDATE supply_chain.purchase_orders po
    SET status = (
      SELECT CASE
        WHEN COUNT(*) = COUNT(*) FILTER (WHERE pol.status = 'fully_received') THEN 'fully_received'
        WHEN COUNT(*) FILTER (WHERE pol.status IN ('fully_received', 'partially_received')) > 0 THEN 'partially_received'
        ELSE status
      END
      FROM supply_chain.purchase_order_lines pol
      WHERE pol.po_id = po.id
        AND pol.tenant_id = po.tenant_id
    ),
    updated_at = NOW(),
    updated_by = COALESCE(p_actor_user_id, v_receipt.created_by_user_id)
    WHERE id = v_receipt.po_id
      AND tenant_id = v_tenant_id;
  END IF;
  
  -- 6. UPDATE RECEIPT STATUS to 'confirmed'
  UPDATE supply_chain.receipts
  SET
    status = 'confirmed',
    updated_at = NOW(),
    updated_by = COALESCE(p_actor_user_id, v_receipt.created_by_user_id)
  WHERE id = p_receipt_id
    AND tenant_id = v_tenant_id;
  
  -- Build result
  v_result := jsonb_build_object(
    'success', true,
    'receipt_id', p_receipt_id,
    'receipt_number', v_receipt.receipt_number,
    'posted_lines', v_posted_count,
    'rejected_lines', v_rejected_count,
    'damaged_lines', v_damaged_count,
    'skipped_lines', v_skipped_count,
    'location_id', v_receipt.location_id,
    'location_name', v_location.name,
    'received_at', v_receipt.received_at,
    'message', format('Posted %s lines, rejected %s, damaged %s, skipped %s', 
      v_posted_count, v_rejected_count, v_damaged_count, v_skipped_count)
  );
  
  RAISE NOTICE '✅ Receipt % posted to inventory: % posted, % rejected, % damaged',
    p_receipt_id, v_posted_count, v_rejected_count, v_damaged_count;
  
  RETURN v_result;
  
EXCEPTION
  WHEN OTHERS THEN
    RAISE EXCEPTION 'Failed to post receipt % to inventory: %', p_receipt_id, SQLERRM;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_post_receipt_to_inventory_v2"("p_receipt_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_post_receipt_to_inventory_v2"("p_receipt_id" "uuid", "p_actor_user_id" "uuid") IS 'Enhanced atomic receipt posting with support for condition_status and destination_location_id.
  Handles: accepted (normal), damaged (flagged), quarantine (flagged), rejected (not added to inventory).
  Updates receipt status to confirmed upon successful posting.';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_reverse_receipt_from_inventory"("p_receipt_id" "uuid", "p_reason" "text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_receipt supply_chain.receipts%ROWTYPE;
  v_line supply_chain.receipt_lines%ROWTYPE;
  v_event_id TEXT;
  v_reversed_count INT := 0;
  v_result JSONB;
BEGIN
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'No tenant_id in JWT. Authentication required.';
  END IF;
  
  -- Validate reason provided
  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason required for reversal';
  END IF;
  
  -- Fetch receipt
  SELECT * INTO v_receipt
  FROM supply_chain.receipts
  WHERE id = p_receipt_id
    AND tenant_id = v_tenant_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt % not found', p_receipt_id;
  END IF;
  
  -- Check if receipt was posted
  IF v_receipt.last_event_id IS NULL THEN
    RAISE EXCEPTION 'Receipt % was never posted to inventory', p_receipt_id;
  END IF;
  
  -- Process each receipt line (reverse)
  FOR v_line IN
    SELECT *
    FROM supply_chain.receipt_lines
    WHERE receipt_id = p_receipt_id
      AND tenant_id = v_tenant_id
    ORDER BY line_number
  LOOP
    v_event_id := 'reversal-' || p_receipt_id::TEXT || '-line-' || v_line.line_number::TEXT || '-' || extract(epoch from now())::TEXT;
    
    -- Insert negative inventory event
    INSERT INTO inventory.inventory_events (
      tenant_id,
      catalog_item_id,
      location_id,
      event_type,
      quantity_delta,
      payload,
      correlation_id,
      occurred_at,
      actor_user_id,
      last_event_id
    ) VALUES (
      v_tenant_id,
      v_line.catalog_item_id,
      v_receipt.location_id,
      'adjusted', -- reversal is an adjustment
      -v_line.qty_received, -- NEGATIVE
      jsonb_build_object(
        'reason', 'receipt_reversal',
        'original_receipt_id', p_receipt_id,
        'original_receipt_number', v_receipt.receipt_number,
        'reversal_reason', p_reason
      ),
      p_receipt_id,
      NOW(),
      p_actor_user_id,
      v_event_id
    );
    
    -- Insert negative stock movement
    INSERT INTO inventory.stock_movements (
      tenant_id,
      catalog_item_id,
      location_id,
      quantity_delta,
      movement_type,
      source_ref_type,
      source_ref_id,
      reason,
      notes,
      correlation_id,
      occurred_at,
      created_by_user_id,
      last_event_id
    ) VALUES (
      v_tenant_id,
      v_line.catalog_item_id,
      v_receipt.location_id,
      -v_line.qty_received, -- NEGATIVE
      'adjusted',
      'receipt_reversal',
      p_receipt_id,
      'receipt_reversal',
      'Reversed receipt ' || v_receipt.receipt_number || ': ' || p_reason,
      p_receipt_id,
      NOW(),
      p_actor_user_id,
      v_event_id
    );
    
    -- Update stock balances
    UPDATE inventory.stock_balances
    SET
      qty_on_hand = qty_on_hand - v_line.qty_received,
      qty_available = qty_available - v_line.qty_received,
      last_event_id = v_event_id,
      updated_at = NOW()
    WHERE tenant_id = v_tenant_id
      AND catalog_item_id = v_line.catalog_item_id
      AND location_id = v_receipt.location_id;
    
    -- Reverse PO line status
    IF v_line.po_line_id IS NOT NULL THEN
      UPDATE supply_chain.purchase_order_lines
      SET
        qty_received = GREATEST(0, qty_received - v_line.qty_received),
        status = CASE
          WHEN qty_received - v_line.qty_received >= qty_ordered THEN 'received'
          WHEN qty_received - v_line.qty_received > 0 THEN 'partially_received'
          ELSE 'pending'
        END,
        updated_at = NOW()
      WHERE id = v_line.po_line_id
        AND tenant_id = v_tenant_id;
    END IF;
    
    v_reversed_count := v_reversed_count + 1;
  END LOOP;
  
  -- Mark receipt as reversed
  UPDATE supply_chain.receipts
  SET
    last_event_id = NULL, -- Allow re-posting if needed
    notes = COALESCE(notes, '') || E'\n[REVERSED: ' || p_reason || ']',
    updated_at = NOW()
  WHERE id = p_receipt_id
    AND tenant_id = v_tenant_id;
  
  v_result := jsonb_build_object(
    'success', true,
    'receipt_id', p_receipt_id,
    'receipt_number', v_receipt.receipt_number,
    'reversed_lines', v_reversed_count,
    'reason', p_reason,
    'message', format('Reversed %s lines from inventory', v_reversed_count)
  );
  
  RAISE NOTICE '✅ Receipt % reversed from inventory: % lines', p_receipt_id, v_reversed_count;
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_reverse_receipt_from_inventory"("p_receipt_id" "uuid", "p_reason" "text", "p_actor_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_reverse_receipt_from_inventory"("p_receipt_id" "uuid", "p_reason" "text", "p_actor_user_id" "uuid") IS 'Reverses a receipt posting from inventory (creates negative movements).
Use only for corrections. Requires reason.';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_send_po_email"("p_po_id" "uuid", "p_recipient_email" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_user_id UUID;
    v_po RECORD;
    v_vendor RECORD;
    v_event_id UUID;
    v_result JSONB;
BEGIN
    -- Get tenant and user from auth context
    v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
    v_user_id := (auth.jwt() ->> 'user_id')::UUID;
    
    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required - no tenant_id in JWT';
    END IF;
    
    -- Get PO and vendor
    SELECT po.* INTO v_po
    FROM supply_chain.purchase_orders po
    WHERE po.id = p_po_id
        AND po.tenant_id = v_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Purchase order not found';
    END IF;
    
    SELECT v.* INTO v_vendor
    FROM supply_chain.vendors v
    WHERE v.id = v_po.vendor_id;
    
    -- Determine recipient
    IF p_recipient_email IS NULL THEN
        p_recipient_email := COALESCE(v_vendor.po_email, v_vendor.contact_email);
    END IF;
    
    IF p_recipient_email IS NULL THEN
        RAISE EXCEPTION 'No email address available for vendor';
    END IF;
    
    -- Generate event ID
    v_event_id := gen_random_uuid();
    
    -- Update PO sent tracking
    UPDATE supply_chain.purchase_orders
    SET 
        sent_at = NOW(),
        sent_by_user_id = v_user_id,
        updated_at = NOW()
    WHERE id = p_po_id;
    
    -- Emit event (this would trigger email service)
    PERFORM inventory.publish_event(
        p_tenant_id := v_tenant_id,
        p_scope := 'supply_chain',
        p_event_name := 'purchase_order.sent',
        p_aggregate_type := 'purchase_order',
        p_aggregate_id := p_po_id,
        p_payload := jsonb_build_object(
            'po_id', p_po_id,
            'po_number', v_po.po_number,
            'recipient_email', p_recipient_email,
            'vendor_id', v_po.vendor_id,
            'vendor_name', v_vendor.name,
            'requires_po_in_subject', v_vendor.requires_po_in_subject
        ),
        p_event_version := 1,
        p_metadata := jsonb_build_object(
            'sent_by', v_user_id,
            'source', 'rpc_send_po_email'
        )
    );
    
    -- Build result
    v_result := jsonb_build_object(
        'success', true,
        'po_id', p_po_id,
        'po_number', v_po.po_number,
        'recipient_email', p_recipient_email,
        'sent_at', NOW(),
        'event_id', v_event_id
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_send_po_email"("p_po_id" "uuid", "p_recipient_email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_send_po_email"("p_po_id" "uuid", "p_recipient_email" "text") IS 'Send PO via email to vendor. 
Note: This is OPTIONAL and separate from order placement. 
Many vendors (portal-based) never receive the PO via email.';



CREATE OR REPLACE FUNCTION "supply_chain"."rpc_update_tenant_settings"("p_updates" "jsonb") RETURNS "supply_chain"."tenant_settings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_user_id UUID;
  v_role TEXT;
  v_settings supply_chain.tenant_settings;
BEGIN
  v_tenant_id := public.current_tenant_id();
  v_user_id := (auth.jwt() ->> 'user_id')::UUID;
  v_role := auth.jwt() -> 'app_metadata' ->> 'role';

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required - no tenant_id in JWT';
  END IF;

  IF v_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Admin role required to update tenant settings';
  END IF;

  SELECT * INTO v_settings
  FROM supply_chain.tenant_settings
  WHERE tenant_id = v_tenant_id;

  IF NOT FOUND THEN
    v_settings := supply_chain.get_or_create_tenant_settings(v_tenant_id);
  END IF;

  UPDATE supply_chain.tenant_settings
  SET
    po_number_format = COALESCE(p_updates->>'po_number_format', po_number_format),
    po_number_prefix = COALESCE(p_updates->>'po_number_prefix', po_number_prefix),
    auto_approve_enabled = COALESCE((p_updates->>'auto_approve_enabled')::BOOLEAN, auto_approve_enabled),
    auto_approve_limit = COALESCE((p_updates->>'auto_approve_limit')::NUMERIC, auto_approve_limit),
    cycle_count_number_format = COALESCE(p_updates->>'cycle_count_number_format', cycle_count_number_format),
    cycle_count_number_prefix = COALESCE(p_updates->>'cycle_count_number_prefix', cycle_count_number_prefix),
    vendor_auto_approve_limits = COALESCE((p_updates->'vendor_auto_approve_limits')::JSONB, vendor_auto_approve_limits),
    vendor_code_strategy = COALESCE(p_updates->>'vendor_code_strategy', vendor_code_strategy),
    vendor_code_required = COALESCE((p_updates->>'vendor_code_required')::BOOLEAN, vendor_code_required),
    vendor_code_case = COALESCE(p_updates->>'vendor_code_case', vendor_code_case),
    vendor_code_min_length = COALESCE((p_updates->>'vendor_code_min_length')::INTEGER, vendor_code_min_length),
    vendor_code_max_length = COALESCE((p_updates->>'vendor_code_max_length')::INTEGER, vendor_code_max_length),
    vendor_code_prefix = COALESCE(p_updates->>'vendor_code_prefix', vendor_code_prefix),
    vendor_code_suffix = COALESCE(p_updates->>'vendor_code_suffix', vendor_code_suffix),
    vendor_code_allowed_chars = COALESCE(p_updates->>'vendor_code_allowed_chars', vendor_code_allowed_chars),
    vendor_code_regex = COALESCE(p_updates->>'vendor_code_regex', vendor_code_regex),
    vendor_code_user_editable = COALESCE((p_updates->>'vendor_code_user_editable')::BOOLEAN, vendor_code_user_editable),
    vendor_code_immutable_after_use = COALESCE((p_updates->>'vendor_code_immutable_after_use')::BOOLEAN, vendor_code_immutable_after_use),
    vendor_code_sequence_padding = COALESCE((p_updates->>'vendor_code_sequence_padding')::INTEGER, vendor_code_sequence_padding),
    updated_at = NOW(),
    updated_by = v_user_id
  WHERE tenant_id = v_tenant_id
  RETURNING * INTO v_settings;

  RETURN v_settings;
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_update_tenant_settings"("p_updates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."rpc_validate_receipt"("p_receipt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_receipt supply_chain.receipts%ROWTYPE;
  v_errors TEXT[] := ARRAY[]::TEXT[];
  v_warnings TEXT[] := ARRAY[]::TEXT[];
  v_line_count INT;
  v_over_delivery_count INT;
BEGIN
  -- Get tenant from JWT
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Fetch receipt
  SELECT * INTO v_receipt
  FROM supply_chain.receipts
  WHERE id = p_receipt_id
    AND tenant_id = v_tenant_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'valid', false,
      'errors', jsonb_build_array('Receipt not found')
    );
  END IF;
  
  -- Check if already confirmed
  IF v_receipt.status = 'confirmed' THEN
    v_warnings := array_append(v_warnings, 'Receipt already confirmed');
  END IF;
  
  IF v_receipt.status = 'cancelled' THEN
    v_errors := array_append(v_errors, 'Cannot post cancelled receipt');
  END IF;
  
  -- Check if location exists
  IF NOT EXISTS (
    SELECT 1 FROM inventory.locations 
    WHERE id = v_receipt.location_id AND tenant_id = v_tenant_id
  ) THEN
    v_errors := array_append(v_errors, 'Receipt location not found in inventory');
  END IF;
  
  -- Check lines exist
  SELECT COUNT(*) INTO v_line_count
  FROM supply_chain.receipt_lines
  WHERE receipt_id = p_receipt_id AND tenant_id = v_tenant_id;
  
  IF v_line_count = 0 THEN
    v_errors := array_append(v_errors, 'Receipt has no lines');
  END IF;
  
  -- Check for catalog items that don't exist
  IF EXISTS (
    SELECT 1 
    FROM supply_chain.receipt_lines rl
    WHERE rl.receipt_id = p_receipt_id 
      AND rl.tenant_id = v_tenant_id
      AND NOT EXISTS (
        SELECT 1 FROM inventory.catalog_items ci 
        WHERE ci.id = rl.catalog_item_id AND ci.tenant_id = v_tenant_id
      )
  ) THEN
    v_errors := array_append(v_errors, 'One or more catalog items not found');
  END IF;
  
  -- Check for over-deliveries (warnings, not errors)
  IF v_receipt.po_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_over_delivery_count
    FROM supply_chain.receipt_lines rl
    JOIN supply_chain.purchase_order_lines pol ON pol.id = rl.po_line_id
    WHERE rl.receipt_id = p_receipt_id
      AND rl.tenant_id = v_tenant_id
      AND pol.allow_over_delivery = false
      AND (pol.qty_received + rl.qty_received) > pol.qty_ordered;
    
    IF v_over_delivery_count > 0 THEN
      v_warnings := array_append(v_warnings, 
        format('%s line(s) would exceed ordered quantity', v_over_delivery_count));
    END IF;
  END IF;
  
  -- Return validation result
  RETURN jsonb_build_object(
    'valid', array_length(v_errors, 1) IS NULL,
    'errors', to_jsonb(v_errors),
    'warnings', to_jsonb(v_warnings),
    'receipt_id', p_receipt_id,
    'status', v_receipt.status,
    'line_count', v_line_count
  );
END;
$$;


ALTER FUNCTION "supply_chain"."rpc_validate_receipt"("p_receipt_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."rpc_validate_receipt"("p_receipt_id" "uuid") IS 'Validates receipt before posting. Returns {valid, errors[], warnings[]}';



CREATE OR REPLACE FUNCTION "supply_chain"."set_purchase_order_vendor_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'public'
    AS $$
DECLARE
  v_name TEXT;
  v_code TEXT;
BEGIN
  IF NEW.vendor_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT name, code INTO v_name, v_code
  FROM supply_chain.vendors
  WHERE id = NEW.vendor_id AND tenant_id = NEW.tenant_id;

  NEW.vendor_name_snapshot := COALESCE(NEW.vendor_name_snapshot, v_name);
  NEW.vendor_code_snapshot := COALESCE(NEW.vendor_code_snapshot, v_code);

  RETURN NEW;
END;
$$;


ALTER FUNCTION "supply_chain"."set_purchase_order_vendor_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."set_receipt_vendor_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'supply_chain', 'public'
    AS $$
DECLARE
  v_vendor_id UUID;
  v_name TEXT;
  v_code TEXT;
BEGIN
  IF NEW.vendor_id IS NOT NULL THEN
    v_vendor_id := NEW.vendor_id;
  ELSIF NEW.po_id IS NOT NULL THEN
    SELECT vendor_id, vendor_name_snapshot, vendor_code_snapshot
    INTO v_vendor_id, v_name, v_code
    FROM supply_chain.purchase_orders
    WHERE id = NEW.po_id AND tenant_id = NEW.tenant_id;

    NEW.vendor_name_snapshot := COALESCE(NEW.vendor_name_snapshot, v_name);
    NEW.vendor_code_snapshot := COALESCE(NEW.vendor_code_snapshot, v_code);
  END IF;

  IF v_vendor_id IS NOT NULL THEN
    SELECT name, code INTO v_name, v_code
    FROM supply_chain.vendors
    WHERE id = v_vendor_id AND tenant_id = NEW.tenant_id;

    NEW.vendor_name_snapshot := COALESCE(NEW.vendor_name_snapshot, v_name);
    NEW.vendor_code_snapshot := COALESCE(NEW.vendor_code_snapshot, v_code);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "supply_chain"."set_receipt_vendor_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."update_po_line_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.qty_received = 0 THEN
        NEW.status := 'pending';
    ELSIF NEW.qty_received >= NEW.qty_ordered THEN
        NEW.status := 'received';
    ELSE
        NEW.status := 'partially_received';
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "supply_chain"."update_po_line_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."update_po_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_all_received BOOLEAN;
    v_any_received BOOLEAN;
BEGIN
    -- Check if all lines are received
    SELECT 
        BOOL_AND(status = 'received'),
        BOOL_OR(status IN ('received', 'partially_received'))
    INTO v_all_received, v_any_received
    FROM inventory.purchase_order_lines
    WHERE po_id = COALESCE(NEW.po_id, OLD.po_id);
    
    -- Update PO status
    UPDATE inventory.purchase_orders
    SET status = CASE
        WHEN v_all_received THEN 'received'
        WHEN v_any_received THEN 'partially_received'
        ELSE status
    END
    WHERE id = COALESCE(NEW.po_id, OLD.po_id);
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "supply_chain"."update_po_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."update_po_status_from_lines"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_po_id UUID;
    v_line_stats RECORD;
BEGIN
    -- Get the PO ID (works for INSERT, UPDATE, DELETE)
    v_po_id := COALESCE(NEW.po_id, OLD.po_id);
    
    -- Calculate line statistics
    SELECT
        COUNT(*) AS total_lines,
        COUNT(*) FILTER (WHERE status = 'fully_received') AS fully_received_count,
        COUNT(*) FILTER (WHERE status IN ('open', 'partially_received')) AS open_count,
        COUNT(*) FILTER (WHERE status = 'cancelled') AS cancelled_count,
        SUM(qty_ordered) AS total_ordered,
        SUM(qty_received) AS total_received
    INTO v_line_stats
    FROM supply_chain.purchase_order_lines
    WHERE po_id = v_po_id;
    
    -- Update PO status based on line statuses
    IF v_line_stats.fully_received_count = v_line_stats.total_lines AND v_line_stats.total_lines > 0 THEN
        -- All lines fully received
        UPDATE supply_chain.purchase_orders
        SET status = 'fully_received', updated_at = NOW()
        WHERE id = v_po_id AND status NOT IN ('closed', 'cancelled');
        
    ELSIF v_line_stats.total_received > 0 THEN
        -- Some quantity received
        UPDATE supply_chain.purchase_orders
        SET status = 'partially_received', updated_at = NOW()
        WHERE id = v_po_id AND status NOT IN ('fully_received', 'closed', 'cancelled');
    END IF;
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "supply_chain"."update_po_status_from_lines"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "supply_chain"."validate_po_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Allow any transition from draft
    IF OLD.status = 'draft' THEN
        RETURN NEW;
    END IF;
    
    -- Prevent invalid transitions
    IF OLD.status = 'cancelled' AND NEW.status != 'cancelled' THEN
        RAISE EXCEPTION 'Cannot change status of cancelled PO';
    END IF;
    
    IF OLD.status = 'closed' AND NEW.status != 'closed' THEN
        RAISE EXCEPTION 'Cannot change status of closed PO';
    END IF;
    
    -- Prevent going backwards in workflow (except cancellation)
    IF NEW.status = 'draft' AND OLD.status != 'draft' THEN
        RAISE EXCEPTION 'Cannot return PO to draft status';
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "supply_chain"."validate_po_status_transition"() OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."validate_po_status_transition"() IS 'Enforces valid state machine transitions for purchase orders. Prevents illegal status jumps.';



