CREATE TABLE IF NOT EXISTS "inventory"."cycle_count_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "cycle_count_id" "uuid" NOT NULL,
    "line_number" integer NOT NULL,
    "catalog_item_id" "uuid" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "qty_expected" numeric(18,4),
    "qty_counted" numeric(18,4),
    "variance" numeric(18,4) GENERATED ALWAYS AS ((COALESCE("qty_counted", (0)::numeric) - COALESCE("qty_expected", (0)::numeric))) STORED,
    "variance_pct" numeric(10,2),
    "counted_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "last_event_id" "text" NOT NULL,
    "variance_qty" numeric,
    "requires_approval" boolean DEFAULT false,
    "auto_approved" boolean DEFAULT false,
    "counted_by_user_id" "uuid",
    "recount_pass" integer DEFAULT 1,
    "variance_reason_code" "text",
    "photo_urls" "text"[],
    "posted_at" timestamp with time zone,
    "adjustment_movement_id" "uuid",
    "decision_status" "inventory"."variance_decision_status" DEFAULT 'pending'::"inventory"."variance_decision_status",
    "decision_reason" "text",
    "decision_notes" "text",
    "decided_by_user_id" "uuid",
    "decided_at" timestamp with time zone
);


ALTER TABLE "inventory"."cycle_count_lines" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."cycle_count_lines" IS 'Individual items counted during cycle counts';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."variance" IS 'Computed as qty_counted - qty_expected';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."variance_pct" IS 'Variance as percentage of expected qty';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."last_event_id" IS 'Idempotency key for count line submission';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."variance_qty" IS 'Difference between counted and expected qty';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."requires_approval" IS 'True if variance exceeds threshold';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."counted_by_user_id" IS 'User who counted this specific line';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."recount_pass" IS 'Counting pass number (1=first count, 2=recount, etc.)';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."variance_reason_code" IS 'Reason code for variance (damaged, missing, theft, data_error, etc.)';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."photo_urls" IS 'Array of photo URLs for documentation (damage, issues, etc.)';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."posted_at" IS 'When adjustment for this line was posted';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."adjustment_movement_id" IS 'Link to the stock_movement created when variance was accepted and posted';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."decision_status" IS 'Decision status for variance: pending (default), accepted (adjust stock), rejected (invalid count), investigating (needs follow-up)';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."decision_reason" IS 'Reason code: usage_not_recorded, transfer_not_recorded, loss_theft, damage_disposal, counting_error, receiving_error, bulk_drift, unknown';



COMMENT ON COLUMN "inventory"."cycle_count_lines"."decision_notes" IS 'Free-form notes explaining the variance decision';



