CREATE TABLE IF NOT EXISTS "inventory"."cycle_counts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "count_number" "text" NOT NULL,
    "location_id" "uuid",
    "scheduled_for" "date" NOT NULL,
    "status" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "counted_by_user_id" "uuid",
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "last_event_id" "text" NOT NULL,
    "auto_approved" boolean DEFAULT false,
    "approval_required" boolean DEFAULT false,
    "approved_by_user_id" "uuid",
    "approved_at" timestamp with time zone,
    "approval_notes" "text",
    "snapshot_at" timestamp with time zone,
    "count_type" "text" DEFAULT 'full'::"text",
    "is_blind" boolean DEFAULT false,
    "scope_path" "text",
    "config_snapshot" "jsonb",
    "posted_at" timestamp with time zone,
    "needs_reconcile" boolean DEFAULT false,
    "movements_since_snapshot" integer DEFAULT 0,
    CONSTRAINT "cycle_counts_count_type_check" CHECK (("count_type" = ANY (ARRAY['full'::"text", 'partial'::"text"]))),
    CONSTRAINT "cycle_counts_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'scheduled'::"text", 'in_progress'::"text", 'under_review'::"text", 'approved'::"text", 'posted'::"text", 'closed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "inventory"."cycle_counts" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."cycle_counts" IS 'Cycle count variance application should use SERIALIZABLE isolation';



COMMENT ON COLUMN "inventory"."cycle_counts"."last_event_id" IS 'Idempotency key for cycle count creation';



COMMENT ON COLUMN "inventory"."cycle_counts"."auto_approved" IS 'True if all lines auto-approved (under threshold)';



COMMENT ON COLUMN "inventory"."cycle_counts"."approval_required" IS 'True if any line exceeds approval threshold';



COMMENT ON COLUMN "inventory"."cycle_counts"."snapshot_at" IS 'Timestamp when expected state was captured (when count started)';



COMMENT ON COLUMN "inventory"."cycle_counts"."count_type" IS 'Type of count: full (all items in scope) or partial (selected items)';



COMMENT ON COLUMN "inventory"."cycle_counts"."is_blind" IS 'Whether counters can see expected quantities (blind=true means hidden)';



COMMENT ON COLUMN "inventory"."cycle_counts"."scope_path" IS 'Optional sub-location path for narrower scope (e.g., zone/bin)';



COMMENT ON COLUMN "inventory"."cycle_counts"."config_snapshot" IS 'Snapshot of thresholds and approval rules at time of count';



COMMENT ON COLUMN "inventory"."cycle_counts"."posted_at" IS 'When adjustments were posted to inventory (idempotency marker)';



COMMENT ON COLUMN "inventory"."cycle_counts"."needs_reconcile" IS 'Flag indicating movements occurred after snapshot requiring review';



COMMENT ON COLUMN "inventory"."cycle_counts"."movements_since_snapshot" IS 'Count of stock movements in scope after snapshot_at';



