CREATE TABLE IF NOT EXISTS "inventory"."events_outbox" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "scope" "text" DEFAULT 'tenant'::"text" NOT NULL,
    "event_type" "text" NOT NULL,
    "aggregate_type" "text" NOT NULL,
    "aggregate_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "actor_user_id" "uuid",
    "payload" "jsonb" NOT NULL,
    "metadata" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "published_at" timestamp with time zone,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "retry_count" integer DEFAULT 0 NOT NULL,
    "last_error" "text",
    "event_name" "text",
    "event_version" integer DEFAULT 1,
    "next_attempt_at" timestamp with time zone DEFAULT "now"(),
    "locked_at" timestamp with time zone,
    "locked_by" "text",
    "last_attempt_at" timestamp with time zone,
    "last_retry_at" timestamp with time zone,
    "error_message" "text",
    "max_retries" integer DEFAULT 5,
    "trace_id" "uuid" DEFAULT "gen_random_uuid"(),
    "correlation_id" "uuid",
    CONSTRAINT "events_outbox_scope_check" CHECK (("scope" = ANY (ARRAY['tenant'::"text", 'profile'::"text", 'global'::"text"]))),
    CONSTRAINT "events_outbox_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'published'::"text", 'failed'::"text", 'dead'::"text"])))
);


ALTER TABLE "inventory"."events_outbox" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."events_outbox" IS 'Outbox pattern for reliable event publishing. Polled by events-poller Edge Function every minute.';



COMMENT ON COLUMN "inventory"."events_outbox"."scope" IS 'Event scope: tenant (tenant-wide), profile (user-specific), global (system-wide)';



COMMENT ON COLUMN "inventory"."events_outbox"."aggregate_type" IS 'Type of aggregate that emitted the event';



COMMENT ON COLUMN "inventory"."events_outbox"."aggregate_id" IS 'ID of the aggregate instance';



COMMENT ON COLUMN "inventory"."events_outbox"."published_at" IS 'Timestamp when event was successfully published to downstream systems.';



COMMENT ON COLUMN "inventory"."events_outbox"."retry_count" IS 'Number of times delivery has been attempted';



COMMENT ON COLUMN "inventory"."events_outbox"."last_error" IS 'Error message from most recent failed publish attempt.';



COMMENT ON COLUMN "inventory"."events_outbox"."event_name" IS 'References event_definitions.event_name';



COMMENT ON COLUMN "inventory"."events_outbox"."event_version" IS 'References event_definitions.version';



COMMENT ON COLUMN "inventory"."events_outbox"."next_attempt_at" IS 'When this event should be attempted next (for retry backoff)';



COMMENT ON COLUMN "inventory"."events_outbox"."locked_at" IS 'When this event was locked by a poller (for concurrent safety)';



COMMENT ON COLUMN "inventory"."events_outbox"."locked_by" IS 'Identifier of the poller that locked this event (hostname or worker ID)';



COMMENT ON COLUMN "inventory"."events_outbox"."last_attempt_at" IS 'Timestamp of most recent delivery attempt';



COMMENT ON COLUMN "inventory"."events_outbox"."last_retry_at" IS 'Timestamp of most recent delivery attempt';



COMMENT ON COLUMN "inventory"."events_outbox"."error_message" IS 'Error from last failed delivery attempt';



COMMENT ON COLUMN "inventory"."events_outbox"."max_retries" IS 'Maximum retry attempts before moving to dead letter queue';



