COMMENT ON COLUMN "inventory"."location_types"."code" IS 'Unique code within tenant (e.g., yard, warehouse)';



COMMENT ON COLUMN "inventory"."location_types"."name" IS 'Display name for the location type';



CREATE TABLE IF NOT EXISTS "inventory"."locations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "parent_location_id" "uuid",
    "external_ref" "jsonb",
    "active" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "address" "text",
    "location_type_id" "uuid" NOT NULL,
    "last_event_id" "text" NOT NULL
);


ALTER TABLE "inventory"."locations" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."locations" IS 'Storage locations for inventory items. Uses location_type_id to reference location_types table.';



COMMENT ON COLUMN "inventory"."locations"."address" IS 'Physical address or location description';



COMMENT ON COLUMN "inventory"."locations"."location_type_id" IS 'Reference to tenant-specific location type definition';



CREATE MATERIALIZED VIEW "inventory"."mv_asset_utilization" AS
 SELECT "a"."tenant_id",
    "a"."status",
    "ci"."name" AS "asset_type",
    "count"(*) AS "asset_count",
    "count"(*) FILTER (WHERE (("aa"."id" IS NOT NULL) AND ("aa"."returned_at" IS NULL))) AS "currently_assigned",
    "now"() AS "refreshed_at"
   FROM (("inventory"."assets" "a"
     LEFT JOIN "inventory"."catalog_items" "ci" ON (("ci"."id" = "a"."catalog_item_id")))
     LEFT JOIN "inventory"."asset_assignments" "aa" ON ((("aa"."asset_id" = "a"."id") AND ("aa"."returned_at" IS NULL))))
  GROUP BY "a"."tenant_id", "a"."status", "ci"."name"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "inventory"."mv_asset_utilization" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "inventory"."mv_asset_utilization" IS 'Asset status and assignment metrics';



CREATE TABLE IF NOT EXISTS "inventory"."stock_balances" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "catalog_item_id" "uuid" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "qty_on_hand" numeric(18,4) DEFAULT 0 NOT NULL,
    "qty_reserved" numeric(18,4) DEFAULT 0 NOT NULL,
    "qty_available" numeric(18,4) GENERATED ALWAYS AS (("qty_on_hand" - "qty_reserved")) STORED,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    CONSTRAINT "stock_balances_qty_on_hand_check" CHECK (("qty_on_hand" >= (0)::numeric)),
    CONSTRAINT "stock_balances_qty_reserved_check" CHECK (("qty_reserved" >= (0)::numeric))
);


ALTER TABLE "inventory"."stock_balances" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."stock_balances" IS 'Current stock levels per item per location - rebuilt from inventory_events';



COMMENT ON COLUMN "inventory"."stock_balances"."qty_available" IS 'Computed as qty_on_hand - qty_reserved';



CREATE MATERIALIZED VIEW "inventory"."mv_inventory_summary" AS
 SELECT "tenant_id",
    "count"(DISTINCT "catalog_item_id") AS "total_items",
    "count"(DISTINCT "location_id") AS "total_locations",
    "sum"("qty_on_hand") AS "total_qty_on_hand",
    "sum"("qty_reserved") AS "total_qty_reserved",
    "sum"("qty_available") AS "total_qty_available",
    "count"(*) FILTER (WHERE ("qty_available" < (0)::numeric)) AS "negative_balance_count",
    "count"(*) FILTER (WHERE ("qty_available" = (0)::numeric)) AS "zero_balance_count",
    "now"() AS "refreshed_at"
   FROM "inventory"."stock_balances" "sb"
  GROUP BY "tenant_id"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "inventory"."mv_inventory_summary" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "inventory"."mv_inventory_summary" IS 'Pre-aggregated inventory KPIs for fast dashboard loading';



CREATE MATERIALIZED VIEW "inventory"."mv_low_stock_summary" AS
 SELECT "ci"."tenant_id",
    "ci"."id" AS "catalog_item_id",
    "ci"."sku",
    "ci"."name",
    "ci"."min_stock_level",
    "ci"."reorder_point",
    "sum"("sb"."qty_available") AS "total_available",
    "count"("sb"."location_id") AS "location_count",
    "now"() AS "refreshed_at"
   FROM ("inventory"."catalog_items" "ci"
     LEFT JOIN "inventory"."stock_balances" "sb" ON (("sb"."catalog_item_id" = "ci"."id")))
  WHERE (("ci"."deleted_at" IS NULL) AND ("ci"."min_stock_level" IS NOT NULL))
  GROUP BY "ci"."tenant_id", "ci"."id", "ci"."sku", "ci"."name", "ci"."min_stock_level", "ci"."reorder_point"
 HAVING (("sum"("sb"."qty_available") < "ci"."min_stock_level") OR ("sum"("sb"."qty_available") IS NULL))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "inventory"."mv_low_stock_summary" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "inventory"."mv_low_stock_summary" IS 'Items below minimum stock levels requiring attention';



CREATE TABLE IF NOT EXISTS "supply_chain"."purchase_order_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "po_id" "uuid" NOT NULL,
    "line_number" integer NOT NULL,
    "catalog_item_id" "uuid",
    "qty_ordered" numeric(18,4) NOT NULL,
    "qty_received" numeric(18,4) DEFAULT 0 NOT NULL,
    "unit_cost" numeric(18,4),
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "last_event_id" "text" NOT NULL,
    "item_description" "text",
    "item_vendor_sku" "text",
    "unit_of_measure" "text",
    "is_approximate_qty" boolean DEFAULT false,
    "price_basis" "text",
    "estimated_unit_cost" numeric(18,4),
    "line_notes" "text",
    "allow_over_delivery" boolean DEFAULT false,
    CONSTRAINT "chk_line_has_item_reference" CHECK ((("catalog_item_id" IS NOT NULL) OR ("item_description" IS NOT NULL))),
    CONSTRAINT "chk_noncatalog_has_uom" CHECK ((("catalog_item_id" IS NOT NULL) OR ("unit_of_measure" IS NOT NULL))),
    CONSTRAINT "chk_po_line_quantities_with_override" CHECK ((("qty_received" >= (0)::numeric) AND ("qty_ordered" > (0)::numeric) AND (("allow_over_delivery" = true) OR ("qty_received" <= "qty_ordered")))),
    CONSTRAINT "purchase_order_lines_price_basis_check" CHECK (("price_basis" = ANY (ARRAY['fixed'::"text", 'estimated'::"text", 'market'::"text", 'unknown'::"text"]))),
    CONSTRAINT "purchase_order_lines_qty_ordered_check" CHECK (("qty_ordered" > (0)::numeric)),
    CONSTRAINT "purchase_order_lines_qty_received_check" CHECK (("qty_received" >= (0)::numeric)),
    CONSTRAINT "purchase_order_lines_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'partially_received'::"text", 'fully_received'::"text", 'cancelled'::"text", 'pending'::"text"])))
);


ALTER TABLE "supply_chain"."purchase_order_lines" OWNER TO "postgres";


COMMENT ON TABLE "supply_chain"."purchase_order_lines" IS 'Flexible PO line items supporting both catalog and non-catalog items with approximate quantities and variable pricing';



COMMENT ON COLUMN "supply_chain"."purchase_order_lines"."status" IS 'Line status: open/partially_received/fully_received/cancelled';



COMMENT ON COLUMN "supply_chain"."purchase_order_lines"."last_event_id" IS 'Idempotency key for event-driven processing';



COMMENT ON COLUMN "supply_chain"."purchase_order_lines"."item_description" IS 'Free-text description for non-catalog items';



COMMENT ON COLUMN "supply_chain"."purchase_order_lines"."item_vendor_sku" IS 'Vendor SKU/part number (informational only)';



COMMENT ON COLUMN "supply_chain"."purchase_order_lines"."unit_of_measure" IS 'Unit of measure for non-catalog items';



COMMENT ON COLUMN "supply_chain"."purchase_order_lines"."is_approximate_qty" IS 'True if quantity is approximate (~30 tons)';



COMMENT ON COLUMN "supply_chain"."purchase_order_lines"."price_basis" IS 'Fixed, estimated, market pricing, or unknown';



COMMENT ON COLUMN "supply_chain"."purchase_order_lines"."estimated_unit_cost" IS 'Estimated unit cost when exact price unknown';



COMMENT ON COLUMN "supply_chain"."purchase_order_lines"."line_notes" IS 'Line-specific notes (fuel surcharge, backorder ok, etc)';



COMMENT ON COLUMN "supply_chain"."purchase_order_lines"."allow_over_delivery" IS 'If true, allows receiving more than ordered quantity. Used for approximate orders (e.g., gravel by the truckload).';



CREATE OR REPLACE VIEW "inventory"."purchase_order_lines" AS
 SELECT "id",
    "tenant_id",
    "po_id",
    "line_number",
    "catalog_item_id",
    "qty_ordered",
    "qty_received",
    "unit_cost",
    "status",
    "notes",
    "created_at",
    "updated_at",
    "created_by",
    "updated_by",
    "last_event_id"
   FROM "supply_chain"."purchase_order_lines";


ALTER VIEW "inventory"."purchase_order_lines" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."purchase_order_lines" IS 'Compatibility view → supply_chain.purchase_order_lines';



CREATE TABLE IF NOT EXISTS "supply_chain"."purchase_orders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "po_number" "text" NOT NULL,
    "vendor_location_id" "uuid",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "order_date" "date" NOT NULL,
    "expected_delivery_date" "date",
    "delivery_location_id" "uuid",
    "notes" "text",
    "created_by_user_id" "uuid",
    "approved_by_user_id" "uuid",
    "approved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "last_event_id" "text" NOT NULL,
    "vendor_id" "uuid",
    "delivery_method" "text" DEFAULT 'ship'::"text",
    "needed_by_date" "date",
    "cost_context" "text" DEFAULT 'yard'::"text",
    "job_id" "uuid",
    "max_authorized_spend" numeric(18,4),
    "pickup_location_id" "uuid",
    "vendor_quote_ref" "text",
    "sent_at" timestamp with time zone,
    "sent_by_user_id" "uuid",
    "attachments" "jsonb" DEFAULT '[]'::"jsonb",
    "external_order_number" "text",
    "ordered_at" timestamp with time zone,
    "ordered_by_user_id" "uuid",
    "order_placement_method" "text",
    "order_placement_notes" "text",
    "vendor_name_snapshot" "text",
    "vendor_code_snapshot" "text",
    CONSTRAINT "purchase_orders_cost_context_check" CHECK (("cost_context" = ANY (ARRAY['job'::"text", 'yard'::"text", 'overhead'::"text"]))),
    CONSTRAINT "purchase_orders_delivery_method_check" CHECK (("delivery_method" = ANY (ARRAY['ship'::"text", 'pickup'::"text"]))),
    CONSTRAINT "purchase_orders_order_placement_method_check" CHECK (("order_placement_method" = ANY (ARRAY['portal'::"text", 'email'::"text", 'phone'::"text", 'in_person'::"text", 'other'::"text"]))),
    CONSTRAINT "purchase_orders_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'awaiting_approval'::"text", 'approved'::"text", 'placed'::"text", 'acknowledged'::"text", 'partially_received'::"text", 'fully_received'::"text", 'cancelled'::"text", 'closed'::"text"])))
);


ALTER TABLE "supply_chain"."purchase_orders" OWNER TO "postgres";


COMMENT ON TABLE "supply_chain"."purchase_orders" IS 'PO approval and receipt should use SERIALIZABLE isolation to prevent race conditions';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."status" IS 'PO lifecycle: 
  draft - Being created
  awaiting_approval - Needs authorization (optional)
  approved - Authorized, ready to order
  placed - Order placed with vendor (portal/phone/email)
  acknowledged - Vendor confirmed (optional)
  partially_received - Some items received
  fully_received - All items received
  cancelled - Cancelled before completion
  closed - Completed/archived';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."vendor_id" IS 'Reference to vendor (replaces vendor_location_id pattern)';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."delivery_method" IS 'Ship (vendor delivers) or pickup (we pick up)';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."needed_by_date" IS 'When we need the materials (ops planning, not vendor promise)';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."cost_context" IS 'Job, yard stock, or overhead - for cost tracking';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."job_id" IS 'Job/project ID if cost_context = job';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."max_authorized_spend" IS 'Maximum authorized spend (when pricing is unknown/variable)';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."pickup_location_id" IS 'Location for pickup if delivery_method = pickup';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."vendor_quote_ref" IS 'Vendor quote or reference number';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."sent_at" IS 'When PO was sent via EMAIL (if applicable). 
OPTIONAL: Portal-based and card-only vendors may never receive PO email.';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."sent_by_user_id" IS 'User who sent the PO to vendor';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."attachments" IS 'Array of attachment URLs (quotes, screenshots, emails)';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."external_order_number" IS 'Vendor-generated order number (from portal, confirmation email, etc)';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."ordered_at" IS 'When order was placed with vendor (via portal/phone/email).
This is SEPARATE from sent_at. Many orders are placed without sending PO.';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."ordered_by_user_id" IS 'User who placed the external order';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."order_placement_method" IS 'How order was placed with vendor (for traceability)';



COMMENT ON COLUMN "supply_chain"."purchase_orders"."order_placement_notes" IS 'Notes about order placement (cart total, confirmation, issues)';



CREATE OR REPLACE VIEW "inventory"."purchase_orders" AS
 SELECT "id",
    "tenant_id",
    "po_number",
    "vendor_location_id",
    "status",
    "order_date",
    "expected_delivery_date",
    "delivery_location_id",
    "notes",
    "created_by_user_id",
    "approved_by_user_id",
    "approved_at",
    "created_at",
    "updated_at",
    "updated_by",
    "last_event_id",
    "vendor_id",
    "vendor_name_snapshot",
    "vendor_code_snapshot"
   FROM "supply_chain"."purchase_orders";


ALTER VIEW "inventory"."purchase_orders" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "supply_chain"."receipt_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "receipt_id" "uuid" NOT NULL,
    "po_line_id" "uuid",
    "line_number" integer NOT NULL,
    "catalog_item_id" "uuid" NOT NULL,
    "qty_received" numeric(18,4) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "last_event_id" "text" NOT NULL,
    "condition_status" "text" DEFAULT 'accepted'::"text" NOT NULL,
    "destination_location_id" "uuid",
    "unit_cost_actual" numeric(18,4),
    "uom" "text",
    "notes" "text",
    CONSTRAINT "receipt_lines_condition_check" CHECK (("condition_status" = ANY (ARRAY['accepted'::"text", 'damaged'::"text", 'quarantine'::"text", 'rejected'::"text"]))),
    CONSTRAINT "receipt_lines_qty_received_check" CHECK (("qty_received" > (0)::numeric))
);


ALTER TABLE "supply_chain"."receipt_lines" OWNER TO "postgres";


COMMENT ON TABLE "supply_chain"."receipt_lines" IS 'Receipt line items. Individual catalog items received.
  
  Condition status values:
  - accepted: Items in good condition, added to available inventory
  - damaged: Items damaged but may be usable, flagged for inspection
  - quarantine: Items requiring inspection before release
  - rejected: Items not accepted, not added to inventory (return to vendor)';



COMMENT ON COLUMN "supply_chain"."receipt_lines"."condition_status" IS 'Condition of received items: accepted (good), damaged (usable but damaged), quarantine (needs inspection), rejected (not accepted)';



COMMENT ON COLUMN "supply_chain"."receipt_lines"."destination_location_id" IS 'Destination location for this line. If NULL, defaults to receipt.location_id. Enables line-level location splitting.';



COMMENT ON COLUMN "supply_chain"."receipt_lines"."unit_cost_actual" IS 'Actual unit cost from vendor invoice. May differ from PO estimate.';



COMMENT ON COLUMN "supply_chain"."receipt_lines"."uom" IS 'Unit of measure (denormalized from catalog_item for historical accuracy)';



CREATE OR REPLACE VIEW "inventory"."receipt_lines" AS
 SELECT "id",
    "tenant_id",
    "receipt_id",
    "po_line_id",
    "line_number",
    "catalog_item_id",
    "qty_received",
    "created_at",
    "updated_at",
    "created_by",
    "updated_by",
    "last_event_id"
   FROM "supply_chain"."receipt_lines";


ALTER VIEW "inventory"."receipt_lines" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."receipt_lines" IS 'Compatibility view → supply_chain.receipt_lines';



CREATE TABLE IF NOT EXISTS "supply_chain"."receipts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "po_id" "uuid",
    "receipt_number" "text" NOT NULL,
    "received_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "received_by_user_id" "uuid",
    "location_id" "uuid" NOT NULL,
    "last_event_id" "text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "status" "text" DEFAULT 'confirmed'::"text" NOT NULL,
    "vendor_id" "uuid",
    "packing_slip_no" "text",
    "vendor_invoice_no" "text",
    "source_type" "text" DEFAULT 'delivery'::"text",
    "vendor_name_snapshot" "text",
    "vendor_code_snapshot" "text",
    CONSTRAINT "receipts_source_type_check" CHECK (("source_type" = ANY (ARRAY['delivery'::"text", 'pickup'::"text", 'transfer'::"text", 'return'::"text"]))),
    CONSTRAINT "receipts_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'confirmed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "supply_chain"."receipts" OWNER TO "postgres";


COMMENT ON TABLE "supply_chain"."receipts" IS 'Receipt header records. Tracks physical receipt of items from vendors or other sources.
  
  Status values:
  - draft: Receipt created but not yet confirmed/posted to inventory
  - confirmed: Receipt posted to inventory (stock balances updated)
  - cancelled: Receipt cancelled, no inventory impact
  
  Source types:
  - delivery: Vendor delivered items to our location
  - pickup: We picked up items from vendor location
  - transfer: Internal transfer between locations
  - return: Customer/job return';



COMMENT ON COLUMN "supply_chain"."receipts"."last_event_id" IS 'Idempotency key linking to inventory_events';



COMMENT ON COLUMN "supply_chain"."receipts"."status" IS 'Receipt status: draft (not posted), confirmed (posted to inventory), cancelled';



COMMENT ON COLUMN "supply_chain"."receipts"."vendor_id" IS 'Vendor for this receipt. Denormalized from PO or user-selected for quick receives.';



COMMENT ON COLUMN "supply_chain"."receipts"."packing_slip_no" IS 'Vendor packing slip number for matching and auditing';



COMMENT ON COLUMN "supply_chain"."receipts"."vendor_invoice_no" IS 'Vendor invoice number for expense matching';



COMMENT ON COLUMN "supply_chain"."receipts"."source_type" IS 'How items were received: delivery (vendor shipped), pickup (we picked up), transfer (internal), return (customer return)';



CREATE OR REPLACE VIEW "inventory"."receipts" AS
 SELECT "id",
    "tenant_id",
    "po_id",
    "receipt_number",
    "received_at",
    "received_by_user_id",
    "location_id",
    "last_event_id",
    "notes",
    "created_at",
    "updated_at",
    "created_by",
    "updated_by",
    "vendor_id",
    "vendor_name_snapshot",
    "vendor_code_snapshot"
   FROM "supply_chain"."receipts";


ALTER VIEW "inventory"."receipts" OWNER TO "postgres";


