    "asset_id" "uuid",
    "reserved_from" timestamp with time zone,
    "reserved_until" timestamp with time zone,
    "reservation_type" "text" NOT NULL,
    "notes" "text",
    "destination_location_id" "uuid",
    CONSTRAINT "chk_reservation_mode_validity" CHECK (
CASE
    WHEN ("reservation_type" = 'fungible'::"text") THEN (("qty" > (0)::numeric) AND ("catalog_item_id" IS NOT NULL) AND ("location_id" IS NOT NULL) AND ("asset_id" IS NULL))
    WHEN ("reservation_type" = 'serialized'::"text") THEN (("asset_id" IS NOT NULL) AND (("qty" IS NULL) OR ("qty" = (1)::numeric)))
    ELSE false
END),
    CONSTRAINT "reservations_reservation_type_check" CHECK (("reservation_type" = ANY (ARRAY['fungible'::"text", 'serialized'::"text"]))),
    CONSTRAINT "reservations_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'fulfilled'::"text", 'released'::"text", 'expired'::"text"])))
);


ALTER TABLE "inventory"."reservations" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."reservations" IS 'Active reservations/allocations - supports both fungible (qty-based) and serialized (asset-specific) reservations with optional time windows';



COMMENT ON COLUMN "inventory"."reservations"."status" IS 'Reservation state: active/fulfilled/released/expired';



COMMENT ON COLUMN "inventory"."reservations"."fulfilled_by_user_id" IS 'User who fulfilled/issued the reservation';



COMMENT ON COLUMN "inventory"."reservations"."cancelled_by_user_id" IS 'User who cancelled the reservation';



COMMENT ON COLUMN "inventory"."reservations"."expiration_date" IS 'Auto-cancel if not fulfilled by this date';



COMMENT ON COLUMN "inventory"."reservations"."allocation_type" IS 'What the reservation is for (job, project, etc.)';



COMMENT ON COLUMN "inventory"."reservations"."external_order_ref" IS 'External reference (job number, order number, etc.)';



COMMENT ON COLUMN "inventory"."reservations"."asset_id" IS 'For serialized reservations: specific asset being reserved (mutually exclusive with qty > 1)';



COMMENT ON COLUMN "inventory"."reservations"."reserved_from" IS 'Start of reservation time window (nullable for immediate/indefinite reservations)';



COMMENT ON COLUMN "inventory"."reservations"."reserved_until" IS 'End of reservation time window (nullable for indefinite reservations)';



COMMENT ON COLUMN "inventory"."reservations"."reservation_type" IS 'Type of reservation: fungible (qty-based) or serialized (asset-specific)';



COMMENT ON COLUMN "inventory"."reservations"."notes" IS 'Additional context or instructions for this reservation';



COMMENT ON COLUMN "inventory"."reservations"."destination_location_id" IS 'Where the reserved stock/asset is needed or will be staged.';



COMMENT ON CONSTRAINT "chk_reservation_mode_validity" ON "inventory"."reservations" IS 'Enforces mutual exclusivity: fungible reservations use qty + catalog_item_id + location_id; serialized reservations use asset_id';



