CREATE TABLE IF NOT EXISTS "inventory"."rfid_cycle_count_submissions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "device_id" "uuid" NOT NULL,
