    "last_event_id" "text" NOT NULL,
    CONSTRAINT "rfid_cycle_count_submissions_power_mode_used_check" CHECK (("power_mode_used" = ANY (ARRAY['LOW'::"text", 'MED'::"text", 'HIGH'::"text"]))),
    CONSTRAINT "rfid_cycle_count_submissions_status_check" CHECK (("status" = ANY (ARRAY['staged'::"text", 'committed'::"text", 'rejected'::"text", 'superseded'::"text"])))
);


