    CONSTRAINT "rfid_tags_check_assignment" CHECK (((("tag_category" = 'asset_tag'::"text") AND ("asset_id" IS NOT NULL) AND ("bulk_catalog_item_id" IS NULL)) OR (("tag_category" = 'bulk_item_tag'::"text") AND ("bulk_catalog_item_id" IS NOT NULL) AND ("asset_id" IS NULL)) OR (("tag_category" = 'unassigned'::"text") AND ("asset_id" IS NULL) AND ("bulk_catalog_item_id" IS NULL)))),
    CONSTRAINT "rfid_tags_tag_category_check" CHECK (("tag_category" = ANY (ARRAY['asset_tag'::"text", 'bulk_item_tag'::"text", 'unassigned'::"text"])))
);


