    CONSTRAINT "stock_movements_posting_status_check" CHECK (("posting_status" = ANY (ARRAY['posted'::"text", 'reversed'::"text", 'pending'::"text"])))
);


ALTER TABLE "inventory"."stock_movements" OWNER TO "postgres";


