    CONSTRAINT "transfer_lines_qty_check" CHECK (("qty" > (0)::numeric)),
    CONSTRAINT "transfer_lines_qty_received_check" CHECK ((("qty_received" >= (0)::numeric) AND ("qty_received" <= "qty_shipped"))),
