    CONSTRAINT "transfers_different_locations" CHECK (("from_location_id" <> "to_location_id")),
    CONSTRAINT "transfers_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'in_transit'::"text", 'partially_received'::"text", 'completed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "inventory"."transfers" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."transfers" IS 'Transfer operations should use SERIALIZABLE isolation:
    BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
