CREATE TABLE IF NOT EXISTS "public"."dashboards" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "is_default" boolean DEFAULT false NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "scope" "text" DEFAULT 'user'::"text" NOT NULL,
    "owner_user_id" "uuid",
    "role_key" "text",
    "deleted_at" timestamp with time zone,
    "last_event_id" "text" NOT NULL,
    CONSTRAINT "dashboards_scope_check" CHECK (((("scope" = 'role'::"text") AND ("role_key" IS NOT NULL)) OR (("scope" = 'user'::"text") AND ("owner_user_id" IS NOT NULL)) OR ("scope" = 'tenant'::"text"))),
    CONSTRAINT "dashboards_scope_enum_check" CHECK (("scope" = ANY (ARRAY['tenant'::"text", 'role'::"text", 'user'::"text"])))
);


