COMMENT ON COLUMN "public"."dashboards"."owner_user_id" IS 'User ID who owns this dashboard (for scope=user)';



COMMENT ON COLUMN "public"."dashboards"."role_key" IS 'Role key for role-specific dashboards (for scope=role)';



