CREATE OR REPLACE VIEW "supply_chain"."v_vendor_ordering_guidance" AS
 SELECT "id" AS "vendor_id",
    "tenant_id",
    "name" AS "vendor_name",
    "ordering_mode",
    "po_required",
    "accepts_net_terms",
    "default_payment_method",
    "portal_url",
    "phone_number",
    "po_email",
    "notes_for_buyers",
    "requires_external_order_number",
        CASE "ordering_mode"
            WHEN 'email_po'::"supply_chain"."ordering_mode" THEN ('Email PO to: '::"text" || COALESCE("po_email", "contact_email", 'No email on file'::"text"))
            WHEN 'portal_with_po_ref'::"supply_chain"."ordering_mode" THEN (('Order via portal: '::"text" || COALESCE("portal_url", 'No portal URL on file'::"text")) || '
Reference PO # during checkout'::"text")
            WHEN 'phone_with_po_ref'::"supply_chain"."ordering_mode" THEN (('Call: '::"text" || COALESCE("phone_number", 'No phone on file'::"text")) || '
Reference PO # when ordering'::"text")
            WHEN 'card_only_internal_po'::"supply_chain"."ordering_mode" THEN 'Order with company card. PO is for internal tracking only.'::"text"
            WHEN 'pickup_only'::"supply_chain"."ordering_mode" THEN 'In-person pickup. Bring PO or reference PO #.'::"text"
            WHEN 'mixed'::"supply_chain"."ordering_mode" THEN 'Multiple ordering methods available. See notes.'::"text"
            ELSE 'Contact vendor to place order'::"text"
        END AS "ordering_instructions",
        CASE
            WHEN "accepts_net_terms" THEN ('Invoice - '::"text" || COALESCE("payment_terms", 'Net 30'::"text"))
            ELSE 'Card payment required'::"text"
        END AS "payment_guidance",
        CASE
            WHEN "requires_external_order_number" THEN 'External order # required for receiving'::"text"
            ELSE 'Can receive with PO # or external order #'::"text"
        END AS "receiving_notes"
   FROM "supply_chain"."vendors" "v"
  WHERE ("active" = true);


ALTER VIEW "supply_chain"."v_vendor_ordering_guidance" OWNER TO "postgres";


COMMENT ON VIEW "supply_chain"."v_vendor_ordering_guidance" IS 'Provides ordering instructions and guidance per vendor based on their configuration.
Use this to drive UI hints and help users order correctly.';



CREATE OR REPLACE VIEW "supply_chain"."vendor_items_with_catalog" AS
 SELECT "vi"."id",
    "vi"."tenant_id",
    "vi"."vendor_id",
    "vi"."catalog_item_id",
    "vi"."vendor_sku",
    "vi"."vendor_uom",
    "vi"."pack_size",
    "vi"."is_preferred",
    "vi"."unit_cost",
    "vi"."currency",
    "vi"."lead_time_days",
    "vi"."min_order_qty",
    "vi"."notes",
    "vi"."created_at",
    "vi"."updated_at",
    "ci"."id" AS "catalog_item_id_resolved",
    "ci"."sku" AS "catalog_item_sku",
    "ci"."name" AS "catalog_item_name",
    "ci"."description" AS "catalog_item_description"
   FROM ("supply_chain"."vendor_items" "vi"
